MainAPI.Print = function(prefix, ...)
    prefix = (prefix or 'info'):upper()

    if prefix == 'DEBUG' and (not canDebug or not debugOn) then
        return
    end

    local args = {...}

    for i = 1, #args do
        args[i] = tostring(args[i])
    end

    print('[^3BanditMenu^0] [^'..(prefix == 'ERROR' and 1 or prefix == 'INFO' and 5 or prefix == 'WARNING' and 3 or prefix == 'SUCCESS' and 2 or prefix == 'DEBUG' and 3 or 7)..prefix..'^0] '..table.concat(args, ' '))
end

MainAPI.Debug = function(...)
    MainAPI.Print('debug', ...)
end

