-- Local scripts live only in this Lua runtime, never in the cloud.
-- Add scripts as { id = { name = 'Name', code = '...' } } if needed.
_G.BanditLocalData = type(_G.BanditLocalData) == 'table' and _G.BanditLocalData or {}
Utils.LocalData = _G.BanditLocalData
Utils.LocalData.scripts = type(Utils.LocalData.scripts) == 'table' and Utils.LocalData.scripts or {}

Utils.CopyLocalData = function(value)
    if type(value) ~= 'table' then return value end
    local copy = {}
    for key, item in pairs(value) do
        copy[key] = Utils.CopyLocalData(item)
    end
    return copy
end

Utils.GetUserScripts = function()
    return Utils.CopyLocalData(Utils.LocalData.scripts)
end

local userScripts = {}

