local function isResourceRunning(resource)
    local setState = GetResourceState(tostring(resource))
    return (setState == 'started' or setState == 'starting') and MachoResourceInjectable(resource)
end

local commonResource
local commonResources = {
    'es_extended',
    'qb-core',
    'core',
    'ox_lib',
    'ox_inventory',
    'illenium-appearance',
    'chat',
    'oxmysql',
    'monitor'
}

for i = 1, #commonResources do
    local setResource = commonResources[i]

    if isResourceRunning(setResource) then
        commonResource = setResource
        break
    end
end

if not commonResource then
    commonResource = GetResourceByFindIndex(math.random(0, GetNumResources() - 1))
end

