    local resource = GetCurrentResourceName()

    -- MainAPI.Debug('Forced Bypass (AimActive) (^3'..tostring(resource)..'^0)')

    return false, false
end)

HookNative(0xA571D46727E2B718, function(padIndex)
    if padIndex == 0 then
        local resource = GetCurrentResourceName()

        -- MainAPI.Debug('Forced Bypass (UsingKeyboard-'..tostring(padIndex)..') (^3'..tostring(resource)..'^0)')

        return false, false
    end

    return true
end)

HookNative(0x1CEA6BFDF248E5D9, function(padIndex, control)
    if control == 1 or control == 2 then
        local resource = GetCurrentResourceName()

        -- MainAPI.Debug('Forced Bypass (Cntrl-'..padIndex..'-'..control..') (^3'..tostring(resource)..'^0)')

        return false, true
    end

    return true
end)

