local safeLoadedScripts = {}

HookNative(0x0C515FAB3FF9EA92, function(propType, data)
    if menuInjected and propType and data then
        if propType == 'SetClient_LoadedSafeFuncs' then
            safeLoadedScripts[data] = true
        elseif propType == 'MainAPI.Hook' then
            data = json.decode(data)
            
            if data then
                local hookData = data.HookData

                if hookData then
                    local setHook = setHooks[hookData.HookType]

                    if setHook then
                        CreateThread(function()
                            setHook(table.unpack(hookData.SetArgs))
                        end)
                    end
                end
            end
        end
    end

    return true
end)

CreateHook('Print', MainAPI.Print)

local function customThemesTab()
    local setOptions = {
        {
            name = 'Save Current',
            id = 'save_current',
            action = function()
                showInput('Theme Name', 'name', function(setName)
                    setCustomThemes[setName] = {
                        mainColor = setActiveMainColor,
                        backColor = setActiveBackColor,
                        banner = setActiveBanner
                    }
                end)
            end
        },
        {
            name = 'Your Themes',
            separator = true
        }
    }

    local insertThemes = {}

    for themeName, themeData in pairs(setCustomThemes) do
        insertThemes[#insertThemes + 1] = {
            name = themeName,
            id = 'menu_theme_'..themeName,
            submenu = {
                tabs = {
                    {
                        label = 'Manage Theme',
                        id = 'manage_theme',
                        liveOptions = function()
                            return {
                                {
                                    name = 'Set Theme',
                                    id = 'set_theme',
                                    action = function()
                                        if themeData then
                                            setMenuColors(themeData.mainColor, themeData.backColor)
                                            setMenuBanner(themeData.banner)
                                        end
                                    end
                                },
                                {
                                    name = 'Override Theme',
                                    id = 'override_theme',
                                    action = function()
                                        setCustomThemes[themeName] = {
                                            mainColor = setActiveMainColor,
                                            backColor = setActiveBackColor,
                                            banner = setActiveBanner
                                        }
                                    end
                                },
                                {
                                    name = 'Rename Theme',
                                    id = 'rename_theme',
                                    action = function()
                                        if setCustomThemes[themeName] then
                                            showInput('New Theme Name', 'name', function(newThemeName)
                                                setCustomThemes[themeName] = nil

                                                themeName = newThemeName
                                                setCustomThemes[themeName] = themeData
                                            end)
                                        end
                                    end
                                },
                                {
                                    name = 'Delete Theme',
                                    id = 'delete_theme',
                                    action = function()
                                        setCustomThemes[themeName] = nil
                                        themeData = nil
                                        menuAction('Back')
                                    end
                                },
                                {
                                    name = 'Theme Info',
                                    separator = true
                                },
                                {
                                    name = 'Main Color',
                                    button = {
                                        label = themeData and themeData.mainColor or '?'
                                    }
                                },
                                {
                                    name = 'Back Color',
                                    button = {
                                        label = themeData and themeData.backColor or '?'
                                    }
                                },
                                {
                                    name = 'Banner',
                                    button = {
                                        label = themeData and themeData.banner or '?'
                                    }
                                }
                            }
                        end
                    }
                }
            }
        }
    end

    table.sort(insertThemes, function(a, b)
        return a.name:lower() < b.name:lower()
    end)

    for i = 1, #insertThemes do
        setOptions[#setOptions + 1] = insertThemes[i]
    end

    return setOptions
end

local function customMainColorsTab()
    local setOptions = {
        -- {
        --     name = 'Save Current',
        --     id = 'save_current',
        --     action = function()
        --         showInput('Color Name', 'name', function(setName)
        --             setCustomMainColors[setName] = setActiveMainColor
        --         end)
        --     end
        -- },
        {
            name = 'Custom Color',
            id = 'custom_color',
            action = function()
                showInput('Custom Color (Hex Only)', '#FFFFFF', function(colorCode)
                    setMainColor(colorCode)
                end)
            end
        },
        -- {
        --     name = 'Your Colors',
        --     separator = true
        -- }
    }

    local insertColors = {}

    for colorName, colorCode in pairs(setCustomMainColors) do
        insertColors[#insertColors + 1] = {
            name = colorName,
            id = 'menu_color_'..colorName,
            submenu = {
                tabs = {
                    {
                        label = 'Manage Color',
                        id = 'manage_color',
                        liveOptions = function()
                            return {
                                {
                                    name = 'Set Main Color',
                                    id = 'set_main_color',
                                    action = function()
                                        if colorCode then
                                            setMainColor(colorCode)
                                        end
                                    end
                                },
                                {
                                    name = 'Override Color',
                                    id = 'override_color',
                                    action = function()
                                        setCustomMainColors[colorName] = setActiveMainColor
                                    end
                                },
                                {
                                    name = 'Rename Color',
                                    id = 'rename_color',
                                    action = function()
                                        if setCustomMainColors[colorName] then
                                            showInput('New Color Name', 'name', function(newColorName)
                                                setCustomMainColors[colorName] = nil

                                                colorName = newColorName
                                                setCustomMainColors[colorName] = colorCode
                                            end)
                                        end
                                    end
                                },
                                {
                                    name = 'Delete Color',
                                    id = 'delete_color',
                                    action = function()
                                        setCustomMainColors[colorName] = nil
                                        colorCode = nil
                                        menuAction('Back')
                                    end
                                },
                                {
                                    name = 'Color',
                                    button = {
                                        label = colorCode
                                    }
                                }
                            }
                        end
                    }
                }
            }
        }
    end

    table.sort(insertColors, function(a, b)
        return a.name:lower() < b.name:lower()
    end)

    for i = 1, #insertColors do
        setOptions[#setOptions + 1] = insertColors[i]
    end

    return setOptions
end

