                showInput('Custom Color (Hex Only)', '#FFFFFF', function(colorCode)
                    setBackColor(colorCode)
                end)
            end
        },
        {
            name = 'Your Colors',
            separator = true
        }
    }

    local insertColors = {}

    for colorName, colorCode in pairs(setCustomBackColors) do
        insertColors[#insertColors + 1] = {
            name = colorName,
            id = 'menu_color_'..colorName,
            submenu = {
                tabs = {
                    {
                        label = 'Manage Color',
                        id = 'manage_color',
                        liveOptions = function()
                            return {
                                {
                                    name = 'Set Back Color',
                                    id = 'set_back_color',
                                    action = function()
                                        if colorCode then
                                            setBackColor(colorCode)
                                        end
                                    end
                                },
                                {
                                    name = 'Override Color',
                                    id = 'override_color',
                                    action = function()
                                        setCustomBackColors[colorName] = setActiveBackColor
                                    end
                                },
                                {
                                    name = 'Rename Color',
                                    id = 'rename_color',
                                    action = function()
                                        if setCustomBackColors[colorName] then
                                            showInput('New Color Name', 'name', function(newColorName)
                                                setCustomBackColors[colorName] = nil

                                                colorName = newColorName
                                                setCustomBackColors[colorName] = colorCode
                                            end)
                                        end
                                    end
                                },
                                {
                                    name = 'Delete Color',
                                    id = 'delete_color',
                                    action = function()
                                        setCustomBackColors[colorName] = nil
                                        colorCode = nil
                                        menuAction('Back')
                                    end
                                },
                                {
                                    name = 'Color',
                                    button = {
                                        label = colorCode
                                    }
                                }
                            }
                        end
                    }
                }
            }
        }
    end

    table.sort(insertColors, function(a, b)
        return a.name:lower() < b.name:lower()
    end)

    for i = 1, #insertColors do
        setOptions[#setOptions + 1] = insertColors[i]
    end

    return setOptions
end

