local function autoScriptsFinished()
    local allSetWeapons = {
        'weapon_unarmed'
    }

    for i = 1, #gameWeapons do
        allSetWeapons[#allSetWeapons + 1] = gameWeapons[i]
    end

    for i = 1, #addonWeapons do
        allSetWeapons[#allSetWeapons + 1] = addonWeapons[i]
    end

    for i = 1, #allSetWeapons do
        local setWeapon = allSetWeapons[i]
        local weaponHash = type(setWeapon) == 'number' and setWeapon or GetHashKey(setWeapon)

        weaponsByHash[weaponHash] = setWeapon
        weaponsByName[setWeapon] = weaponHash
    end

    -- if not loadedBypasses.ped then
    --     MainAPI.InjectCode(commonResource, [[
