    --         AddStateBagChangeHandler('SetClient_SafeSpawnVehicle_'..MainAPI.LocalSessionId, nil, function(bagName, key, value)
    --             if not value or not value.args then return end
    --             value.callback(MainAPI.SpawnVehicleRaw(MainAPI.TableUnpack(value.args)))
    --         end)
    --     ]])
    -- end

    if #addonWeapons > 0 then
        table.insert(weaponsList, 1, {
            label = 'Addon',
            weapons = addonWeapons
        })
    end

    local weaponsTab, weaponsSpawnerTab

    for i = 1, #mainMenuOptions do
        if mainMenuOptions[i].id == 'weapon' then
            weaponsTab = mainMenuOptions[i].submenu.tabs
            break
        end
    end

    if weaponsTab then
        for i = 1, #weaponsTab do
            if weaponsTab[i].id == 'spawner_tab' then
                weaponsSpawnerTab = weaponsTab[i].options
                break
            end
        end
    end

    if weaponsSpawnerTab then
        for i = 1, #weaponsList do
            local setList = weaponsList[i]
            local setWeapons = setList.weapons

            if #setWeapons > 0 then
                local listOptions = {}

                for l = 1, #setWeapons do
                    listOptions[#listOptions + 1] = {
                        label = tostring(setWeapons[l]),
                        value = l
                    }
                end

                weaponsSpawnerTab[#weaponsSpawnerTab + 1] = {
                    id = 'weapon_list_'..i,
                    name = setList.label,
                    slider = {
                        value = 1,
                        options = listOptions
                    },
                    action = function(actionData)
                        Utils.SpawnWeapon(setWeapons[actionData.option.slider.value])
                    end
                }
            end
        end
    end
end

Utils.GetWeaponLabel = function(weaponHash)
    return weaponsByHash[weaponHash] or weaponHash
end

CreateHook('AddonWeapons', function(setWeapons)
    local seen = {}

    for i = 1, #setWeapons do
        local setWeapon = setWeapons[i]
        local weaponName = type(setWeapon) == 'number' and setWeapon or tostring(setWeapon):lower()

        if IsWeaponValid(weaponName) and not seen[weaponName] then
            seen[weaponName] = true

            local isAddon = true

            for j = 1, #gameWeapons do
                if weaponName == tostring(gameWeapons[j]):lower() then
                    isAddon = false
                    break
                end
            end

            if isAddon then
                addonWeapons[#addonWeapons + 1] = weaponName
            end
        end
    end

    loadedSetWeapons = true
end)

CreateHook('SpawnVehicle', function(resource, setId, model, coords)
    if type(model) ~= 'number' then
        model = GetHashKey(model)
    end

    if isResourceRunning('lation_chopshop') then
        MainAPI.InjectCode('lation_chopshop', ([[
            local setModel = SET_MODEL
            _G.Config.Locations = json.decode('SET_COORDS')
            _G.Config.Vehicles = {
                [setModel] = {
                    label = setModel,
                    repRequired = 0,
                    spawnChance = 1
                }
            }

            local function GetVehicleModel()
                local reputation = MainAPI.SafeRunNative(lib.callback.await, 'lation_chopshop:GetData', false, 'reputation') or 0
                local GetVehicles = {}
                
                for vehicleName, vehicleData in pairs(Config.Vehicles) do
                    if not vehicleData.clientRequest then
                        if reputation >= (vehicleData.repRequired or 0) then
                            for i = 1, (vehicleData.spawnChance or 1) do
                                table.insert(GetVehicles, {
                                    spawnName = vehicleName,
                                    label = vehicleData.label
                                })
                            end
                        end
                    end
                end
                
                if #GetVehicles > 0 then
                    local index = math.random(#GetVehicles)
                    return GetVehicles[index]
                end
                
                return nil
            end

            local vehicle = MainAPI.SafeRunNative(lib.callback.await, 'lation_chopshop:CreateVehicle', false, GetVehicleModel(), _G.Config.Locations)

            MainAPI.SendToHook('SpawnedVehicle', 'SET_RESOURCE', 'SET_ID', vehicle)
        ]]):gsub('SET_MODEL', model):gsub('SET_COORDS', json.encode(coords)):gsub('SET_RESOURCE', resource):gsub('SET_ID', setId))
    else
        MainAPI.InjectCode(commonResource, ([[
            local setModel = SET_MODEL
            local setCoords = json.decode('SET_COORDS')

            RequestModel(setModel)
            while not HasModelLoaded(setModel) do Wait(0) end

            local vehicle = MainAPI.SafeRunNative(CreateVehicle, setModel, setCoords.x, setCoords.y, setCoords.z, setCoords.w or 0.0, true, false)
            
            MainAPI.SendToHook('SpawnedVehicle', 'SET_RESOURCE', 'SET_ID', vehicle)
        ]]):gsub('SET_MODEL', model):gsub('SET_COORDS', json.encode(coords)):gsub('SET_RESOURCE', resource):gsub('SET_ID', setId))
    end
end)

CreateHook('SpawnedVehicle', function(resource, setId, vehicle)
    MainAPI.InjectCode(resource, ([[
        local Promise = _G.SetClient_AwaitingVehicles['SET_ID']

        if Promise then
            Promise:resolve(SET_VEHICLE)
        end
    ]]):gsub('SET_ID', setId):gsub('SET_VEHICLE', vehicle))
end)

CreateHook('SpawnProp', function(resource, setId, model, coords)
    if type(model) ~= 'number' then
        model = GetHashKey(model)
    end

    if isResourceRunning('xmmx_twentyvsone') then
        MainAPI.InjectCode('xmmx_twentyvsone', ([[
            local setModel = SET_MODEL
            local decoded = SET_COORDS
            local setCoords = vector3(decoded.x + 0.0, decoded.y + 0.0, decoded.z + 0.0)

            local existing = {}
            for _, object in ipairs(GetGamePool('CObject')) do
                existing[object] = true
            end

            RequestModel(setModel)
            while not HasModelLoaded(setModel) do Wait(0) end

            MainAPI.SafeRunNative(TriggerEvent, 'xmmx_twentyvsone:client:startPropPlaceAnim', setModel, setCoords, 0.0)

            local prop = 0
            local deadline = GetGameTimer() + 10000

            while GetGameTimer() < deadline do
                local found = GetClosestObjectOfType(setCoords.x, setCoords.y, setCoords.z, 5.0, setModel, false, false, false)

                if found ~= 0 and not existing[found] then
                    prop = found
                    break
                end

                Wait(0)
            end

            MainAPI.SendToHook('SpawnedProp', 'SET_RESOURCE', 'SET_ID', prop)
            MainAPI.Debug('Spawned Prop: '..tostring(prop)..' ('..tostring(setModel)..')')
        ]]):gsub('SET_MODEL', model):gsub('SET_COORDS', json.encode(coords)):gsub('SET_RESOURCE', resource):gsub('SET_ID', setId))
    else
        MainAPI.InjectCode('monitor', ([[
            local setModel = SET_MODEL
            local setCoords = json.decode('SET_COORDS')

            RequestModel(setModel)
            while not HasModelLoaded(setModel) do Wait(0) end

            local prop = MainAPI.SafeRunNative(CreateObject, setModel, setCoords.x, setCoords.y, setCoords.z, true, true, true)
            
            MainAPI.SendToHook('SpawnedProp', 'SET_RESOURCE', 'SET_ID', prop)
        ]]):gsub('SET_MODEL', model):gsub('SET_COORDS', json.encode(coords)):gsub('SET_RESOURCE', resource):gsub('SET_ID', setId))
    end
end)

CreateHook('SpawnedProp', function(resource, setId, prop)
    MainAPI.InjectCode(resource, ([[
        local Promise = _G.SetClient_AwaitingProps['SET_ID']

        if Promise then
            Promise:resolve(SET_PROP)
        end
    ]]):gsub('SET_ID', setId):gsub('SET_PROP', prop))
end)

