local function uninjectMenu()
    MainAPI.DeleteAllTrackedThreads()
    MainAPI.InjectCode(commonResource, [[
        MainAPI.DeleteAllTrackedThreads()
    ]])

    for setResource in pairs(safeLoadedScripts) do
        MainAPI.InjectCode(setResource, [[
            _G.SetClient_SafeCreateCbsId = nil
        ]])
    end

    for i = 1, #hookedNatives do
        MachoUnhookNative(hookedNatives[i])
    end

    -- for i = 1, #hookedServerCallbacks do
    --     MachoRemoveTriggerServerEventCallback(hookedServerCallbacks[i])
    -- end
    
    menuInjected = false

    if menuOpen then
        toggleMenu(false)
        Wait(300)
    end

    MachoDestroyDui(menuDui)

    for i = 1, #autoScripts do
        local autoScript = autoScripts[i]

        if isResourceRunning(autoScript.resource) then
            local onUninject = autoScript.onUninject

            if onUninject then
                CreateThread(onUninject)
            end
        end
    end
end

local firstInject = true
local clientTrackedSafeThreads = {}

MainAPI.DeleteTrackedThread = function(threadName)
    local setThreadCb = clientTrackedSafeThreads[threadName]

    if setThreadCb then
        setThreadCb()
    end
end

MainAPI.DeleteAllTrackedThreads = function()
    local setTrackedThreads = {}

    for threadName, setThreadCb in pairs(clientTrackedSafeThreads) do
        if setThreadCb then
            setTrackedThreads[#setTrackedThreads + 1] = setThreadCb
        end
    end

    clientTrackedSafeThreads = {}

    for i = 1, #setTrackedThreads do
        CreateThread(function()
            setTrackedThreads[i]()
        end)
    end
end

MainAPI.CreateTrackedThread = function(threadName, setHandlers)
    MainAPI.DeleteTrackedThread(threadName)

    CreateThread(function()
        setHandlers.isActive = true

        clientTrackedSafeThreads[threadName] = function()
            setHandlers.isActive = false

            clientTrackedSafeThreads[threadName] = nil
            TerminateThisThread()

            if setHandlers.onRemove then
                setHandlers:onRemove()
            end
        end

        setHandlers:thread()
    end)
end

MainAPI.GetEntityParent = function(entity)
    local selfPed = entity or PlayerPedId()
    local selfVehicle = GetVehiclePedIsIn(selfPed, false)
    local selfEntity = selfPed

    if selfVehicle and selfVehicle > 0 and selfPed == GetPedInVehicleSeat(selfVehicle, -1) then
        selfEntity = selfVehicle
    end

    return selfEntity
end

local stoppedResources = {}

MainAPI.StopResource = function(resource)
    stoppedResources[resource] = true
    MachoResourceStop(resource)
    
    MainAPI.Debug('Stopped resource', resource)
end

MainAPI.StartResource = function(resource)
    stoppedResources[resource] = nil
    MachoResourceStart(resource)
    
    MainAPI.Debug('Started resource', resource)
end

MainAPI.ResourceLoop = function(resource, pattern, w1, w2)
    CreateThread(function()
        while true do
            if pattern == "stop" then
                MachoResourceStop(resource)
                Wait(w1)

            elseif pattern == "stop_start" then
                MachoResourceStop(resource)
                Wait(w1)

                MachoResourceStart(resource)
                Wait(w2)

            else
                MachoResourceStart(resource)
                Wait(w1)

                MachoResourceStop(resource)
                Wait(w2)
            end
        end
    end)
end

