        MainAPI.TableUnpack = table.unpack

        MainAPI.AntiCheats = json.decode('FOUND_ANTICHEATS')
        
        MainAPI.IsAntiCheatStarted = function(name)
            for i = 1, #MainAPI.AntiCheats do
                if MainAPI.AntiCheats[i] == name then
                    return true
                end
            end

            return false
        end

        MainAPI.EXT_FUNCREF = 10

        MainAPI.PackValueExt = function(tag, data)
            local len = #data

            if len == 1 then
                return MainAPI.StringChar(0xD4, tag)..data
            elseif len == 2 then
                return MainAPI.StringChar(0xD5, tag)..data
            elseif len == 4 then
                return MainAPI.StringChar(0xD6, tag)..data
            elseif len == 8 then
                return MainAPI.StringChar(0xD7, tag)..data
            elseif len == 16 then
                return MainAPI.StringChar(0xD8, tag)..data
            elseif len <= 255 then
                return MainAPI.StringChar(0xC7, len, tag)..data
            elseif len <= 65535 then
                return MainAPI.StringChar(0xC8, math.floor(len / 256), len % 256, tag)..data
            end
        end

        MainAPI.PackValue = function(val)
            local t = val ~= nil and type(val)

            if val == nil then
                return MainAPI.StringChar(0xC0)
            elseif t == 'boolean' then
                return MainAPI.StringChar(val and 0xC3 or 0xC2)
            elseif t == 'number' then
                if val % 1 == 0 then
                    if val >= 0 and val <= 127 then
                        return MainAPI.StringChar(val)
                    elseif val < 0 and val >= -32 then
                        return MainAPI.StringChar(0x100 + val)
                    elseif val >= 0 and val <= 0xFF then
                        return MainAPI.StringChar(0xCC, val)
                    elseif val >= 0 and val <= 0xFFFF then
                        return MainAPI.StringChar(0xCD, math.floor(val / 256), val % 256)
                    elseif val >= -128 and val < 0 then
                        return MainAPI.StringChar(0xD0, 0x100 + val)
                    elseif val >= -32768 and val < 0 then
                        local v = 0x10000 + val
                        return MainAPI.StringChar(0xD1, math.floor(v / 256), v % 256)
                    end
                end

                local buf = string.pack('>d', val)

                return MainAPI.StringChar(0xCB) .. buf
            elseif t == 'string' then
                local len = #val

                if len <= 31 then
                    return MainAPI.StringChar(0xA0 + len) .. val
                elseif len <= 255 then
                    return MainAPI.StringChar(0xD9, len) .. val
                elseif len <= 65535 then
                    return MainAPI.StringChar(0xDA, math.floor(len / 256), len % 256) .. val
                end
            elseif t == 'function' then
                local ref = Citizen.GetFunctionReference(val)

                if ref then
                    return MainAPI.PackValueExt(MainAPI.EXT_FUNCREF, ref)
                else
                    error('Cannot pack non-referenced function')
                end
            elseif t == 'table' then
                local cfxRef = rawget(val, '__cfx_functionReference')
                if cfxRef then
                    local ref = Citizen.GetFunctionReference(val)
                    if ref then
                        return MainAPI.PackValueExt(MainAPI.EXT_FUNCREF, ref)
                    end
                end

                local n = #val
                local header

                if n <= 15 then
                    header = MainAPI.StringChar(0x90 + n)
                elseif n <= 65535 then
                    header = MainAPI.StringChar(0xDC, math.floor(n / 256), n % 256)
                end

                local parts = {
                    header
                }

                for i = 1, n do
                    parts[#parts + 1] = MainAPI.PackValue(val[i])
                end

                return table.concat(parts)
            end
        end

        MainAPI.RawSafeRunNative = function(native, ...)
            local funcRef = msgpack.unpack(MainAPI.PackValue(native))

            return funcRef(...)
        end

        MainAPI.SetSafeStateBag = function(bag, key, value, synced)
            if value == nil then
                return
            end

            local payload = MainAPI.PackValue(value)
            if payload == nil then
                return
            end

            MainAPI.RawSafeRunNative(SetStateBagValue, bag, key, payload, #payload, synced)
        end

