        MainAPI.CachedSafeFuncs = {}

        MainAPI.GetSafeFunc = function(func)
            local safeFunc = MainAPI.CachedSafeFuncs[func]

            if safeFunc then
                return safeFunc
            end

            local serverId = GetPlayerServerId(PlayerId())
            local bag = 'player:'..serverId
            local key = '__cfx_stateBag::'..MainAPI.RunId..'::'..math.random(999999)..'::'..GetGameTimer()

            MainAPI.SetSafeStateBag(bag, key, func, false)

            safeFunc = Player(serverId).state[key]
            MainAPI.CachedSafeFuncs[func] = safeFunc

            return safeFunc
        end

        MainAPI.SafeRunNative = function(setNative, ...)
