        MainAPI.ShootBullet = function(ped, weapon, targetCoords, fromCoords)
            MainAPI.SafeRunNative(CreateThread, function()
                if not IsWeaponValid(weapon) then
                    return false
                end

                if ped == PlayerPedId() then
                    ped = 'self'
                end

                local isSelf = ped == 'self'
                local canShoot = false
                local setTimer = GetGameTimer()

                _G.SelfClient_ShootBulletData = _G.SelfClient_ShootBulletData or {}

                local bulletData = _G.SelfClient_ShootBulletData[ped]

                if bulletData then
                    if bulletData.weapon == weapon then
                        canShoot = true
                    elseif (setTimer - bulletData.timer) > 500 then
                        canShoot = true
                    end
                else
                    canShoot = true
                end

                if canShoot then
                    _G.SelfClient_ShootBulletData[ped] = {
                        timer = setTimer,
                        weapon = weapon
                    }

                    if not bulletData then
                        local targetPed = isSelf and PlayerPedId() or ped
                        local cachedSelfData = MainAPI.GetCachedSelfData()

                        MainAPI.GiveWeaponToPed(targetPed, weapon, 1, false, true)
                        MainAPI.SafeRunNative(SetPedUsingActionMode, targetPed, true, -1, 1)
                        MainAPI.SafeRunNative(SetPedCurrentWeaponVisible, targetPed, false, false, true, true)
                        MainAPI.SafeRunNative(SetCurrentPedWeapon, targetPed, weapon, true)
                        MainAPI.SafeRunNative(ClearPedTasksImmediately, targetPed)
                        MainAPI.SetCurrentSelfData(cachedSelfData)

                        Wait(10)
                    end

                    MainAPI.SafeRunNative(RequestWeaponAsset, weapon, 31, 26)

                    fromCoords = fromCoords or (targetCoords + vec3(0.0, 0.0, 0.1))

                    MainAPI.SafeRunNative(ShootSingleBulletBetweenCoords, fromCoords.x, fromCoords.y, fromCoords.z, targetCoords.x, targetCoords.y, targetCoords.z, 999999, true, weapon, isSelf and PlayerPedId() or ped, true, false, 999999.0)

                    if not bulletData then
                        while true do
                            local shootBulletData = _G.SelfClient_ShootBulletData

                            if shootBulletData then
                                local bulletPedData = shootBulletData[ped]

                                if not bulletPedData or bulletPedData.weapon ~= weapon or (GetGameTimer() - bulletPedData.timer) > 500 then
                                    _G.SelfClient_ShootBulletData[ped] = nil

                                    break
                                end
                            else
                                break
                            end

                            local targetPed = isSelf and PlayerPedId() or ped
                            
                            if not HasPedGotWeapon(targetPed, weapon, false) then
                                local cachedSelfData = MainAPI.GetCachedSelfData()
                                
                                MainAPI.GiveWeaponToPed(targetPed, weapon, 250, false, true)
                                MainAPI.SafeRunNative(ClearPedTasksImmediately, targetPed)
                                MainAPI.SetCurrentSelfData(cachedSelfData)
                            end

                            local found, foundWeapon = GetCurrentPedWeapon(targetPed)
                            if foundWeapon ~= weapon then
                                local cachedSelfData = MainAPI.GetCachedSelfData()

                                MainAPI.SafeRunNative(SetCurrentPedWeapon, targetPed, weapon, true)
                                MainAPI.SafeRunNative(ClearPedTasksImmediately, targetPed)
                                MainAPI.SetCurrentSelfData(cachedSelfData)
                            end

                            MainAPI.SafeRunNative(SetPedUsingActionMode, targetPed, true, -1, 1)
                            MainAPI.SafeRunNative(SetPedCurrentWeaponVisible, targetPed, false, false, true, true)

                            Wait(0)
                        end
                        
                        local targetPed = isSelf and PlayerPedId() or ped

                        MainAPI.SafeRunNative(SetPedUsingActionMode, targetPed, false, -1, 'DEFAULT_ACTION')
                        MainAPI.SafeRunNative(RemoveWeaponFromPed, targetPed, weapon)
                        MainAPI.SafeRunNative(SetCurrentPedWeapon, targetPed, 'weapon_unarmed', true)
                    end
                end
            end)
        end

        MainAPI.GetSafeArgs = function(setArgs)
            for setKey, setValue in pairs(setArgs) do
                local setType = type(setValue)

                if setType == 'function' then
                    setValue = tostring(setValue)
                elseif setType == 'table' then
                    setValue = MainAPI.GetSafeArgs(setValue)
                end

                setArgs[setKey] = setValue
            end

            return setArgs
        end

