        _G.SetClient_AwaitingProps = _G.SetClient_AwaitingProps or {}
        _G.SetClient_SpawnHistory = _G.SetClient_SpawnHistory or {}
        _G.SetClient_SpawnCooldownUntil = _G.SetClient_SpawnCooldownUntil or 0

        MainAPI.SpawnObject = function(model, ...)
            if MainAPI.IsAntiCheatStarted('WaveShield') then
                local now = GetGameTimer()

                if now < _G.SetClient_SpawnCooldownUntil then
                    MainAPI.ShowNotification('Error', 'Ban Prevention', ('Wait %.1f seconds before spawning objects again.'):format((_G.SetClient_SpawnCooldownUntil - now) / 1000))
                    return nil
                end

                for i = #_G.SetClient_SpawnHistory, 1, -1 do
                    if (now - _G.SetClient_SpawnHistory[i]) > 3000 then
                        table.remove(_G.SetClient_SpawnHistory, i)
                    end
                end

                _G.SetClient_SpawnHistory[#_G.SetClient_SpawnHistory + 1] = now

                if #_G.SetClient_SpawnHistory >= 3 then
                    _G.SetClient_SpawnCooldownUntil = now + 7000
                    _G.SetClient_SpawnHistory = {}

                    -- MainAPI.Debug('RATE LIMIT TRIGGED FOR 7 SECONDS')
                    return nil
                end
            end

            local Promise = promise.new()

            MainAPI.LoadModel(model)

            local setId = GetGameTimer() .. '_' .. math.random(9999999)

            MainAPI.SendToHook('SpawnProp', MainAPI.CurrentResource, setId, model, ...)

            _G.SetClient_AwaitingProps[setId] = Promise

            local object = Citizen.Await(Promise)

            if not object or object <= 0 then
                MainAPI.Debug('Failed to spawn object', object, model)
            end

            return object
        end

