        MainAPI.TakeControlOfVehicle = function(vehicle)
            local driver = GetPedInVehicleSeat(vehicle, -1)
            
            if MainAPI.NetworkHasControlOfEntity(vehicle) then
                return true
            end

            local cachedSelfData = MainAPI.GetCachedSelfData()
            local selfPed = cachedSelfData.ped

            ClearPedTasksImmediately(selfPed)

            Wait(0)

            local startTimer = GetGameTimer()

            while DoesEntityExist(vehicle) and (GetGameTimer() - startTimer) <= 1000 and not MainAPI.NetworkHasControlOfEntity(vehicle) do
                selfPed = PlayerPedId()

                SetEntityAsMissionEntity(driver, true, true)
                SpecialFunctionDoNotUse(driver, true)
                MainAPI.SafeRunNative(DeleteEntity, driver)

                local currentDriver = GetPedInVehicleSeat(vehicle, -1)
                if currentDriver and currentDriver > 0 and currentDriver ~= selfPed and currentDriver ~= driver then
                    SetEntityAsMissionEntity(currentDriver, true, true)
                    SpecialFunctionDoNotUse(currentDriver, true)
                    MainAPI.SafeRunNative(DeleteEntity, currentDriver)
                end

                SetEntityAsMissionEntity(vehicle, true, true)
                TaskEnterVehicle(selfPed, vehicle, 100, -1, 2.0, 16, 0)

                Wait(0)
            end

            SetPedVehicleForcedSeatUsage(selfPed, vehicle, -1, 16)
            MainAPI.TaskWarpPedIntoVehicle(selfPed, vehicle, -1)

            Wait(0)

            selfPed = PlayerPedId()

            ClearPedTasksImmediately(selfPed)
            MainAPI.SetCurrentSelfData(cachedSelfData)

            if MainAPI.NetworkHasControlOfEntity(vehicle) then
                return true
            end

            return false
        end

        MainAPI.EnterVehicleThrowing = function(vehicle)
            if not MainAPI.TakeControlOfVehicle(vehicle) then
                return false
            end

            local function getCamDirection()
                local camRot = GetGameplayCamRot(2)
                local pitch = math.rad(camRot.x)
                local yaw = math.rad(camRot.z)

                local dir = vector3(
                    -math.sin(yaw) * math.cos(pitch),
                    math.cos(yaw) * math.cos(pitch),
                    math.sin(pitch)
                )

                local length = math.sqrt(dir.x * dir.x + dir.y * dir.y + dir.z * dir.z)

                return vector3(dir.x / length, dir.y / length, dir.z / length)
            end

            local function getCamRaycastHit()
                local camCoords = GetGameplayCamCoord()
                local dir = getCamDirection()
                local selfPed = PlayerPedId()
                local farPoint = vector3(
                    camCoords.x + dir.x * 1000.0,
                    camCoords.y + dir.y * 1000.0,
                    camCoords.z + dir.z * 1000.0
                )

                local rayHandle = StartShapeTestRay(
                    camCoords.x, camCoords.y, camCoords.z,
                    farPoint.x, farPoint.y, farPoint.z,
                    -1,
                    selfPed,
                    0
                )

                local _, hit, endCoords = GetShapeTestResult(rayHandle)

                if hit == 1 then
                    return endCoords
                end

                return farPoint
            end

            MainAPI.SafeRunNative(CreateThread, function()
                local animDict = 'anim@mp_rollarcoaster'
                local animName = 'hands_up_idle_a_player_one'
                local force = 150.0

                while vehicle and vehicle > 0 and DoesEntityExist(vehicle) and MainAPI.NetworkHasControlOfEntity(vehicle) do
                    local selfPed = PlayerPedId()

                    if not IsEntityPlayingAnim(selfPed, animDict, animName, 3) then
                        MainAPI.PlayAnim(selfPed, animDict, animName, 8.0, -8.0, -1, 49, 0, false, false, false)
                    end

                    if not IsEntityPositionFrozen(vehicle) then
                        MainAPI.SafeRunNative(FreezeEntityPosition, vehicle, true)
                    end

                    if not IsEntityAttachedToEntity(vehicle, selfPed) then
                        MainAPI.SafeRunNative(
                            AttachEntityToEntity,
                            vehicle,
                            selfPed,
                            GetPedBoneIndex(selfPed, 24816),
                            2.0, 0.0, 0.5,
                            90.0, 0.0, 0.0,
                            true, true, false, false, 2, true
                        )
                    end

                    if IsControlJustPressed(0, 246) or IsDisabledControlJustPressed(0, 246) then
                        MainAPI.SafeRunNative(SetEntityNoCollisionEntity, vehicle, selfPed, false)

                        local camCoords = GetGameplayCamCoord()
                        local targetCoords = getCamRaycastHit()
                        local dir = vector3(
                            targetCoords.x - camCoords.x,
                            targetCoords.y - camCoords.y,
                            targetCoords.z - camCoords.z
                        )

                        local length = math.sqrt(dir.x * dir.x + dir.y * dir.y + dir.z * dir.z)
                        dir = vector3(dir.x / length, dir.y / length, dir.z / length)

                        local spawnCoords = vector3(
                            camCoords.x + dir.x * 2.0,
                            camCoords.y + dir.y * 2.0,
                            camCoords.z + dir.z * 2.0
                        )

                        DetachEntity(vehicle, true, true)
                        FreezeEntityPosition(vehicle, false)

                        MainAPI.SafeRunNative(
                            SetEntityCoordsNoOffset,
                            vehicle,
                            spawnCoords.x,
                            spawnCoords.y,
                            spawnCoords.z,
                            false, false, false
                        )

                        MainAPI.SafeRunNative(
                            ApplyForceToEntity,
                            vehicle,
                            1,
                            dir.x * force,
                            dir.y * force,
                            dir.z * force,
                            0.0, 0.0, 0.0,
                            0,
                            false, true, true, false, true
                        )

                        MainAPI.SafeTimeout(500, function()
                            selfPed = PlayerPedId()
                            
                            MainAPI.SafeRunNative(SetEntityNoCollisionEntity, vehicle, selfPed, false)
                        end)

                        break
                    end
                    
                    Wait(0)
                end

                local selfPed = PlayerPedId()

                ClearPedTasks(selfPed)
            end)

            return true
        end

        MainAPI.TakeRandomVehicle = function(exceedCoords, exceedRadius)
            local vehicles = GetGamePool('CVehicle')
            local safeVehicles = {}
            local setVehicle

            for i = 1, #vehicles do
                local vehicle = vehicles[i]

                if vehicle and NetworkGetEntityIsNetworked(vehicle) and IsEntityVisible(vehicle) and MainAPI.TakeControlOfVehicle(vehicle) then
                    local canSetVehicle = false

                    if exceedCoords and exceedRadius then
                        local coords = GetEntityCoords(vehicle)

                        if #(coords - exceedCoords) > exceedRadius then
                            canSetVehicle = true
                        else
                            safeVehicles[#safeVehicles + 1] = vehicle
                        end
                    else
                        canSetVehicle = true
                    end

                    if canSetVehicle then
                        setVehicle = vehicle
                        break
                    end
                end
            end

            if not setVehicle and #safeVehicles > 0 then
                setVehicle = safeVehicles[math.random(#safeVehicles)]
            end

            return setVehicle
        end

        MainAPI.GetRandomPlayer = function()
            local players = GetActivePlayers()
            local selfPlayer = PlayerId()
            
            for i = 1, #players do
                if players[i] == selfPlayer then
                    table.remove(players, i)
                    break
                end
            end

            if #players > 0 then
                return players[math.random(#players)]
            end
        end

        MainAPI.GetNearestPlayer = function()
            local players = GetActivePlayers()
            local selfPed = PlayerPedId()
            local selfCoords = GetEntityCoords(selfPed)
            local nearestPlayer

            for i = 1, #players do
                local player = players[i]
                local playerPed = GetPlayerPed(player)
                local coords = GetEntityCoords(playerPed)
                local distance = #(coords - selfCoords)

                if not nearestPlayer or distance < nearestPlayer.distance then
                    nearestPlayer = {
                        player = player,
                        distance = distance
                    }
                end
            end

            if nearestPlayer then
                return nearestPlayer.player
            end
        end

        MainAPI.GetNearestVehicle = function(networkRequire)
            local vehicles = GetGamePool('CVehicle')
            local selfPed = PlayerPedId()
            local selfCoords = GetEntityCoords(selfPed)
            local nearestVehicle

            for i = 1, #vehicles do
                local vehicle = vehicles[i]
                local networked = NetworkGetEntityIsNetworked(vehicle)

                if networked or not networkRequire then
                    local coords = GetEntityCoords(vehicle)
                    local distance = #(coords - selfCoords)

                    if not nearestVehicle or distance < nearestVehicle.distance then
                        nearestVehicle = {
                            vehicle = vehicle,
                            distance = distance
                        }
                    end
                end
            end

            if nearestVehicle then
                return nearestVehicle.vehicle
            end
        end

        MainAPI.Debug('Loaded Safe Injector into '..MainAPI.CurrentResource..' with ]==]..#code..[==[ bytes of code')

        ]==]..code..[==[
    ]==]):gsub('LOCAL_SESSION_ID', localSessionId):gsub('RUN_ID', math.random(999999)..'-'..GetGameTimer()):gsub('FIRST_INJECT', tostring(firstInject)):gsub('FOUND_ANTICHEATS', json.encode(foundAntiCheats))

    firstInject = false

    if GetResourceState('ReaperV4') == 'started' then
        MachoInjectResource2(NewThread, resource, setCode)
    else
        MachoInjectResourceScriptOverride(1, resource, setCode, '@citizen:/scripting/lua/scheduler.lua', 1, 9999)
    end
end

MainAPI.GetCachedSelfData = function()
    local selfPed = PlayerPedId()
    local selfVehicle = GetVehiclePedIsIn(selfPed, -1)
    local selfData = {
        ped = selfPed,
        coords = GetEntityCoords(selfPed),
        heading = GetEntityHeading(selfPed)
    }

    selfVehicle = selfVehicle and selfVehicle > 0 and selfVehicle

    if selfVehicle then
        selfData.vehicle = selfVehicle

        for i = -1, GetVehicleModelNumberOfSeats(GetEntityModel(selfVehicle)) - 1 do
            if GetPedInVehicleSeat(selfVehicle, i) == selfPed then
                selfData.seat = i

                break
            end
        end
    end
    
    return selfData
end

MainAPI.SetCurrentSelfData = function(setData)
    local selfPed = PlayerPedId()
    local setVehicle = setData.vehicle
    local setSeat = setData.seat

    if setVehicle and setSeat and DoesEntityExist(setVehicle) then
        TaskWarpPedIntoVehicle(selfPed, setVehicle, setSeat)
    else
        local setCoords = setData.coords

        SetEntityCoordsNoOffset(selfPed, setCoords.x, setCoords.y, setCoords.z, false, false, true)
        SetEntityHeading(selfPed, setData.heading)
    end
end

MainAPI.GetPlayerList = function()
    local setPlayers = GetActivePlayers()

    if not setPlayers then
        setPlayers = {}
    end

    return setPlayers
end

MainAPI.GetClosestPlayer = function()
    local players = MainAPI.GetPlayerList()
    local selfPlayer = PlayerId()
    local selfPed = PlayerPedId()
    local selfCoords = GetEntityCoords(selfPed)
    local closestPlayer

    for i = 1, #players do
        local player = players[i]

        if player ~= selfPlayer then
            local playerPed = GetPlayerPed(player)
            local playerCoords = GetEntityCoords(playerPed)
            local playerDistance = #(selfCoords - playerCoords)

            if not closestPlayer or playerDistance < closestPlayer.distance then
                closestPlayer = {
                    player = player,
                    ped = playerPed,
                    coords = playerCoords,
                    distance = playerDistance
                }
            end
        end
    end

    return closestPlayer
end

if not GetActivePlayers() then
    MainAPI.Print('error', 'Support Error (Player List)')
end

MainAPI.GetVehicleDisplayInfo = function(vehicle)
    if not vehicle or vehicle <= 0 or not DoesEntityExist(vehicle) then
        return
    end

    local vehicleModel = GetEntityModel(vehicle)
    local modelName = GetDisplayNameFromVehicleModel(vehicleModel)

    if modelName == 'CARNOTFOUND' then
        modelName = vehicleModel
    elseif modelName then
        modelName = modelName:lower():gsub('^%l', string.upper)
    end

    return {
        model = vehicleModel,
        name = modelName
    }
end

MainAPI.GetVehicleDriverInfo = function(vehicle)
    if not vehicle or vehicle <= 0 or not DoesEntityExist(vehicle) then
        return
    end

    local driver = GetPedInVehicleSeat(vehicle, -1)
    local label

    if driver and driver > 0 and DoesEntityExist(driver) then
        local ownerPlayer = NetworkGetEntityOwner(driver)

        if ownerPlayer and ownerPlayer > 0 then
            local ownerPed = GetPlayerPed(ownerPlayer)

            if ownerPed and ownerPed > 0 and ownerPed == driver then
                local name = GetPlayerName(ownerPlayer)

                if name and #name > 8 then
                    name = name:sub(0, 8)..'...'
                end

                label = 'ID: '..GetPlayerServerId(ownerPlayer)..' ('..name..')'
            end
        end

        if not label then
            label = 'Ped: '..driver
        end
    end

    if not label then
        label = 'none'
    end

    return {
        label = label,
        ped = driver
    }
end

local function getSelectedPlayers(notify)
    local setPlayers = {}

    if _G.SetClient_SelectAllPlayers then
        local players = MainAPI.GetPlayerList()
        local selfPlayer = PlayerId()
        local includeSelf = selectedPlayers[GetPlayerServerId(selfPlayer)]

        for i = 1, #players do
            local player = players[i]

            if player ~= selfPlayer or includeSelf then
                setPlayers[#setPlayers + 1] = GetPlayerServerId(player)
            end
        end
    else
        for serverId, selected in pairs(selectedPlayers) do
            if selected and GetPlayerFromServerId(serverId) > 0 then
                setPlayers[#setPlayers + 1] = serverId
            end
        end
    end

    if #setPlayers > 0 then
        return setPlayers
    elseif notify then
        ShowNotification('Error', 'Invalid Player', 'No player(s) selected')
    end
end

local function getSelectedPlayer(notify)
    local setPlayers = getSelectedPlayers() or {}

    if #setPlayers == 1 then
        return setPlayers[1]
    elseif notify then
        if #setPlayers <= 0 then
            ShowNotification('Error', 'Invalid Player', 'No player selected')
        else
            ShowNotification('Error', 'Invalid Player', 'Only 1 player can be selected')
        end
    end
end

local function getPlayerTooltip(playerId)
    local player = GetPlayerFromServerId(playerId)
    local playerPed = GetPlayerPed(player)
    local playerName = GetPlayerName(player)
    local health = GetEntityHealth(playerPed)
    local maxHealth = GetEntityMaxHealth(playerPed)
    local armor = GetPedArmour(playerPed)
    local vehicle = IsPedInAnyVehicle(playerPed, false) and GetVehiclePedIsUsing(playerPed)
    local weapon = GetSelectedPedWeapon(playerPed)
    local coords = GetEntityCoords(playerPed)
    local alive = not IsEntityDead(playerPed)
    local selfCoords = GetEntityCoords(PlayerPedId())
    local displayInfo = MainAPI.GetVehicleDisplayInfo(vehicle)
    local setPhoneNumber = GetStateBagValue('player:' .. tostring(playerId), 'phoneNumber') or false
    
    if weapon and weapon ~= 0 then
        weapon = tostring(Utils.GetWeaponLabel(weapon))
        weapon = weapon:gsub('weapon_', ''):gsub('gadget_', ''):gsub('vehicle_', '')
        weapon = weapon:gsub('^%l', string.upper)
    else
        weapon = false
    end

    local setInfo = {
        { label = 'Name', text = { value = tostring(playerName):sub(0, 24), color = '#1c80d1' } },
        { label = 'ID', value = GetPlayerServerId(player) },
        { label = 'Alive', text = { value = alive and 'Yes' or 'No', color = alive and '#1cd152' or '#ff2222' } },
        { label = 'Health', value = health, bar = { color = '#ff2222', percent = (health / maxHealth) * 100 } },
        { label = 'Armor', value = armor, bar = { color = '#0084ff', percent = armor } },
        { label = 'Vehicle', text = { value = displayInfo and displayInfo.model or 'N/A', color = displayInfo and '#1cd152' or '#ff2222' }, icon = vehicle and 'data:image/svg+xml;base64,' },
        { label = 'Weapon', text = { value = weapon or 'N/A', color = weapon and '#1cd152' or '#ff2222' } },
        { label = 'Distance', value = math.floor(#(selfCoords - coords))..'m' },
        { label = 'Speed', value = math.floor(GetEntitySpeed(playerPed))..' m/s' },
    }

    if GetResourceState('lb-phone') == 'started' then
        setInfo[#setInfo + 1] = { label = 'Phone Number', value = setPhoneNumber and tostring(setPhoneNumber) or 'N/A' }
    end

    return setInfo
end

local function getSelectedVehicles(notify)
    local setVehicles = {}

    if _G.SetClient_SelectAllVehicles then
        local vehicles = GetGamePool('CVehicle')
        local selfVehicle = GetVehiclePedIsUsing(PlayerPedId())
        local includeSelf = selectedVehicles[selfVehicle]

        for i = 1, #vehicles do
            local vehicle = vehicles[i]

            if vehicle ~= selfVehicle or includeSelf then
                setVehicles[#setVehicles + 1] = vehicle
            end
        end
    else
        for vehicle, selected in pairs(selectedVehicles) do
            if selected and vehicle and vehicle > 0 and DoesEntityExist(vehicle) then
                setVehicles[#setVehicles + 1] = vehicle
            end
        end
    end

    if #setVehicles > 0 then
        return setVehicles
    elseif notify then
        ShowNotification('Error', 'Invalid Vehicle', 'No vehicle(s) selected')
    end
end

local function getSelectedVehicle(notify)
    local setVehicles = getSelectedVehicles() or {}

    if #setVehicles == 1 then
        return setVehicles[1]
    elseif notify then
        if #setVehicles <= 0 then
            ShowNotification('Error', 'Invalid Vehicle', 'No vehicle selected')
        else
            ShowNotification('Error', 'Invalid Vehicle', 'Only 1 vehicle can be selected')
        end
    end
end

local function getVehicleTooltip(vehicle)
    local health = GetEntityHealth(vehicle)
    local maxHealth = GetEntityMaxHealth(vehicle)
    local coords = GetEntityCoords(vehicle)
    local alive = not IsEntityDead(vehicle)
    local selfCoords = GetEntityCoords(PlayerPedId())
    local networked = NetworkGetEntityIsNetworked(vehicle)
    local displayInfo = MainAPI.GetVehicleDisplayInfo(vehicle)
    local driverInfo = MainAPI.GetVehicleDriverInfo(vehicle)

    return {
        { label = 'Vehicle', text = { value = tostring(vehicle), color = '#1c80d1' } },
        { label = 'Model', text = { value = displayInfo and displayInfo.model or 'N/A', color = displayInfo and displayInfo.model and '#1cd152' or '#ff2222' } },
        { label = 'Name', text = { value = displayInfo and displayInfo.name or 'N/A', color = displayInfo and displayInfo.name and '#1cd152' or '#ff2222' }, icon = vehicle and 'data:image/svg+xml;base64,' },
        { label = 'Alive', text = { value = alive and 'Yes' or 'No', color = alive and '#1cd152' or '#ff2222' } },
        { label = 'Health', value = health, bar = { color = '#ff2222', percent = (health / maxHealth) * 100 } },
        -- { label = 'Coords', value = tostring(coords) },
        { label = 'Distance', value = math.floor(#(selfCoords - coords))..'m' },
        { label = 'Speed', value = math.floor(GetEntitySpeed(vehicle))..' m/s' },
        { label = 'Networked', text = { value = networked and 'Yes' or 'No', color = networked and '#1cd152' or '#ff2222' } },
        { label = 'Driver', value = driverInfo and driverInfo.label or 'none' }
    }
end

