function setPlayerModel(setModel)
    MainAPI.InjectCode(commonResource, ([[
        local setModel = SET_MODEL

        if not IsModelValid(setModel) then
            return MainAPI.ShowNotification('Error', 'Set Player Model', 'Invalid model')
        end

        RequestModel(setModel)
        while not HasModelLoaded(setModel) do
            Wait(0)
        end

        MainAPI.SetPlayerModel(PlayerId(), setModel)
        SetPedDefaultComponentVariation(PlayerPedId())
    ]]):gsub('SET_MODEL', GetHashKey(setModel)))
end

