local showingCrosshair = false
local runningBugPlayer = false

local mathAbs = math.abs
local mathSqrt = math.sqrt
local mathRad = math.rad
local mathCos = math.cos
local mathSin = math.sin
local mathMax = math.max
local mathMin = math.min

local function normalize(v)
    local mag = mathSqrt(v.x * v.x + v.y * v.y + v.z * v.z)

    if mag == 0 then
        return {
            x = 0,
            y = 0,
            z = 0
        }
    end

    return {
        x = v.x / mag,
        y = v.y / mag,
        z = v.z / mag
    }
end

local function dot(a, b)
    return a.x * b.x + a.y * b.y + a.z * b.z
end

local function cross(a, b)
    return {
        x = a.y * b.z - a.z * b.y,
        y = a.z * b.x - a.x * b.z,
        z = a.x * b.y - a.y * b.x
    }
end

local function subtract(a, b)
    return {
        x = a.x - b.x,
        y = a.y - b.y,
        z = a.z - b.z
    }
end

local function getCameraAdjustment(cameraPos, cameraRot, targetPos)
    local setRadZ = mathRad(cameraRot.z)
    local setRadX = mathRad(cameraRot.x)
    local setAbsX = mathAbs(mathCos(setRadX))
    local camDir = normalize({
        x = -mathSin(setRadZ) * setAbsX,
        y = mathCos(setRadZ) * setAbsX,
        z = mathSin(setRadX)
    })

    local toTarget = normalize(subtract(targetPos, cameraPos))
    local right = normalize(cross(camDir, {
        x = 0,
        y = 0,
        z = 1
    }))

    local up = normalize(cross(right, camDir))
    local rightDot = dot(toTarget, right)
    local upDot = dot(toTarget, up)
    local horizontal, vertical

    if rightDot > 0.0 then
        horizontal = 'right'
    elseif rightDot < -0.0 then
        horizontal = 'left'
    else
        horizontal = 'none'
    end

    if upDot > 0.0 then
        vertical = 'up'
    elseif upDot < -0.0 then
        vertical = 'down'
    else
        vertical = 'none'
    end

    return vertical, horizontal, upDot, rightDot
end

