Utils.TeleportPlayer = function(x, y, z, h)
    MainAPI.InjectCode(commonResource, ([[
        DoScreenFadeOut(250)

        Wait(250)

        local selfPed = PlayerPedId()
        local targetEntity = MainAPI.GetEntityParent()

        if targetEntity == selfPed then
            ClearPedTasks(selfPed)
        end

        local coords = vec3(SET_X, SET_Y, SET_Z)
        local xCoord = coords.x
        local yCoord = coords.y
        local zCoord = coords.z

        FreezeEntityPosition(targetEntity, true)
        MainAPI.SetCoords(targetEntity, coords + vec3(0.0, 0.0, 1.0))

        local startTimer = GetGameTimer()
        while (GetGameTimer() - startTimer) <= 500 do
            RequestCollisionAtCoord(xCoord, yCoord, zCoord)
            Wait(0)
        end

        local found, groundZ
        
        for i = 1, 25 do
            found, groundZ = GetGroundZFor_3dCoord(xCoord, yCoord, zCoord + i, 0)

            if found and groundZ then
                break
            end
        end

        MainAPI.SetCoords(targetEntity, vec3(xCoord, yCoord, (found and groundZ or zCoord) + 1.0))

        local setHeading = SET_H
        if setHeading then
            SetEntityHeading(targetEntity, setHeading)
        end

        FreezeEntityPosition(targetEntity, false)
        DoScreenFadeIn(250)
    ]]):gsub('SET_X', x):gsub('SET_Y', y):gsub('SET_Z', z):gsub('SET_H', tostring(h)))
end

Utils.SpawnInVehicle = false
Utils.DeleteVehicleOnWarp = false

Utils.SpawnVehicle = function(model)
    MainAPI.InjectCode(commonResource, ([[
        local setModel = SET_MODEL

        if IsModelValid(setModel) then
            RequestModel(setModel)
            while not HasModelLoaded(setModel) do
                Wait(0)
            end

            local selfPed = PlayerPedId()
            local spawnIn = 'SET_IN' == 'true'
            local setCoords = GetOffsetFromEntityInWorldCoords(selfPed, 0.0, 5.0, 0.0)
            
            if spawnIn and not IsPedInAnyVehicle(selfPed, false) then
                setCoords = GetEntityCoords(selfPed)
            end
            
            local entity = MainAPI.SpawnVehicle(setModel, vec3(setCoords.x, setCoords.y, setCoords.z))

            if spawnIn then
                selfPed = PlayerPedId()

                MainAPI.SetCoords(entity, GetEntityCoords(selfPed))
                SetEntityHeading(entity, GetEntityHeading(selfPed))

                if 'SET_DELETE' == 'true' then
                    local vehicle = GetVehiclePedIsIn(selfPed, false)

                    if vehicle and vehicle > 0 then
                        MainAPI.SafeRunNative(DeleteEntity, vehicle)
                    end
                end

                ClearPedTasksImmediately(selfPed)
                MainAPI.TaskWarpPedIntoVehicle(selfPed, entity, -1)
            end
        end
    ]]):gsub('SET_MODEL', GetHashKey(model)):gsub('SET_IN', tostring(Utils.SpawnInVehicle)):gsub('SET_DELETE', tostring(Utils.DeleteVehicleOnWarp)))
end

