local function getOptionIndexes(setStart, setEnd)
    local indexes = {}

    for i = setStart, setEnd do
        local indexValue = #indexes + 1

        indexes[indexValue] = {
            value = indexValue,
            label = i
        }
    end

    return indexes
end

local setWeather = {
    force = false,
    current = 1
}

local setTime = {
    force = false,
    second = 0,
    minute = 0,
    hour = 0    
}

local function updateWeather()
    MainAPI.InjectCode(commonResource, ([[
        MainAPI.SafeRunNative(CreateThread, function()
            _G.SetClient_WeatherIndex = (_G.SetClient_WeatherIndex or 0) + 1
            local setWeatherIndex = _G.SetClient_WeatherIndex

            ClearOverrideWeather()
            ClearWeatherTypePersist()

            if 'SET_FORCE' == 'true' then
                local weatherType = 'SET_TYPE'

                while setWeatherIndex == _G.SetClient_WeatherIndex do
                    ClearOverrideWeather()
                    ClearWeatherTypePersist()
                    SetWeatherTypeNow(weatherType)
                    SetWeatherTypeNowPersist(weatherType)

                    Wait(0)
                end
            end
        end)
    ]]):gsub('SET_FORCE', tostring(setWeather.force)):gsub('SET_TYPE', Utils.Weathers[setWeather.current].type))
end

local function updateTime()
    MainAPI.InjectCode(commonResource, ([[
        _G.SetClient_TimeIndex = (_G.SetClient_TimeIndex or 0) + 1
        local setTimeIndex = _G.SetClient_TimeIndex

        if 'SET_FORCE' == 'true' then
            while setTimeIndex == _G.SetClient_TimeIndex do
                PauseClock(true)
                NetworkOverrideClockTime(SET_HOUR, SET_MINUTE, SET_SECOND)

                Wait(0)
            end
        else
            PauseClock(false)
        end
    ]]):gsub('SET_FORCE', tostring(setTime.force)):gsub('SET_HOUR', setTime.hour):gsub('SET_MINUTE', setTime.minute):gsub('SET_SECOND', setTime.second))
end

local scriptingApi = [[
    local MainAPI = {}

    MainAPI.Print = function(prefix, ...)
        prefix = (prefix or 'info'):upper()

        local args = {...}

        for i = 1, #args do
            args[i] = tostring(args[i])
        end

        print('[^3Mayhem^0] [^'..(prefix == 'ERROR' and 1 or prefix == 'INFO' and 5 or prefix == 'WARNING' and 3 or prefix == 'SUCCESS' and 2 or prefix == 'DEBUG' and 6 or 7)..prefix..'^0] '..table.concat(args, ' '))
    end
]]

