													MainAPI.DeleteTrackedThread('Freecam')

													if setFreeCamHandler and DoesCamExist(setFreeCamHandler) then
														SetCamActive(setFreeCamHandler, false)
														RenderScriptCams(false, false, 0, false, false)
														DestroyCam(setFreeCamHandler, false)
													end

													setFreeCamHandler = nil

													if menuDui then
														MachoExecuteDuiScript(menuDui, 'window.hoveringText.hideList();')
														MachoExecuteDuiScript(menuDui, 'window.crosshair.hide();')
													end

													return
												end

												if not commonResource or not MachoResourceInjectable(commonResource) then
													ShowNotification('Error', 'Freecam', 'No injectable resource available')
													return
												end

                                                CreateThread(function()
                                                    -- Give the DUI time to finish parsing the giant HTML/CSS/JS
                                                    -- payload before calling into it. 150ms was too short
                                                    -- on slower machines.
                                                    Wait(1000)
                                                    MachoExecuteDuiScript(menuDui, 'window.hoveringText.showList();')
                                                    MachoExecuteDuiScript(menuDui, 'window.crosshair.show();')
                                                end)

                                                MainAPI.CreateTrackedThread('Freecam', {
                                                    thread = function(self)
                                                        while self.isActive do
                                                            MachoExecuteDuiScript(menuDui, 'window.crosshair.show();')
