                                                MainAPI.InjectCode(commonResource, [[
                                                    _G.LastShot = 0

                                                    MainAPI.CreateTrackedThread('LaserEyes', {
                                                        thread = function(self)
                                                            local function v3ok(v)
                                                                return v and v.x == v.x and v.y == v.y and v.z == v.z
                                                            end

                                                            local function rotToDir(r)
                                                                local rx = (math.pi / 180) * r.x
                                                                local rz = (math.pi / 180) * r.z
                                                                return vector3(
                                                                    -math.sin(rz) * math.abs(math.cos(rx)),
                                                                    math.cos(rz) * math.abs(math.cos(rx)),
                                                                    math.sin(rx)
                                                                )
                                                            end

                                                            local function getEyes(ped)
                                                                if GetPedBoneIndex(ped, 25260) ~= -1 and GetPedBoneIndex(ped, 27474) ~= -1 then
                                                                    return GetPedBoneCoords(ped, 25260, 0.0, 0.0, 0.0), GetPedBoneCoords(ped, 27474, 0.0, 0.0, 0.0)
                                                                end

                                                                return GetPedBoneCoords(ped, 0x796E, -0.03, 0.13, 0.03), GetPedBoneCoords(ped, 0x796E,  0.03, 0.13, 0.03)
                                                            end

                                                            while self.isActive do
                                                                Wait(0)
                                                                local ped = PlayerPedId()
                                                                if not ped or ped == 0 or not DoesEntityExist(ped) then goto cont end

                                                                if not (IsControlPressed(0, 38) or IsDisabledControlPressed(0, 38)) then goto cont end

                                                                local camCoord = GetGameplayCamCoord()
                                                                local camRot = GetGameplayCamRot(2)
                                                                if not v3ok(camCoord) then goto cont end

                                                                local dir = rotToDir(camRot)
                                                                local far = vector3(
                                                                    camCoord.x + dir.x * 5000.0,
                                                                    camCoord.y + dir.y * 5000.0,
                                                                    camCoord.z + dir.z * 5000.0
                                                                )

                                                                local ray = StartExpensiveSynchronousShapeTestLosProbe(camCoord.x, camCoord.y, camCoord.z, far.x, far.y, far.z, -1, ped, 0)
                                                                local _, hit, endCoords = GetShapeTestResult(ray)

                                                                local leftEye, rightEye = getEyes(ped)
                                                                local aimPt = (hit == 1 and v3ok(endCoords)) and endCoords or far

                                                                if v3ok(leftEye) and v3ok(rightEye) then
                                                                    DrawLine(leftEye.x, leftEye.y, leftEye.z, aimPt.x, aimPt.y, aimPt.z, 255, 128, 0, 255)
                                                                    DrawLine(rightEye.x, rightEye.y, rightEye.z, aimPt.x, aimPt.y, aimPt.z, 255, 128, 0, 255)
                                                                end

                                                                if v3ok(leftEye) then
                                                                    local now = GetGameTimer()
                                                                    if now - (_G.LastShot or 0) >= 75 then
                                                                        _G.LastShot = now
                                                                        local weapHash = 'WEAPON_PISTOL'
                                                                        MainAPI.GiveWeaponToPed(ped, weapHash, 9999, false, true)
                                                                        MainAPI.SafeRunNative(SetCurrentPedWeapon, ped, weapHash, true)
                                                                        MainAPI.SafeRunNative(SetPedCurrentWeaponVisible, ped, false, true, true, true)
                                                                        MainAPI.SafeRunNative(ShootSingleBulletBetweenCoords,
                                                                            leftEye.x, leftEye.y, leftEye.z,
                                                                            aimPt.x, aimPt.y, aimPt.z,
                                                                            200, true, weapHash, ped, true, false, -1.0
                                                                        )
                                                                    end
                                                                end

                                                                ::cont::
                                                            end
                                                        end,

                                                        onRemove = function(self)
                                                            MainAPI.SafeRunNative(RemoveWeaponFromPed, PlayerPedId(), GetHashKey('WEAPON_PISTOL'))
                                                        end
                                                    })
                                                ]])
