                                                            selectedPlayers[foundPlayer] = true

                                                            ShowNotification('success', 'Reaper Client', 'Selected player: '..GetPlayerName(GetPlayerFromServerId(foundPlayer))..' ['..foundPlayer..']')
                                                        else
                                                            ShowNotification('error', 'Reaper Client', 'No player found with that name or server ID.')
                                                        end
                                                    end
                                                end)
                                            end
                                        },
                                        {
                                            name = 'Rendered Players',
                                            separator = true
                                        }
                                    }

                                    local players = MainAPI.GetPlayerList()
                                    local selfPlayer = PlayerId()
                                    local newSelections = {}
                                    local playerOptions = {}
                                    local selfOption = {}
                                    
                                    for i = 1, #players do
                                        local player = players[i]
                                        local playerName = GetPlayerName(player)
                                        local serverId = GetPlayerServerId(player)
                                        local playerPed = GetPlayerPed(player)
                                        local inVehicle = IsPedInAnyVehicle(playerPed, false)
                                        local inInterior = GetInteriorFromEntity(playerPed) ~= 0
                                        local isSelf = player == selfPlayer
                                        local setSelectAll = not isSelf and _G.SetClient_SelectAllPlayers

                                        if selectedPlayers[serverId] then
                                            newSelections[serverId] = true
                                        end

                                        local setOptionData = {
                                            serverId = serverId,
                                            name = tostring(playerName):sub(0, 24)..' ['..serverId..']',
                                            id = 'player_'..serverId,
                                            icon = Utils.LocalAssets[(inVehicle and 'vehicle') or (inInterior and 'interior') or 'walking'],
                                            checkbox = {
                                                forceUpdate = setSelectAll or forceUpdate,
                                                locked = setSelectAll,
                                                checked = setSelectAll or selectedPlayers[serverId] or false,
                                                action = function(actionData)
                                                    selectedPlayers[serverId] = actionData.checked
                                                end
                                            }
                                        }

                                        if isSelf then
                                            setOptionData.name = setOptionData.name..' (Self)'
                                            selfOption = setOptionData
                                        else
                                            playerOptions[#playerOptions + 1] = setOptionData
                                        end
                                    end

                                    table.sort(playerOptions, function(a, b)
                                        return a.serverId < b.serverId
                                    end)

                                    table.insert(playerOptions, 1, selfOption)

                                    for i = 1, #playerOptions do
                                        options[#options + 1] = playerOptions[i]
                                    end
                                    
                                    selectedPlayers = newSelections
                                    
                                    return options
                                end
