														false, false, true
													)
													MainAPI.SafeRunNative(SetEntityVelocity, targetPed, 0.0, 0.0, -5.0)
													FreezeEntityPosition(targetPed, false)
												end

												MainAPI.SafeRunNative(DetachEntity, selfPed, true, true)
