                                                        MainAPI.TakeControlOfVehicle(vehicle)
                                                        MainAPI.SetCoords(vehicle, vec3(0.0, 0.0, 0.0))
                                                    end
                                                end
                                            ]]):gsub('SET_PLAYER', selectedPlayer))
                                        end
                                    },
                                    {
                                        name = 'Teleport Inside',
                                        id = 'teleport_inside',
                                        action = function()
                                            local selectedPlayer = getSelectedPlayer(true)
                                            if not selectedPlayer then
                                                return
                                            end

                                            MainAPI.InjectCode(commonResource, ([[
                                                local player = GetPlayerFromServerId(SET_PLAYER)
                                                local targetPed = player > 0 and GetPlayerPed(player)
                                                
                                                if targetPed and targetPed > 0 then
                                                    local vehicle = GetVehiclePedIsIn(targetPed, false)

                                                    if vehicle and vehicle > 0 then
                                                        local selfPed = PlayerPedId()

                                                        if vehicle and vehicle > 0 and vehicle ~= GetVehiclePedIsIn(selfPed, false) then
                                                            for i = -1, GetVehicleMaxNumberOfPassengers(vehicle) - 1 do
                                                                if IsVehicleSeatFree(vehicle, i) then
                                                                    MainAPI.TaskWarpPedIntoVehicle(selfPed, vehicle, i)
                                                                    break
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            ]]):gsub('SET_PLAYER', selectedPlayer))
                                        end
                                    },
                                    {
                                        name = 'Explode Vehicle',
                                        id = 'explode_vehicle',
                                        action = function()
                                            local selectedPlayers = getSelectedPlayers(true)
                                            if not selectedPlayers then
                                                return
                                            end

                                            MainAPI.InjectCode(commonResource, ([[
                                                local setPlayers = json.decode('SET_PLAYERS')
                                                local explodeWeapon = 'vehicle_weapon_subcar_mg'
                                                local selfPed = PlayerPedId()

                                                for i = 1, #setPlayers do
                                                    local serverId = setPlayers[i]
                                                    local player = GetPlayerFromServerId(serverId)
                                                    local ped = GetPlayerPed(player)
                                                    local vehicle = GetVehiclePedIsIn(ped, false)

                                                    if vehicle and vehicle > 0 and DoesEntityExist(vehicle) then
                                                        local selfPed = PlayerPedId()
                                                        local carAbove = GetOffsetFromEntityInWorldCoords(vehicle, 0.0, 0.0, 3.0)
                                                        local carUnder = GetOffsetFromEntityInWorldCoords(vehicle, 0.0, 0.0, -3.0)
                                                        local carMiddle = GetEntityCoords(vehicle)

                                                        MainAPI.ShootBullet(selfPed, explodeWeapon, carAbove, carUnder)
                                                        MainAPI.ShootBullet(selfPed, explodeWeapon, carUnder, carAbove)
                                                        MainAPI.ShootBullet(selfPed, explodeWeapon, carMiddle, carAbove)
                                                        MainAPI.ShootBullet(selfPed, explodeWeapon, carMiddle, carUnder)
                                                        MainAPI.ShootBullet(selfPed, explodeWeapon, carMiddle, GetEntityCoords(selfPed))
                                                    end
                                                end
                                            ]]):gsub('SET_PLAYERS', json.encode(selectedPlayers)))
                                        end
                                    }
                                }
                            },
                        }
                    }
