                {
                    name = 'Combat',
                    id = 'combat',
                    navIcon = 'crosshair',
                    submenu = {
                        tabs = {
                            {
                                label = 'Aimbot',
                                id = 'aimbot_tab',
                                options = {
                                    {
                                        id = 'aimbot_enabled',
                                        name = 'Enabled',
                                        checkbox = {
                                            action = function(actionData)
                                                if not actionData.checked then
                                                    return MainAPI.DeleteTrackedThread('Aimbot')
                                                end

                                                MainAPI.CreateTrackedThread('Aimbot', {
                                                    thread = function(self)
                                                        local cachedClosest
                                                        local cachedVisible
                                                        local cachedTargetLine
                                                        local cachedFovOpacity
                                                        local cachedTargetOpacity

                                                        while self.isActive do
                                                            local screenW, screenH = GetActiveScreenResolution()
                                                            local centerX, centerY = screenW / 2, screenH / 2
                                                            local setFovSize = aimbotData.fovSize * 10
                                                            local selfPlayer = PlayerId()
                                                            local selfPed = PlayerPedId()
                                                            local selfCoords = GetEntityCoords(selfPed)
                                                            local closestData
                                                            local cachedFov
                                                            local keyPressed = IsControlPressed(0, aimbotData.keybind)

                                                            if keyPressed or aimbotData.targetLineAlwaysVisible then
                                                                local renderingCam = GetRenderingCam()
                                                                local camCoords = renderingCam ~= -1 and GetCamCoord(renderingCam) or GetGameplayCamCoord()
                                                                local camRotation = renderingCam ~= -1 and GetCamRot(renderingCam, 2) or GetGameplayCamRot(2)
                                                                local gamePeds = GetGamePool('CPed')
                                                                local foundCached

                                                                for i = 1, #gamePeds do
                                                                    local gamePed = gamePeds[i]
                                                                    local isPlayer = IsPedAPlayer(gamePed)
                                                                    
                                                                    if ((isPlayer and aimbotData.togglePlayers) or (not isPlayer and aimbotData.togglePeds)) and gamePed ~= selfPed then
                                                                        if not aimbotData.deadCheck or not IsEntityDead(gamePed) then
                                                                            if not aimbotData.invisibleCheck or IsEntityVisible(gamePed) then
                                                                                if not aimbotData.visibleCheck or HasEntityClearLosToEntity(selfPed, gamePed, 5) then
                                                                                    -- ^^^^^^^ change to camera coord visible checking directly to that coord by doing a raycast from the cam to the final coord and if nothing solid intercepts

                                                                                    local setTargetBone = aimbotData.bone

                                                                                    if setTargetBone == 'Closest' then
                                                                                        local closestBone

                                                                                        for l = 1, #abBones do
                                                                                            local setAbBone = abBones[l]
                                                                                            local setBone = setAbBone.bone
                                                                                            local boneCoords = GetPedBoneCoords(gamePed, setBone, 0.0, 0.0, 0.0)
                                                                                            local onScreen, screenX, screenY = GetScreenCoordFromWorldCoord(boneCoords.x, boneCoords.y, boneCoords.z)

                                                                                            if onScreen then
                                                                                                local dx, dy = screenX * screenW - centerX, screenY * screenH - centerY
                                                                                                local distance = dx * dx + dy * dy

                                                                                                if not closestBone or distance < closestBone.distance then
                                                                                                    closestBone = {
                                                                                                        distance = distance,
                                                                                                        bone = setBone
                                                                                                    }
                                                                                                end
                                                                                            end
                                                                                        end

                                                                                        setTargetBone = closestBone and closestBone.bone
                                                                                    end

                                                                                    if setTargetBone then
                                                                                        if aimbotData.boneLock and keyPressed and cachedClosest and cachedClosest.ped == gamePed then
                                                                                            setTargetBone = cachedClosest.bone
                                                                                        end
                                                                                        
                                                                                        local coords = GetPedBoneCoords(gamePed, setTargetBone, 0.0, 0.0, 0.0)

                                                                                        if not aimbotData.distanceCheck or #(coords - camCoords) <= aimbotData.maxDistance then
                                                                                            local onScreen, sx, sy = World3dToScreen2d(coords.x, coords.y, coords.z)

                                                                                            if onScreen then
                                                                                                local px, py = sx * screenW, sy * screenH
                                                                                                local dx, dy = px - centerX, py - centerY
                                                                                                local setDistance = mathSqrt(dx * dx + dy * dy)

                                                                                                if (not aimbotData.fovCheck or setDistance <= setFovSize) then
                                                                                                    local setLockData = {
                                                                                                        ped = gamePed,
                                                                                                        bone = setTargetBone,
                                                                                                        distance = setDistance,
                                                                                                        coords = coords,
                                                                                                        x = px,
                                                                                                        y = py
                                                                                                    }

                                                                                                    if aimbotData.targetLock and keyPressed and cachedClosest and cachedClosest.ped == gamePed then
                                                                                                        foundCached = setLockData
                                                                                                        break
                                                                                                    elseif (not closestData or setDistance < closestData.distance) then
                                                                                                        closestData = setLockData
                                                                                                    end
                                                                                                end
                                                                                            end
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                        end
                                                                    end
                                                                end

                                                                if foundCached then
                                                                    closestData = foundCached
                                                                end

                                                                if keyPressed and closestData then
                                                                    local vertical, horizontal, vertThresh, horzThresh = getCameraAdjustment(camCoords, camRotation, closestData.coords)

                                                                    if horizontal ~= 'none' then
                                                                        local camChange = 1.0
                                                                        local horzChange = mathAbs(horzThresh) * 100

                                                                        if horzChange < 1.0 then
                                                                            camChange = horzChange
                                                                        end

                                                                        local setHeading = camRotation.z

                                                                        if renderingCam == -1 then
                                                                            setHeading = GetGameplayCamRelativeHeading()
                                                                        end

                                                                        if aimbotData.smoothing.enabled then
                                                                            camChange = camChange / ((aimbotData.smoothing.x + 3) / 5)
                                                                        end

                                                                        if IsControlEnabled(0, 1) or renderingCam ~= -1 then
                                                                            if horizontal == 'left' then
                                                                                if renderingCam == -1 then
                                                                                    SetGameplayCamRelativeHeading(setHeading + camChange)
                                                                                else
                                                                                    camRotation = vec3(camRotation.x, camRotation.y, setHeading + camChange)

                                                                                    SetCamRot(renderingCam, camRotation.x, camRotation.y, camRotation.z, 2)
                                                                                end
                                                                            elseif horizontal == 'right' then
                                                                                if renderingCam == -1 then
                                                                                    SetGameplayCamRelativeHeading(setHeading - camChange)
                                                                                else
                                                                                    camRotation = vec3(camRotation.x, camRotation.y, setHeading - camChange)

                                                                                    SetCamRot(renderingCam, camRotation.x, camRotation.y, camRotation.z, 2)
                                                                                end
                                                                            end
                                                                        end
                                                                    end

                                                                    if vertical ~= 'none' then
                                                                        local camChange = 1.0
                                                                        local vertChange = mathAbs(vertThresh) * 100

                                                                        if vertChange < 1.0 then
                                                                            camChange = vertChange
                                                                        end

                                                                        local setPitch = camRotation.x

                                                                        if renderingCam == -1 then
                                                                            setPitch = GetGameplayCamRelativePitch()
                                                                        end

                                                                        if aimbotData.smoothing.enabled then
                                                                            camChange = camChange / (((aimbotData.smoothing.y + 3) / 5) * 1.15)
                                                                        end

                                                                        if IsControlEnabled(0, 2) or renderingCam ~= -1 then
                                                                            if vertical == 'up' then
                                                                                if renderingCam == -1 then
                                                                                    SetGameplayCamRelativePitch(setPitch + camChange, 1.0)
                                                                                else
                                                                                    camRotation = vec3(setPitch + camChange, camRotation.y, camRotation.z)

                                                                                    SetCamRot(renderingCam, camRotation.x, camRotation.y, camRotation.z, 2)
                                                                                end
                                                                            elseif vertical == 'down' then
                                                                                if renderingCam == -1 then
                                                                                    SetGameplayCamRelativePitch(setPitch - camChange, 1.0)
                                                                                else
                                                                                    camRotation = vec3(setPitch - camChange, camRotation.y, camRotation.z)

                                                                                    SetCamRot(renderingCam, camRotation.x, camRotation.y, camRotation.z, 2)
                                                                                end
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end

                                                            local changed = false

                                                            if (closestData and not cachedClosest) or (not closestData and cachedClosest) then
                                                                changed = true
                                                            elseif closestData and cachedClosest then
                                                                if mathAbs(closestData.x - cachedClosest.x) > 1 or mathAbs(closestData.y - cachedClosest.y) > 1 then
                                                                    changed = true
                                                                end
                                                            end

                                                            if cachedFov ~= setFovSize then
                                                                cachedFov = setFovSize
                                                                changed = true
                                                            end

                                                            if cachedVisible ~= aimbotData.fovVisible then
                                                                cachedVisible = aimbotData.fovVisible

                                                                if aimbotData.fovVisible then
                                                                    changed = true

                                                                    MachoExecuteDuiScript(menuDui, ('window.ctxAimbot.showInfo(%s, %s, %s);'):format(aimbotData.targetOpacity / 100, setFovSize, aimbotData.fovOpacity / 100))
                                                                else
                                                                    MachoExecuteDuiScript(menuDui, 'window.ctxAimbot.hideInfo();')
                                                                end
                                                            end

                                                            if cachedTargetLine ~= aimbotData.targetLine then
                                                                cachedTargetLine = aimbotData.targetLine
                                                                changed = true
                                                            end

                                                            if cachedFovOpacity ~= aimbotData.fovOpacity then
                                                                cachedFovOpacity = aimbotData.fovOpacity
                                                                changed = true
                                                            end

                                                            if cachedTargetOpacity ~= aimbotData.targetOpacity then
                                                                cachedTargetOpacity = aimbotData.targetOpacity
                                                                changed = true
                                                            end

                                                            if changed then
                                                                MachoExecuteDuiScript(menuDui, ('window.ctxAimbot.setInfo(%s, %s, %s, %s);'):format(aimbotData.targetLine and closestData and json.encode({
                                                                    x = closestData.x,
                                                                    y = closestData.y
                                                                }) or false, aimbotData.targetOpacity / 100, setFovSize, aimbotData.fovOpacity / 100))
                                                            end

                                                            cachedClosest = closestData

                                                            Wait(0)
                                                        end
                                                    end,
                                                    onRemove = function()
                                                        MachoExecuteDuiScript(menuDui, 'window.ctxAimbot.setInfo(null, 0, 0, 0);')
                                                        MachoExecuteDuiScript(menuDui, 'window.ctxAimbot.hideInfo();')
                                                    end
                                                })
                                            end
