                                            action = function(actionData)
                                                if not actionData.checked then
                                                    return MainAPI.DeleteTrackedThread('TriggerBot')
                                                end

                                                MainAPI.CreateTrackedThread('TriggerBot', {
                                                    thread = function(self)
                                                        local cachedEntity

                                                        while self.isActive do
                                                            local keyPressed = pressingBindData(triggerbotData.bind)
                                                            local setCacheData

                                                            if not triggerbotData.useBind or keyPressed then
                                                                local selfPed = PlayerPedId()
                                                                local renderingCam = GetRenderingCam()

                                                                if IsPedArmed(selfPed, 6) or renderingCam ~= -1 then
                                                                    local renderingCam = GetRenderingCam()
                                                                    local camCoords = renderingCam ~= -1 and GetCamCoord(renderingCam) or GetGameplayCamCoord()
                                                                    local camRotation = renderingCam ~= -1 and GetCamRot(renderingCam, 2) or GetGameplayCamRot(2)
                                                                    local radZ = math.rad(camRotation.z)
                                                                    local setX = math.rad(camRotation.x)
                                                                    local setNum = math.abs(math.cos(setX))
                                                                    local retval, hit, endCoords, surface, entity = GetShapeTestResult(StartExpensiveSynchronousShapeTestLosProbe(camCoords.x, camCoords.y, camCoords.z, camCoords.x + (-math.sin(radZ) * setNum) * 500.0, camCoords.y + (math.cos(radZ) * setNum) * 500.0, camCoords.z + math.sin(setX) * 500.0, 4, selfPed, 7))

                                                                    if hit and entity and entity > 0 and entity ~= selfPed and IsEntityAPed(entity) then
                                                                        if not triggerbotData.invisibleCheck or IsEntityVisible(entity) then
                                                                            if not triggerbotData.visibleCheck or HasEntityClearLosToEntity(selfPed, entity, 5) then
                                                                                if not triggerbotData.distanceCheck or #(GetEntityCoords(entity) - camCoords) <= triggerbotData.maxDistance then
                                                                                    if not triggerbotData.deadCheck or not IsEntityDead(entity, true) then
                                                                                        local isPlayer = IsPedAPlayer(entity)

                                                                                        if (isPlayer and triggerbotData.targetPlayers) or (not isPlayer and triggerbotData.targetPeds) then
                                                                                            local canShoot = false

                                                                                            if triggerbotData.useDelay and triggerbotData.delay > 0 then
                                                                                                local setTimer = GetGameTimer()

                                                                                                if not cachedEntity or cachedEntity.entity ~= entity then
                                                                                                    setCacheData = {
                                                                                                        entity = entity,
                                                                                                        timer = setTimer
                                                                                                    }
                                                                                                else
                                                                                                    setCacheData = cachedEntity

                                                                                                    if (setTimer - cachedEntity.timer) > triggerbotData.delay then
                                                                                                        canShoot = true
                                                                                                    end
                                                                                                end
                                                                                            else
                                                                                                canShoot = true
                                                                                            end

                                                                                            if canShoot then
                                                                                                SetControlNormal(0, 24, 1.0)
                                                                                            end
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                        end
                                                                    end
                                                                end
                                                            end

                                                            cachedEntity = setCacheData
                                                            
                                                            Wait(0)
                                                        end
                                                    end
                                                })
                                            end
