                                                MainAPI.InjectCode(commonResource, [[
                                                    local previousWeapon

                                                    MainAPI.CreateTrackedThread('NoRecoil', {
                                                        thread = function(self)
                                                            while self.isActive do
                                                                local selfPed = PlayerPedId()
                                                                local weapon = GetSelectedPedWeapon(selfPed)

                                                                if previousWeapon then
                                                                    local setPreviousWeapon = previousWeapon.weapon
                                                                    
                                                                    if setPreviousWeapon ~= weapon then
                                                                        SetWeaponRecoilShakeAmplitude(setPreviousWeapon, previousWeapon.recoil)
                                                                        previousWeapon = nil
                                                                    end
                                                                end

                                                                if not previousWeapon then
                                                                    previousWeapon = {
                                                                        weapon = weapon,
                                                                        recoil = GetWeaponRecoilShakeAmplitude(weapon)
