                                                    local xCoord = coords.x
                                                    local yCoord = coords.y
                                                    local zCoord = coords.z + 5.0

                                                    SetWaypointOff()
                                                    DoScreenFadeOut(250)

                                                    Wait(250)

                                                    local selfPed = PlayerPedId()
                                                    local targetEntity = MainAPI.GetEntityParent()

                                                    if targetEntity == selfPed then
                                                        ClearPedTasks(selfPed)
                                                    end

                                                    FreezeEntityPosition(targetEntity, true)
                                                    MainAPI.SetCoords(targetEntity, coords + vec3(0.0, 0.0, 1.0))

                                                    local startTimer = GetGameTimer()
                                                    while (GetGameTimer() - startTimer) <= 500 do
                                                        RequestCollisionAtCoord(xCoord, yCoord, zCoord)
                                                        Wait(0)
                                                    end

                                                    local found, groundZ = GetGroundZFor_3dCoord(xCoord, yCoord, zCoord + 500.0, 0)

                                                    MainAPI.SetCoords(targetEntity, vec3(xCoord, yCoord, (found and groundZ or zCoord) + 1.0))
                                                    FreezeEntityPosition(targetEntity, false)
                                                    DoScreenFadeIn(250)
                                                end
                                            ]])
                                        end
                                    },
                                    {
                                        id = 'auto_tp_waypoint',
                                        name = 'Auto TP Waypoint',
                                        checkbox = {
                                            action = function(actionData)
                                                if not actionData.checked then
                                                    MainAPI.InjectCode(commonResource, [[
                                                        MainAPI.DeleteTrackedThread('AutoTPWaypoint')
                                                    ]])

                                                    return
                                                end

                                                MainAPI.InjectCode(commonResource, [[
                                                    MainAPI.CreateTrackedThread('AutoTPWaypoint', {
                                                        thread = function(self)
                                                            while self.isActive do
                                                                local waypoint = GetFirstBlipInfoId(8)
                                                                
                                                                if DoesBlipExist(waypoint) then
                                                                    local coords = GetBlipInfoIdCoord(waypoint)
                                                                    local xCoord = coords.x
                                                                    local yCoord = coords.y
                                                                    local zCoord = coords.z + 5.0

                                                                    SetWaypointOff()
                                                                    DoScreenFadeOut(250)

                                                                    Wait(250)

                                                                    local selfPed = PlayerPedId()
                                                                    local targetEntity = MainAPI.GetEntityParent()

                                                                    if targetEntity == selfPed then
                                                                        ClearPedTasks(selfPed)
                                                                    end

                                                                    FreezeEntityPosition(targetEntity, true)
                                                                    MainAPI.SetCoords(targetEntity, coords + vec3(0.0, 0.0, 1.0))

                                                                    local startTimer = GetGameTimer()
                                                                    while (GetGameTimer() - startTimer) <= 500 do
                                                                        RequestCollisionAtCoord(xCoord, yCoord, zCoord)
                                                                        Wait(0)
                                                                    end

                                                                    local found, groundZ = GetGroundZFor_3dCoord(xCoord, yCoord, zCoord + 50.0, 0)
                                                    
                                                                    MainAPI.SetCoords(targetEntity, vec3(xCoord, yCoord, (found and groundZ or zCoord) + 1.0))
                                                                    FreezeEntityPosition(targetEntity, false)
                                                                    DoScreenFadeIn(250)
                                                                end

                                                                Wait(0)
                                                            end
                                                        end
                                                    })
                                                ]])
                                            end
                                        }
