                                        name = 'Check Anti-Cheats',
                                        action = function()
                                            local setAntiCheats = {}

                                            if isResourceRunning('FiniAC') then
                                                setAntiCheats[#setAntiCheats + 1] = 'FiniAC'
                                            end
                                            
                                            if isResourceRunning('WaveShield') then
                                                setAntiCheats[#setAntiCheats + 1] = 'WaveShield'
                                            end

                                            if isResourceRunning('ReaperV4') then
                                                local setCheckedPro = GetConvar('reaper_pro_addon_enabled', 'false') == 'true'

                                                setAntiCheats[#setAntiCheats + 1] = 'ReaperV4'..(setCheckedPro and ' (Pro)' or '')
                                            end

                                            if isResourceRunning('EC_AC') then
                                                setAntiCheats[#setAntiCheats + 1] = 'Eagle AC'
                                            end

                                            if isResourceRunning('FeloxAC') then
                                                setAntiCheats[#setAntiCheats + 1] = 'Felox AC'
                                            end

                                            if isResourceRunning('WardenAC') then
                                                setAntiCheats[#setAntiCheats + 1] = 'Warden AC'
                                            end

                                            for i = 0, GetNumResources() - 1 do
                                                local setResource = GetResourceByFindIndex(i)

                                                for j = 0, GetNumResourceMetadata(setResource, 'client_script') - 1 do
                                                    local setMetadata = GetResourceMetadata(setResource, 'client_script', j)

                                                    setMetadata = tostring(setMetadata):lower()

                                                    if setMetadata == 'cl-resource-obfuscated.lua' then
                                                        setAntiCheats[#setAntiCheats + 1] = 'FiveGuard ('..setResource..')'

                                                        break
                                                    end
                                                end
                                            end

                                            for i = 0, GetNumResources() - 1 do
                                                local setResource = GetResourceByFindIndex(i)
                                                local setManifest = LoadResourceFile(setResource, 'fxmanifest.lua')

                                                setManifest = tostring(setManifest):lower()

                                                if setManifest:find('https://electron-services.com') or setManifest:find('electron services') then
                                                    setAntiCheats[#setAntiCheats + 1] = 'Electron ('..setResource..')'
                                                end
                                            end

                                            if #setAntiCheats > 0 then
                                                ShowNotification('Info', 'Found Anti-Cheats', table.concat(setAntiCheats, ', '))
                                            else
                                                ShowNotification('Info', 'No Anti-Cheats', 'No anti-cheats were found')
                                            end
                                        end
                                    },
