                                        id = 'go_to_nearest_player',
                                        name = 'Go To Nearest Player',
                                        action = function()
                                            local closestPlayer = MainAPI.GetClosestPlayer()

                                            if not closestPlayer then
                                                return
                                            end
                                            
                                            local targetPed = closestPlayer.ped

                                            if targetPed and targetPed > 0 then
                                                local setCoords = GetEntityCoords(targetPed)
                                                local selfPed = PlayerPedId()

                                                SetEntityCoordsNoOffset(selfPed, setCoords.x, setCoords.y, setCoords.z, false, false, true)
                                            end
