                                        action = function()
                                            MainAPI.InjectCode(commonResource, [[
                                                local vehicle = MainAPI.GetNearestVehicle(true)

                                                if vehicle and vehicle > 0 then
                                                    MainAPI.TakeControlOfVehicle(vehicle)
                                                    MainAPI.SafeRunNative(SetVehicleDoorsLocked, vehicle, 10)
                                                end
                                            ]])
                                        end
                                    },
                                    {
                                        id = 'unlock_nearest_vehicle',
                                        name = 'Unlock Nearest Vehicle',
                                        action = function()
                                            MainAPI.InjectCode(commonResource, [[
                                                local vehicle = MainAPI.GetNearestVehicle(true)

                                                if vehicle and vehicle > 0 then
                                                    MainAPI.TakeControlOfVehicle(vehicle)
                                                    MainAPI.SafeRunNative(SetVehicleDoorsLocked, vehicle, 1)
                                                end
                                            ]])
                                        end
                                    },
                                    {
                                        id = 'remove_nearest_vehicle_driver',
                                        name = 'Remove Nearest Vehicle Driver',
                                        action = function()
                                            MainAPI.InjectCode(commonResource, [[
                                                local vehicle = MainAPI.GetNearestVehicle(true)

                                                if vehicle and vehicle > 0 then
                                                    MainAPI.TakeControlOfVehicle(vehicle)
                                                end
                                            ]])
