                                    {
                                        id = 'go_to_nearest_vehicle',
                                        name = 'Go To Nearest Vehicle',
                                        action = function()
                                            MainAPI.InjectCode(commonResource, [[
                                                local vehicle = MainAPI.GetNearestVehicle(true)

                                                if vehicle and vehicle > 0 then
                                                    MainAPI.SetCoords(PlayerPedId(), GetEntityCoords(vehicle))
                                                end
                                            ]])
                                        end
                                    },
                                    {
                                        id = 'teleport_inside_nearest_vehicle',
                                        name = 'Teleport Inside Nearest Vehicle',
                                        action = function()
                                            MainAPI.InjectCode(commonResource, [[
                                                local vehicle = MainAPI.GetNearestVehicle(true)

                                                if vehicle and vehicle > 0 then
                                                    local selfPed = PlayerPedId()

                                                    if vehicle ~= GetVehiclePedIsIn(selfPed, false) then
                                                        for i = -1, GetVehicleMaxNumberOfPassengers(vehicle) - 1 do
                                                            if IsVehicleSeatFree(vehicle, i) then
                                                                MainAPI.TaskWarpPedIntoVehicle(selfPed, vehicle, i)

                                                                break
                                                            end
                                                        end
                                                    end
                                                end
                                            ]])
                                        end
                                    },
                                    {
                                        id = 'teleport_nearest_vehicle_to_ocean',
                                        name = 'Teleport Nearest Vehicle To Ocean',
                                        action = function()
                                            MainAPI.InjectCode(commonResource, [[
                                                local vehicle = MainAPI.GetNearestVehicle(true)

                                                if vehicle and vehicle > 0 then
                                                    MainAPI.TakeControlOfVehicle(vehicle)
                                                    MainAPI.SetCoords(vehicle, vec3(-4000.0, -4000.0, 10.0))
                                                end
                                            ]])
                                        end
                                    },
                                    {
                                        id = 'teleport_nearest_vehicle_to_void',
                                        name = 'Teleport Nearest Vehicle To Void',
                                        action = function()
                                            MainAPI.InjectCode(commonResource, [[
                                                local vehicle = MainAPI.GetNearestVehicle(true)

                                                if vehicle and vehicle > 0 then
                                                    MainAPI.TakeControlOfVehicle(vehicle)
                                                    MainAPI.SetCoords(vehicle, vec3(0.0, 0.0, 0.0))
                                                end
                                            ]])
                                        end
                                    },
                                    {
                                        id = 'set_nearest_vehicle_coords',
                                        name = 'Set Nearest Vehicle Coords',
                                        action = function()
                                            showInput('Set Vehicle Coords', 'x,y,z', function(coords)
                                                local x, y, z = coords:match('([^,]+),%s*([^,]+),%s*([^,]+)')

                                                x, y, z = tonumber(x), tonumber(y), tonumber(z)

                                                if not x or not y or not z then
                                                    ShowNotification('Error', 'Set Vehicle Coords', 'Invalid coordinates')

                                                    return
                                                end

                                                MainAPI.InjectCode(commonResource, ([[
                                                    local setCoords = json.decode('SET_COORDS')
                                                    local vehicle = MainAPI.GetNearestVehicle(true)

                                                    if vehicle and vehicle > 0 then
                                                        MainAPI.TakeControlOfVehicle(vehicle)
                                                        MainAPI.SetCoords(vehicle, setCoords)
                                                    end
                                                ]]):gsub('SET_COORDS', json.encode({
                                                    x = x + 0.0,
                                                    y = y + 0.0,
                                                    z = z + 0.0
                                                })))
                                            end)
                                        end
                                    },
                                    {
                                        id = 'prevent_mass_entities',
                                        name = 'Prevent Mass Entities',
                                        checkbox = {
                                            action = function(actionData)
                                                if not actionData.checked then
                                                    MainAPI.InjectCode(commonResource, [[
                                                        MainAPI.DeleteTrackedThread('PreventModelOverflow')
                                                    ]])

                                                    return
                                                end
                                                
                                                MainAPI.InjectCode(commonResource, [[
                                                    local setHashes = {}
                                                    local cachedEntity

                                                    MainAPI.CreateTrackedThread('PreventModelOverflow', {
                                                        thread = function(self)
                                                            while self.isActive do
                                                                local vehicles = GetGamePool('CVehicle')
                                                                local peds = GetGamePool('CPed')
                                                                local entities = {}

                                                                for i = 1, #vehicles do
                                                                    entities[#entities + 1] = vehicles[i]
                                                                end

                                                                for i = 1, #peds do
                                                                    entities[#entities + 1] = peds[i]
                                                                end

                                                                local modelCounts = {}
                                                                local selfPed = PlayerPedId()
                                                                local setEntity = selfPed
                                                                local selfVehicle = GetVehiclePedIsIn(selfPed, false)
                                                    
                                                                if selfVehicle and selfVehicle > 0 and GetPedInVehicleSeat(selfVehicle, -1) == selfPed then
                                                                    setEntity = selfVehicle
                                                                end

                                                                for i = 1, #entities do
                                                                    local entity = entities[i]
                                                                    local entityType = GetEntityType(entity)
                                                                    local trackEntity = false

                                                                    if entityType == 2 then
                                                                        local driver = GetPedInVehicleSeat(entity, -1)

                                                                        if not driver or driver <= 0 or not IsPedAPlayer(driver) then
                                                                            trackEntity = true
                                                                        end
                                                                    elseif entityType == 1 then
                                                                        if not IsPedAPlayer(entity) then
                                                                            trackEntity = true
                                                                        end
                                                                    end

                                                                    if trackEntity then
                                                                        local model = GetEntityModel(entity)
                                                                        local count = (modelCounts[model] or 0) + 1

                                                                        modelCounts[model] = count

                                                                        local hideEntity = count > 1

                                                                        if not hideEntity then
                                                                            if entityType == 2 then
                                                                                setHashes.tug = setHashes.tug or GetHashKey('tug')
                                                                                setHashes.jet = setHashes.jet or GetHashKey('jet')
                                                                                setHashes.cargoplane = setHashes.cargoplane or GetHashKey('cargoplane')
                                                                                setHashes.cargoplane2 = setHashes.cargoplane2 or GetHashKey('cargoplane2')
                                                                                setHashes.blimp = setHashes.blimp or GetHashKey('blimp')
                                                                                setHashes.blimp2 = setHashes.blimp2 or GetHashKey('blimp2')
                                                                                setHashes.blimp3 = setHashes.blimp3 or GetHashKey('blimp3')

                                                                                if model == setHashes.tug
                                                                                    or model == setHashes.jet
                                                                                    or model == setHashes.cargoplane
                                                                                    or model == setHashes.cargoplane2
                                                                                    or model == setHashes.blimp
                                                                                    or model == setHashes.blimp2
                                                                                    or model == setHashes.blimp3
                                                                                then
                                                                                    hideEntity = true
                                                                                end
                                                                            elseif entityType == 1 then
                                                                                setHashes.ig_wade = setHashes.ig_wade or GetHashKey('ig_wade')

                                                                                if model == setHashes.ig_wade then
                                                                                    hideEntity = true
                                                                                end
                                                                            end
                                                                        end

                                                                        if hideEntity then
                                                                            if cachedEntity and cachedEntity ~= setEntity then
                                                                                SetEntityNoCollisionEntity(entity, cachedEntity, false)
                                                                            end

                                                                            SetEntityLocallyInvisible(entity)
                                                                            SetEntityNoCollisionEntity(entity, setEntity, true)
                                                                        end
                                                                    end
                                                                end

                                                                cachedEntity = setEntity

                                                                Wait(0)
                                                            end
                                                        end,
                                                        onRemove = function()
                                                            local vehicles = GetGamePool('CVehicle')
                                                            local peds = GetGamePool('CPed')
                                                            local entities = {}

                                                            for i = 1, #vehicles do
                                                                entities[#entities + 1] = vehicles[i]
                                                            end

                                                            for i = 1, #peds do
                                                                entities[#entities + 1] = peds[i]
                                                            end

                                                            for i = 1, #entities do
                                                                local entity = entities[i]
                                                                
                                                                SetEntityNoCollisionEntity(entity, cachedEntity, false)
                                                            end
                                                        end
                                                    })
                                                ]])
                                            end
                                        }
                                    },
                                    {
                                        id = 'no_vehicle_collisions',
                                        name = 'No Vehicle Collisions',
                                        checkbox = {
                                            action = function(actionData)
                                                if not actionData.checked then
                                                    MainAPI.InjectCode(commonResource, [[
                                                        MainAPI.DeleteTrackedThread('NoVehicleCollisions')
                                                    ]])

                                                    return
                                                end
                                                
                                                MainAPI.InjectCode(commonResource, [[
                                                    local cachedEntity

                                                    MainAPI.CreateTrackedThread('NoVehicleCollisions', {
                                                        thread = function(self)
                                                            while self.isActive do
                                                                local selfPed = PlayerPedId()
                                                                local setEntity = MainAPI.GetEntityParent()
                                                                local vehicles = GetGamePool('CVehicle')

                                                                for i = 1, #vehicles do
                                                                    local entity = vehicles[i]

                                                                    if entity ~= setEntity then
                                                                        if cachedEntity and cachedEntity ~= setEntity then
                                                                            SetEntityNoCollisionEntity(entity, cachedEntity, false)
                                                                        end

                                                                        SetEntityNoCollisionEntity(entity, setEntity, true)
                                                                    end
                                                                end

                                                                cachedEntity = setEntity

                                                                Wait(0)
                                                            end
                                                        end,
                                                        onRemove = function()
                                                            local vehicles = GetGamePool('CVehicle')

                                                            for i = 1, #vehicles do
                                                                local entity = vehicles[i]

                                                                SetEntityNoCollisionEntity(entity, cachedEntity, false)
                                                            end
                                                        end
                                                    })
                                                ]])
                                            end
                                        }
                                    },
                                }
                            }
                        }
                    }
