function MainAPI.OpenInventory(id)
    if isResourceRunning('jobs_creator') then
        MainAPI.InjectCode('jobs_creator', ([[
            MainAPI.SafeRunNative(TriggerEvent, 'jobs_creator:actions:search', SET_TARGET)

        ]]):gsub('SET_TARGET', id))
    elseif isResourceRunning('kuro-robbing') then
        MainAPI.InjectCode('kuro-robbing', ([[
            MainAPI.SafeRunNative(TriggerServerEvent, 'lh_deadrob:server:openInventory', SET_TARGET)
        ]]):gsub('SET_TARGET', id))
    elseif isResourceRunning('tech-robbing') then
        MainAPI.InjectCode('tech-robbing', ([[
            local id = SET_TARGET

            MainAPI.SafeRunNative(TriggerServerEvent, 'deadrob:isDead', id, false)

            Wait(150)

