local gameModels = GetAllVehicleModels() or {}

for i = 1, #gameModels do
    local model = gameModels[i]
    local setClass = GetVehicleClassFromName(model)

    if setClass then
        local classData = setClasses[setClass]

        if classData then
            local setModels = classData.models

            setModels[#setModels + 1] = model
            classData.setModels = setModels
        end
    end
end

local vehiclesTab = mainMenuOptions[5].submenu.tabs
local vehiclesSpawnerTab = vehiclesTab[1].options

for i = 0, #setClasses do
    local setClass = setClasses[i]
    local setModels = setClass.models

    if #setModels > 0 then
        local modelOptions = {}

        for l = 1, #setModels do
            modelOptions[#modelOptions + 1] = {
                label = setModels[l],
                value = l
            }
        end

        vehiclesSpawnerTab[#vehiclesSpawnerTab + 1] = {
            id = 'vehicle_class_'..i,
            name = setClass.label,
            slider = {
                value = 1,
                options = modelOptions
            },
            action = function(actionData)
                Utils.SpawnVehicle(setModels[actionData.option.slider.value])
            end
        }
    end
end

