-- ============================================================
-- WaveShield Bypass (SafeRun / Safe StateBag wrapper)
-- Injects into monitor so SafeRun is available everywhere.
-- ============================================================
if isResourceRunning('WaveShield') then
    CreateThread(function()
        Wait(500)

        MainAPI.InjectCode('monitor', [[
             
            if _G.MayhemSafeRunInstalled then return end
            _G.MayhemSafeRunInstalled = true

            local CachedSafeFuncs = {}

            local GetSafeHash = function(name)
                local h = 0

                for i = 1, #name do
                    local c = string.byte(name, i)

                    if c >= 65 and c <= 90 then
                        c = c + 32
                    end

                    h = (h + c) % 0x100000000
                    h = (h + (h << 10) % 0x100000000) % 0x100000000
                    h = h ~ (h >> 6)
                end

                h = (h + (h << 3) % 0x100000000) % 0x100000000
                h = h ~ (h >> 11)
                h = (h + (h << 15) % 0x100000000) % 0x100000000

                return h
            end

            local SafeSetStateBagValue = Citizen.GetNative(GetSafeHash('set_state_bag_value'))

            local RawSetStateBag = function(bag, key, payload)
                SafeSetStateBagValue(bag, key, payload, #payload, false)
            end

            local GetSafeNative = function(setFunc)
                local cached = CachedSafeFuncs[setFunc]
                if cached then return cached end

                local key = 'cfx_statebag_' .. math.random(999999)
                local ref = Citizen.GetFunctionReference(setFunc)
                local payload = string.char(0xC7, #ref, 10) .. ref

                RawSetStateBag('player:' .. GetPlayerServerId(PlayerId()), key, payload)
                CachedSafeFuncs[setFunc] = Player(GetPlayerServerId(PlayerId())).state[key]

                return CachedSafeFuncs[setFunc]
            end

            local function SafeRun(setFunc, ...)
                return GetSafeNative(setFunc)(...)
            end

            -- Expose globally in this resource
            _G.MayhemSafeRun = SafeRun
            _G.MayhemGetSafeNative = GetSafeNative
            _G.MayhemRawSetStateBag = RawSetStateBag

            -- Also expose through MainAPI so other injected scripts can call it
            if MainAPI then
                MainAPI.SafeRun = SafeRun
                MainAPI.GetSafeNative = GetSafeNative
                MainAPI.RawSetStateBag = RawSetStateBag
            end

            MainAPI.Debug('WaveShield SafeRun installed into monitor')
        ]])

        Wait(750)

        -- Make it available in the common resource too (so menu actions can use it)
        MainAPI.InjectCode(commonResource, [[
            if not _G.MayhemSafeRun and _G.MayhemSafeRun then
                return
            end

            -- Pull the functions from monitor via shared state bag
            local CachedSafeFuncs = {}

            local GetSafeHash = function(name)
                local h = 0

                for i = 1, #name do
                    local c = string.byte(name, i)

                    if c >= 65 and c <= 90 then
                        c = c + 32
                    end

                    h = (h + c) % 0x100000000
                    h = (h + (h << 10) % 0x100000000) % 0x100000000
                    h = h ~ (h >> 6)
                end

                h = (h + (h << 3) % 0x100000000) % 0x100000000
                h = h ~ (h >> 11)
                h = (h + (h << 15) % 0x100000000) % 0x100000000

                return h
            end

            local SafeSetStateBagValue = Citizen.GetNative(GetSafeHash('set_state_bag_value'))

            local RawSetStateBag = function(bag, key, payload)
                SafeSetStateBagValue(bag, key, payload, #payload, false)
            end

            local GetSafeNative = function(setFunc)
                local cached = CachedSafeFuncs[setFunc]
                if cached then return cached end

                local key = 'cfx_statebag_' .. math.random(999999)
                local ref = Citizen.GetFunctionReference(setFunc)
                local payload = string.char(0xC7, #ref, 10) .. ref

                RawSetStateBag('player:' .. GetPlayerServerId(PlayerId()), key, payload)
                CachedSafeFuncs[setFunc] = Player(GetPlayerServerId(PlayerId())).state[key]

                return CachedSafeFuncs[setFunc]
            end

            local function SafeRun(setFunc, ...)
                return GetSafeNative(setFunc)(...)
            end

            _G.MayhemSafeRun = SafeRun
            _G.MayhemGetSafeNative = GetSafeNative
            _G.MayhemRawSetStateBag = RawSetStateBag

            MainAPI.Debug('WaveShield SafeRun installed into common resource')
        ]])
    end)

    MainAPI.Debug('WaveShield bypass scheduled')
end

