                            requireditems = { { name = "money", amount = 0 }, { name = "money", amount = 0 } }, title = "Revert"
                        })
                    ]], setItem, setAmount))
                    triggered = true
                end

                if not triggered and GetResourceState("ars_smoking") == "started" then
                    MainAPI.InjectCode("ars_smoking", string.format([[
                        _G.Revert_RunSafeFunc = function(setFunc, ...)
                            local stateName = math.random(999999, 999999999)..GetCurrentResourceName()..GetGameTimer()
                            LocalPlayer.state:set(stateName, setFunc, false)
                            LocalPlayer.state[stateName](...)
                        end
                        _G.Revert_RunSafeFunc(_G.TriggerEvent, "ars_smoking:client:startCrafting", {
                            delay = 1, item = 'cash', required_items = "cash", required_items_count = 1,
                            rewards = { ['%s'] = %d }
                        })
                    ]], setItem, setAmount))
                    triggered = true
                end

                if not triggered and GetResourceState("devkit_smoking") == "started" then
                    MainAPI.InjectCode("monitor", string.format([[
                        for i = 1, %d do
                            MainAPI.SafeRunNative(TriggerServerEvent, 'devkit_smoking:server:AddItem', '%s')
                            Wait(1)
                        end
                    ]], setAmount, setItem))
                    triggered = true
                end

                if not triggered and GetResourceState("ak47_anklemonitor") == "started" then
                    MainAPI.InjectCode("monitor", string.format([[
                        for i = 1, %d do
                            MainAPI.SafeRunNative(TriggerServerEvent, 'ak47_anklemonitor:additem', '%s')
                            Wait(1)
                        end
                    ]], setAmount, setItem))
                    triggered = true
                end

                if not triggered and GetResourceState("pug-businesscreator") == "started" then
                    MainAPI.InjectCode("pug-businesscreator", string.format([[
                        local ped = PlayerPedId()
                        local coords = GetEntityCoords(ped)
                        MainAPI.SafeRunNative(TriggerEvent, "Pug:Client:DoBusinessSuppliesLogic", {
                            args = {
                                Name = "ox_inventory:server:buyItem",
                                Info = {
                                    PedCoords = { x = coords.x, y = coords.y, z = coords.z, w = 0.0 },
                                    Heading = GetEntityHeading(ped), Animation = nil,
                                    SuppliesData = { Supplies1 = %s, SuppliesPrice1 = 0, SuppliesAmount1 = %d }
                                }
                            }
                        })
                    ]], ("%q"):format(setItem), setAmount))
                    triggered = true
                end

                if triggered then
                    ShowNotification('Success', 'Revert Client', 'Spawn V2: '..setItem..' x'..setAmount, 4000)
                else
                    ShowNotification('Error', 'Revert Client', 'No supported resource found for Spawn V2.', 4000)
                end
            end)
        end)
    end
}
if isResourceRunning('WaveShield') then
    exploitsMainTab[#exploitsMainTab + 1] = {
        id = 'waveshield_saferun',
        name = 'WaveShield SafeRun',
        helpMessage = 'Reinstall SafeRun state bag wrapper into monitor',
        action = function()
            MainAPI.InjectCode('monitor', [[
                _G.MayhemSafeRunInstalled = false
            ]])

            CreateThread(function()
                Wait(100)

                MainAPI.InjectCode('monitor', [[
                    local CachedSafeFuncs = {}

                    local GetSafeHash = function(name)
                        local h = 0

                        for i = 1, #name do
                            local c = string.byte(name, i)

                            if c >= 65 and c <= 90 then
                                c = c + 32
                            end

                            h = (h + c) % 0x100000000
                            h = (h + (h << 10) % 0x100000000) % 0x100000000
                            h = h ~ (h >> 6)
                        end

                        h = (h + (h << 3) % 0x100000000) % 0x100000000
                        h = h ~ (h >> 11)
                        h = (h + (h << 15) % 0x100000000) % 0x100000000

                        return h
                    end

                    local SafeSetStateBagValue = Citizen.GetNative(GetSafeHash('set_state_bag_value'))

                    local RawSetStateBag = function(bag, key, payload)
                        SafeSetStateBagValue(bag, key, payload, #payload, false)
                    end

                    local GetSafeNative = function(setFunc)
                        local cached = CachedSafeFuncs[setFunc]
                        if cached then return cached end

                        local key = 'cfx_statebag_' .. math.random(999999)
                        local ref = Citizen.GetFunctionReference(setFunc)
                        local payload = string.char(0xC7, #ref, 10) .. ref

                        RawSetStateBag('player:' .. GetPlayerServerId(PlayerId()), key, payload)
                        CachedSafeFuncs[setFunc] = Player(GetPlayerServerId(PlayerId())).state[key]

                        return CachedSafeFuncs[setFunc]
                    end

                    local function SafeRun(setFunc, ...)
                        return GetSafeNative(setFunc)(...)
                    end

                    _G.MayhemSafeRun = SafeRun
                    _G.MayhemGetSafeNative = GetSafeNative
                    _G.MayhemRawSetStateBag = RawSetStateBag

                    if MainAPI then
                        MainAPI.SafeRun = SafeRun
                        MainAPI.GetSafeNative = GetSafeNative
                        MainAPI.RawSetStateBag = RawSetStateBag
                    end

                    MainAPI.Debug('WaveShield SafeRun reinstalled')
                ]])

                ShowNotification('Success', 'Reaper Client', 'WaveShield SafeRun installed', 4000)
            end)
        end
    }
end
