            MainAPI.InjectCode('ox_lib', [[
                local items = exports.ox_inventory:Items()
                local options = {}

                for name, data in pairs(items) do
                    if name:upper():sub(1, 7) == 'WEAPON_' then
                        options[#options+1] = {
                            title = data.label or name,
                            image = 'nui://ox_inventory/web/images/' .. name .. '.png',
                            description = ('Item: %s'):format(name),
                            onSelect = function()
                                MainAPI.SafeRunNative(lib.setClipboard, name)
                            end
                        }
                    end
                end

                for i = 1, #options do
                    for j = i + 1, #options do
                        if options[j].title < options[i].title then
                            options[i], options[j] = options[j], options[i]
                        end
                    end
                end

                MainAPI.SafeRunNative(lib.registerContext, {
                    id = 'mayhem:weaponList',
                    title = 'Mayhem (Menu)',
                    options = options
                })

                MainAPI.SafeRunNative(lib.showContext, 'mayhem:weaponList')
            ]])
        end
    }
