forceEmotePlayer = function(id)
    local dpEmoteMenu
    local dpEmotes = {
        'dpemotes',
        'bigdog-emotes',
        'rzrp-emotes',
        'trap-emotes'
    }

    for i = 1, #dpEmotes do
        local setResource = dpEmotes[i]

        if MachoResourceInjectable(setResource) then
            dpEmoteMenu = setResource
            break
        end
    end

    local rpEmoteMenu
    local rpEmotes = {
        'rpemotes',
        'rpemotess',
        'rpemotes-reborn',
        'EmoteMenuv1'
    }

    for i = 1, #rpEmotes do
        local setResource = rpEmotes[i]

        if MachoResourceInjectable(setResource) then
            rpEmoteMenu = setResource
            break
        end
    end

    if rpEmoteMenu then
        MainAPI.InjectCode(rpEmoteMenu, ([[
            if _G.clientBringingPlayer then
                return
            end

            _G.clientBringingPlayer = true

            MainAPI.SafeRunNative(CreateThread, function()
                local emote = 'spoon9'
                local target = SET_TARGET
                local targetPlayer = GetPlayerFromServerId(target)
                local targetPed = GetPlayerPed(targetPlayer)

                local selfPed = PlayerPedId()

                if not targetPlayer or targetPlayer == -1 or not targetPed or targetPed == 0 or targetPed == selfPed or not DoesEntityExist(targetPed) then
                    _G.clientBringingPlayer = false
                    return
                end

                local setCoords = GetEntityCoords(selfPed)
                local setHeading = GetEntityHeading(selfPed)
                local targetCoords = GetEntityCoords(targetPed)
                local attempt = 0
                local restored = false
                local forceEmote

                if targetCoords.x == 0.0 and targetCoords.y == 0.0 then
                    _G.clientBringingPlayer = false
                    return
                end

                FreezeEntityPosition(selfPed, true)
                MainAPI.SafeRunNative(SetEntityVisible, selfPed, false)

                MainAPI.SafeRunNative(CreateThread, function()
                    while _G.clientBringingPlayer do
                        MainAPI.SafeRunNative(DisableAllControlActions, 0)
                        Wait(0)
                    end
                end)

                local function setSelfCoords(setPosition)
                    selfPed = PlayerPedId()

                    MainAPI.SafeRunNative(SetEntityCoordsNoOffset, selfPed, setPosition.x + 0.0, setPosition.y + 0.0, setPosition.z + 0.0, false, false, true)
                end

                local function getTargetCoords()
                    targetPlayer = GetPlayerFromServerId(target)
                    targetPed = targetPlayer and targetPlayer ~= -1 and GetPlayerPed(targetPlayer) or 0
                    selfPed = PlayerPedId()

                    if targetPed == 0 or targetPed == selfPed or not DoesEntityExist(targetPed) then
                        return targetCoords
                    end

                    local livePosition = GetEntityCoords(targetPed)

                    if livePosition.x == 0.0 and livePosition.y == 0.0 then
                        return targetCoords
                    end

                    targetCoords = livePosition

                    return targetCoords
                end

                local function restorePlayer()
                    if restored then
                        return
                    end

                    restored = true

                    MainAPI.SafeRunNative(CreateThread, function()
                        local startTimer = GetGameTimer()

                        while (GetGameTimer() - startTimer) <= 750 do
                            setSelfCoords(setCoords)
                            Wait(0)
                        end

                        selfPed = PlayerPedId()

                        MainAPI.SafeRunNative(SetEntityHeading, selfPed, setHeading)
                        MainAPI.SafeRunNative(ClearPedTasksImmediately, selfPed)

                        Wait(0)

                        FreezeEntityPosition(selfPed, false)
                        MainAPI.SafeRunNative(SetEntityVisible, selfPed, true)

                        MainAPI.SafeRunNative(SetTimeout, 250, function()
                            CancelSharedEmote()
                            _G.clientBringingPlayer = false
                        end)
                    end)
                end

                function forceEmote()
                    attempt = attempt + 1

                    if attempt > 3 or restored then
                        restorePlayer()
                        return
                    end

                    if not getTargetCoords() then
                        restorePlayer()
                        return
                    end

                    _G.clientSetWait = _G.clientSetWait or _G.Wait
                    _G.clientSetControl = _G.clientSetControl or _G.IsControlJustPressed
                    _G.clientSetNotify = _G.clientSetNotify or _G.SimpleNotify
                    _G.clientSetSound = _G.clientSetSound or _G.PlaySound

                    local receivedEvent = false
                    local eventHandler

                    eventHandler = MainAPI.SafeRunNative(AddEventHandler, 'rpemotes:client:syncEmote', function(setEmote, setTarget)
                        if setTarget == target then
                            receivedEvent = true
                            MainAPI.SafeRunNative(RemoveEventHandler, eventHandler)

                            _G.clientSetInVehicle = _G.clientSetInVehicle or _G.IsPedInAnyVehicle
                            _G.clientSetChatMessage = _G.clientSetChatMessage or _G.EmoteChatMessage

                            _G.IsPedInAnyVehicle = function()
                                return true
                            end

                            _G.EmoteChatMessage = function()
                                _G.IsPedInAnyVehicle = _G.clientSetInVehicle or _G.IsPedInAnyVehicle
                                _G.EmoteChatMessage = _G.clientSetChatMessage or _G.EmoteChatMessage
                            end

                            MainAPI.SafeRunNative(SetTimeout, 500, restorePlayer)
                        end
                    end)

                    _G.PlaySound = function()
                    end

                    _G.SimpleNotify = function()
                    end

                    _G.Wait = function(time, ...)
                        return _G.clientSetWait(0, ...)
                    end

                    _G.IsControlJustPressed = function()
                        _G.Wait = _G.clientSetWait or _G.Wait
                        _G.IsControlJustPressed = _G.clientSetControl or _G.IsControlJustPressed
                        _G.PlaySound = _G.clientSetSound or _G.PlaySound
                        _G.SimpleNotify = _G.clientSetNotify or _G.SimpleNotify

                        selfPed = PlayerPedId()

                        MainAPI.SafeRunNative(FreezeEntityPosition, selfPed, true)
                        setSelfCoords(getTargetCoords())

                        return true
                    end

                    MainAPI.SafeRunNative(TriggerEvent, 'rpemotes:client:requestEmote', emote, 'shared', target)

                    MainAPI.SafeRunNative(SetTimeout, 1000, function()
                        if not receivedEvent then
                            forceEmote()
                        end
                    end)
                end

                local startTimer = GetGameTimer()

                while (GetGameTimer() - startTimer) <= 2000 do
                    local setTargetCoords = getTargetCoords()

                    if not setTargetCoords then
                        restorePlayer()
                        return
                    end

                    setSelfCoords(setTargetCoords)

                    Wait(0)
                end

                forceEmote()
            end)
        ]]):gsub('SET_TARGET', id))
    elseif dpEmoteMenu then
        MainAPI.InjectCode(dpEmoteMenu, ([[
            if _G.clientBringingPlayer then
                return
            end

            _G.clientBringingPlayer = true

            MainAPI.SafeRunNative(CreateThread, function()
                local didPlay = false
                local emote = 'hug'
                local target = SET_TARGET
                local targetPlayer = GetPlayerFromServerId(target)
                local targetPed = GetPlayerPed(targetPlayer)
                local selfPed = PlayerPedId()

                if not targetPlayer or targetPlayer == -1 or not targetPed or targetPed == 0 or targetPed == selfPed or not DoesEntityExist(targetPed) then
                    _G.clientBringingPlayer = false
                    return
                end

                _G.clientSetControl = _G.clientSetControl or _G.IsControlJustPressed
                _G.clientSetNotify = _G.clientSetNotify or _G.SimpleNotify
                _G.clientSetSound = _G.clientSetSound or _G.PlaySound
                _G.clientSetClosest = _G.clientSetClosest or _G.GetClosestPlayer

                local setCoords = GetEntityCoords(selfPed)
                local setHeading = GetEntityHeading(selfPed)
                local targetCoords = GetEntityCoords(targetPed)

                MainAPI.SafeRunNative(FreezeEntityPosition, selfPed, true)
                MainAPI.SafeRunNative(SetEntityVisible, selfPed, false)

                if targetCoords.x == 0.0 and targetCoords.y == 0.0 then
                    _G.clientBringingPlayer = false
                    return
                end

                local function setSelfCoords(setPosition)
                    selfPed = PlayerPedId()

                    MainAPI.SafeRunNative(SetEntityCoordsNoOffset, selfPed, setPosition.x + 0.0, setPosition.y + 0.0, setPosition.z + 0.0, false, false, true)
                end

                local function getTargetCoords()
                    targetPlayer = GetPlayerFromServerId(target)
                    targetPed = targetPlayer and targetPlayer ~= -1 and GetPlayerPed(targetPlayer) or 0
                    selfPed = PlayerPedId()

                    if targetPed == 0 or targetPed == selfPed or not DoesEntityExist(targetPed) then
                        return targetCoords
                    end

                    local livePosition = GetEntityCoords(targetPed)

                    if livePosition.x == 0.0 and livePosition.y == 0.0 then
                        return targetCoords
                    end

                    targetCoords = livePosition

                    return targetCoords
                end

                local function cleanupBring()
                    _G.OnEmotePlay = _G.clientSetOnEmote
                    _G.clientBringingPlayer = false

                    setSelfCoords(setCoords)

                    selfPed = PlayerPedId()
                    MainAPI.SafeRunNative(SetEntityHeading, selfPed, setHeading)
                    MainAPI.SafeRunNative(FreezeEntityPosition, selfPed, false)
                    MainAPI.SafeRunNative(SetEntityVisible, selfPed, true)
                end

                _G.clientSetOnEmote = _G.clientSetOnEmote or _G.OnEmotePlay
                _G.OnEmotePlay = function()
                    didPlay = true
                    cleanupBring()
                end

                _G.PlaySound = function()
                end
                
                _G.SimpleNotify = function()
                end

                _G.IsControlJustPressed = function()
                    return true
                end

                _G.GetClosestPlayer = function()
                    _G.IsControlJustPressed = _G.clientSetControl or _G.IsControlJustPressed
                    _G.PlaySound = _G.clientSetSound or _G.PlaySound
                    _G.SimpleNotify = _G.clientSetNotify or _G.SimpleNotify
                    _G.GetClosestPlayer = _G.clientSetClosest or _G.GetClosestPlayer

                    return targetPlayer, math.random(100) / 100
                end

                MainAPI.SafeRunNative(FreezeEntityPosition, selfPed, true)

                local startTimer = GetGameTimer()

                while (GetGameTimer() - startTimer) <= 2000 do
                    local setTargetCoords = getTargetCoords()

                    if not setTargetCoords then
                        cleanupBring()
                        return
                    end

                    setSelfCoords(setTargetCoords)

                    Wait(0)
                end

                MainAPI.SafeRunNative(TriggerEvent, 'ClientEmoteRequestReceive', emote, 'shared')

                MainAPI.SafeRunNative(SetTimeout, 2500, function()
                    if not didPlay and _G.clientBringingPlayer then
                        cleanupBring()
                    end
                end)
            end)
        ]]):gsub('SET_TARGET', id))
    else
        print('Couldn\'t find server exploit')
    end
end

