local currentSelection = 1
local currentTab = 1
local menuHistory = {}
local currentMenu
local savedMenuState = nil
local lastHoveredTab = nil
local lastHoveredIndex = nil
local lastHoveredOptionId = nil

local function cacheCurrentMenuState()
    savedMenuState = {
        menu = currentMenu,
        tab = currentTab,
        selection = currentSelection,
        history = {}
    }

    for i, v in ipairs(menuHistory) do
        table.insert(savedMenuState.history, v)
    end
end

local function preserveComponentStates(oldOptions, newOptions)
    if not oldOptions or not newOptions then
        return newOptions
    end
    
    local oldOptionsById = {}
    for _, oldOption in ipairs(oldOptions) do
        if oldOption.id then
            oldOptionsById[oldOption.id] = oldOption
        end
    end

    for _, newOption in ipairs(newOptions) do
        local oldOption = newOption.id and oldOptionsById[newOption.id]

        if oldOption then
            if newOption.checkbox and oldOption.checkbox and not newOption.checkbox.forceUpdate then
                newOption.checkbox.checked = oldOption.checkbox.checked
            end
            
            if newOption.range and oldOption.range and not newOption.range.forceUpdate then
                newOption.range.value = oldOption.range.value
            end
            
            if newOption.slider and oldOption.slider and not newOption.slider.forceUpdate then
                newOption.slider.value = oldOption.slider.value
            end


            if not newOption.setBindData and oldOption.setBindData then
                newOption.setBindData = oldOption.setBindData
            end
        end
    end
    
    return newOptions
end

local function processLiveOption(option)
    if not option then
        return option
    end
    
    if option.liveName and type(option.liveName) == 'function' then
        option.name = option.liveName()
    end
    
    if option.button and option.button.liveLabel and type(option.button.liveLabel) == 'function' then
        option.button.label = option.button.liveLabel()
    end
    
    return option
end

local lastResolvedOptions = {}

function resolveTabOptions(tab, tabIndex, ...)
    if tab.liveOptions and type(tab.liveOptions) == 'function' then
        local oldOptions = lastResolvedOptions[tabIndex]
        local selectedId = nil

        if oldOptions and currentMenu._selections and currentMenu._selections[tabIndex] then
            local selectionIndex = currentMenu._selections[tabIndex]
            if oldOptions[selectionIndex] and oldOptions[selectionIndex].id then
                selectedId = oldOptions[selectionIndex].id
            end
        end

        local newOptions = tab.liveOptions(...)

        newOptions = preserveComponentStates(oldOptions, newOptions)

        for i = 1, #newOptions do
            newOptions[i] = processLiveOption(newOptions[i])
        end
        
        local newSelectionIndex = nil
        if selectedId then
            for i, option in ipairs(newOptions) do
                if option.id == selectedId then
                    newSelectionIndex = i
                    break
                end
            end
        end

        if newSelectionIndex then
            currentMenu._selections[tabIndex] = newSelectionIndex
            if tabIndex == currentTab then
                currentSelection = newSelectionIndex
            end
        else
            local oldSelectionIndex = currentMenu._selections and currentMenu._selections[tabIndex] or 1
            local newCount = #newOptions
            local newIndex = math.max(1, math.min(oldSelectionIndex, newCount))
            local finalIndex = nil

            for i = newIndex, newCount do
                if newOptions[i] and not newOptions[i].separator then
                    finalIndex = i
                    break
                end
            end

            if not finalIndex then
                for i = newIndex - 1, 1, -1 do
                    if newOptions[i] and not newOptions[i].separator then
                        finalIndex = i
                        break
                    end
                end
            end

            if not finalIndex then
                for i = 1, newCount do
                    if newOptions[i] and not newOptions[i].separator then
                        finalIndex = i
                        break
                    end
                end
            end

            if finalIndex then
                currentMenu._selections[tabIndex] = finalIndex
                if tabIndex == currentTab then
                    currentSelection = finalIndex
                end
            end
        end
        
        lastResolvedOptions[tabIndex] = newOptions
        return newOptions
    else
        local options = tab.options or {}
        lastResolvedOptions[tabIndex] = options
        return options
    end
end

local function resolveTabTooltip(tab)
    if tab.liveTooltip and type(tab.liveTooltip) == 'function' then
        return tab.liveTooltip()
    elseif tab.tooltip then
        return tab.tooltip
    end

    return nil
end

local function createResolvedMenu(menu)
    local resolvedMenu = {
        tabs = {},
        _selections = menu._selections,
        _lastTab = menu._lastTab
    }
    
    for i, tab in ipairs(menu.tabs) do
        local resolvedTab = {
            label = tab.label,
            options = resolveTabOptions(tab, i),
            tooltip = resolveTabTooltip(tab)
        }

        table.insert(resolvedMenu.tabs, resolvedTab)
    end
    
    return resolvedMenu
end

local optionBinds = {}

local function updateLiveTooltip()
    if not menuOpen or not currentMenu or not currentMenu.tabs or not currentMenu.tabs[currentTab] then
        return
    end

    local originalTabData = currentMenu.tabs[currentTab]
    if not originalTabData then
        MachoExecuteDuiScript(menuDui, 'window.updateTooltip(null);')
        return
    end

    local tooltipData = nil
    if originalTabData.liveTooltip and type(originalTabData.liveTooltip) == 'function' then
        tooltipData = originalTabData.liveTooltip()
    elseif originalTabData.tooltip then
        tooltipData = originalTabData.tooltip
    end

    if tooltipData then
        local tooltipJson = json.encode(tooltipData)
        MachoExecuteDuiScript(menuDui, string.format('window.updateTooltip(%s);', tooltipJson))
    else
        MachoExecuteDuiScript(menuDui, 'window.updateTooltip(null);')
    end
end

function getCurrentOptions()
    local currentTabData = currentMenu.tabs[currentTab]
    if not currentTabData then return {} end
    return resolveTabOptions(currentTabData, currentTab)
end

local function updateHelpMessage()
    if not menuOpen or not currentMenu or not currentMenu.tabs or not currentMenu.tabs[currentTab] then
        MachoExecuteDuiScript(menuDui, 'window.updateHelpMessage(null);')
        return
    end

    local currentOptions = getCurrentOptions()
    local currentOption = currentOptions[currentSelection]
    
    if currentOption then
        local helpMessage = nil
        
        if currentOption.liveHelpMessage and type(currentOption.liveHelpMessage) == 'function' then
            helpMessage = currentOption.liveHelpMessage()
        elseif currentOption.helpMessage then
            helpMessage = currentOption.helpMessage
        end
        
        if helpMessage then
            MachoExecuteDuiScript(menuDui, string.format('window.updateHelpMessage(%s);', json.encode(helpMessage)))
        else
            MachoExecuteDuiScript(menuDui, 'window.updateHelpMessage(null);')
        end
    else
        MachoExecuteDuiScript(menuDui, 'window.updateHelpMessage(null);')
    end
end

local function updateHoverCallbacks()
    if not menuOpen or not currentMenu or not currentMenu.tabs or not currentMenu.tabs[currentTab] then
        if lastHoveredTab and lastHoveredIndex then
            local lastTabData = currentMenu and currentMenu.tabs and currentMenu.tabs[lastHoveredTab]
            if lastTabData then
                if lastTabData.unHover then
                    local lastOptions = resolveTabOptions(lastTabData, lastHoveredTab)
                    local lastOption = lastOptions[lastHoveredIndex]
                    if lastOption then
                        lastTabData.unHover(lastHoveredIndex, lastOption, true)
                    end
                end
                
                local lastOptions = resolveTabOptions(lastTabData, lastHoveredTab)
                local lastOption = lastOptions[lastHoveredIndex]
                if lastOption and lastOption.unHover then
                    lastOption.unHover(lastHoveredIndex, lastOption, true)
                end
            end
            lastHoveredTab = nil
            lastHoveredIndex = nil
            lastHoveredOptionId = nil
        end
        
        MachoExecuteDuiScript(menuDui, 'window.updateHelpMessage(null);')
        return
    end

    local currentOptions = getCurrentOptions()
    local currentOption = currentOptions[currentSelection]
    local currentTabData = currentMenu.tabs[currentTab]
    local currentOptionId = currentOption and currentOption.id
    
    if lastHoveredTab and lastHoveredIndex then
        local needsUnHover = false
        local leftTab = false
        
        if lastHoveredTab ~= currentTab then
            needsUnHover = true
            leftTab = true
        elseif lastHoveredIndex ~= currentSelection then
            needsUnHover = true
            leftTab = false
        elseif lastHoveredOptionId ~= currentOptionId then
            needsUnHover = true
            leftTab = false
        end
        
        if needsUnHover then
            local lastTabData = currentMenu.tabs[lastHoveredTab]
            if lastTabData then
                local lastOptions = resolveTabOptions(lastTabData, lastHoveredTab)
                local lastOption = lastOptions[lastHoveredIndex]
                
                if lastOption then
                    if lastTabData.unHover then
                        lastTabData.unHover(lastHoveredIndex, lastOption, leftTab)
                    end
                    
                    if lastOption.unHover then
                        lastOption.unHover(lastHoveredIndex, lastOption, leftTab)
                    end
                end
            end
        end
    end
    
    if currentOption and (lastHoveredTab ~= currentTab or lastHoveredIndex ~= currentSelection or lastHoveredOptionId ~= currentOptionId) then
        if currentTabData and currentTabData.onHover then
            currentTabData.onHover(currentSelection, currentOption, false)
        end
        
        if currentOption.onHover then
            currentOption.onHover(currentSelection, currentOption, false)
        end
    end
    
    lastHoveredTab = currentTab
    lastHoveredIndex = currentSelection
    lastHoveredOptionId = currentOptionId
    
    updateHelpMessage()
end

local function updateMenu()
    local resolvedMenu = createResolvedMenu(currentMenu)
    local menuJson = json.encode(resolvedMenu)
    local tabJson = json.encode(currentTab)
    local selectionJson = json.encode(currentSelection)
    
    MachoExecuteDuiScript(menuDui, string.format([[
        window.updateMenuData(%s);
        window.updateTab(%s - 1);
        window.updateSelection(%s - 1);
    ]], menuJson, tabJson, selectionJson))
    
    updateLiveTooltip()
end

local inputActive = false
local inputValue = ''
local inputCallback = nil
local inputHeader = ''
local inputPlaceholder = ''
local inputMaxLength = 100
local inputSelectionStart = 0
local inputSelectionEnd = 0
local inputHasSelection = false
local keyStates = {}
local keyCodes = {
    CTRL = 17,
    SHIFT = 16,
    ALT = 18,
    BACKSPACE = 8,
    DELETE = 46,
    ENTER = 13,
    ESCAPE = 27,
    TAB = 9,
    LEFT_ARROW = 37,
    UP_ARROW = 38,
    RIGHT_ARROW = 39,
    DOWN_ARROW = 40,
    HOME = 36,
    END = 35,
    PAGE_UP = 33,
    PAGE_DOWN = 34
}

function isKeyHeld(keyCode)
    return keyStates[keyCode] == true
end

function isCtrlHeld()
    return isKeyHeld(keyCodes.CTRL)
end

function isShiftHeld()
    return isKeyHeld(keyCodes.SHIFT)
end

function getCharFromKey(keyCode)
    local char = keyMap[keyCode]
    if not char then
        return
    end
    
    if isShiftHeld() then
        if keyCode >= 65 and keyCode <= 90 then
            return char
        elseif keyCode >= 48 and keyCode <= 57 then
            return shiftedNumbers[keyCode] or char
        else
            return shiftedChars[keyCode] or char
        end
    else
        if keyCode >= 65 and keyCode <= 90 then
            return string.lower(char)
        end
        
        return char
    end
end

local function deleteSelection()
    if inputHasSelection then
        local startPos = math.min(inputSelectionStart, inputSelectionEnd)
        local endPos = math.max(inputSelectionStart, inputSelectionEnd)
        inputValue = string.sub(inputValue, 1, startPos) .. string.sub(inputValue, endPos + 1)
        inputSelectionStart = startPos
        inputSelectionEnd = startPos
        inputHasSelection = false

        return true
    end

    return false
end

local function selectAllText()
    inputSelectionStart = 0
    inputSelectionEnd = string.len(inputValue)
    inputHasSelection = true

    local inputData = {
        value = inputValue,
        header = inputHeader,
        placeholder = inputPlaceholder,
        selectionStart = inputSelectionStart,
        selectionEnd = inputSelectionEnd,
        hasSelection = inputHasSelection
    }
    
    MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(inputData)))
end

local function copySelectedText()
    if inputHasSelection then
        local startPos = math.min(inputSelectionStart, inputSelectionEnd)
        local endPos = math.max(inputSelectionStart, inputSelectionEnd)
        local selectedText = string.sub(inputValue, startPos + 1, endPos)
        
        local copyData = {
            text = selectedText,
            selectionStart = inputSelectionStart,
            selectionEnd = inputSelectionEnd,
            hasSelection = inputHasSelection
        }
        
        MachoExecuteDuiScript(menuDui, string.format('window.copyToClipboardWithSelection(%s);', json.encode(copyData)))

        return true
    end

    return false
end

local function pasteText()
    local text = MachoGetClipboardText()
    
    if not text or text == '' then
        return false
    end
    
    saveInputState()
    deleteSelection()
    
    if inputMaxLength then
        local remainingSpace = inputMaxLength - string.len(inputValue)
        if remainingSpace <= 0 then
            return false
        end
        text = string.sub(text, 1, remainingSpace)
    end
    
    inputValue = string.sub(inputValue, 1, inputSelectionStart) .. text .. string.sub(inputValue, inputSelectionStart + 1)
    inputSelectionStart = inputSelectionStart + string.len(text)
    inputSelectionEnd = inputSelectionStart
    inputHasSelection = false
    
    local inputData = {
        value = inputValue,
        header = inputHeader,
        placeholder = inputPlaceholder,
        selectionStart = inputSelectionStart,
        selectionEnd = inputSelectionEnd,
        hasSelection = inputHasSelection
    }
    
    MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(inputData)))

    return true
end

local inputHistory = {}
local inputHistoryIndex = 0
local MAX_HISTORY_SIZE = 50

function saveInputState()
    while #inputHistory > inputHistoryIndex do
        table.remove(inputHistory)
    end
    
    table.insert(inputHistory, {
        value = inputValue,
        selectionStart = inputSelectionStart,
        selectionEnd = inputSelectionEnd,
        hasSelection = inputHasSelection
    })
    
    if #inputHistory > MAX_HISTORY_SIZE then
        table.remove(inputHistory, 1)
    else
        inputHistoryIndex = inputHistoryIndex + 1
    end
end

local function restoreInputState(state)
    if not state then return end
    
    inputValue = state.value
    inputSelectionStart = state.selectionStart
    inputSelectionEnd = state.selectionEnd
    inputHasSelection = state.hasSelection
    
    local inputData = {
        value = inputValue,
        header = inputHeader,
        placeholder = inputPlaceholder,
        selectionStart = inputSelectionStart,
        selectionEnd = inputSelectionEnd,
        hasSelection = inputHasSelection
    }
    
    MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(inputData)))
end

local function handleUndo()
    if inputHistoryIndex > 1 then
        inputHistoryIndex = inputHistoryIndex - 1
        restoreInputState(inputHistory[inputHistoryIndex])
        return true
    end
    return false
end

local function handleRedo()
    if inputHistoryIndex < #inputHistory then
        inputHistoryIndex = inputHistoryIndex + 1
        restoreInputState(inputHistory[inputHistoryIndex])
        return true
    end
    return false
end

local function insertCharacter(char)
    if not char then
        return false
    end

    deleteSelection()

    if inputMaxLength and string.len(inputValue) >= inputMaxLength then
        return false
    end

    saveInputState()
    
    inputValue = string.sub(inputValue, 1, inputSelectionStart) .. char .. string.sub(inputValue, inputSelectionStart + 1)
    inputSelectionStart = inputSelectionStart + 1
    inputSelectionEnd = inputSelectionStart

    return true
end

local function handleBackspace()
    saveInputState()
    
    if inputHasSelection then
        deleteSelection()
    elseif inputSelectionStart > 0 then
        inputValue = string.sub(inputValue, 1, inputSelectionStart - 1) .. string.sub(inputValue, inputSelectionStart + 1)
        inputSelectionStart = inputSelectionStart - 1
        inputSelectionEnd = inputSelectionStart
    end
end

local function handleDelete()
    saveInputState()
    
    if inputHasSelection then
        deleteSelection()
    elseif inputSelectionStart < string.len(inputValue) then
        inputValue = string.sub(inputValue, 1, inputSelectionStart) .. string.sub(inputValue, inputSelectionStart + 2)
    end
end

local function moveCursorLeft()
    if inputHasSelection then
        inputSelectionStart = math.min(inputSelectionStart, inputSelectionEnd)
        inputSelectionEnd = inputSelectionStart
        inputHasSelection = false
    elseif inputSelectionStart > 0 then
        inputSelectionStart = inputSelectionStart - 1
        inputSelectionEnd = inputSelectionStart
    end
end

local function moveCursorRight()
    if inputHasSelection then
        inputSelectionStart = math.max(inputSelectionStart, inputSelectionEnd)
        inputSelectionEnd = inputSelectionStart
        inputHasSelection = false
    elseif inputSelectionStart < string.len(inputValue) then
        inputSelectionStart = inputSelectionStart + 1
        inputSelectionEnd = inputSelectionStart
    end
end

local function moveCursorHome()
    inputSelectionStart = 0
    inputSelectionEnd = 0
    inputHasSelection = false
end

local function moveCursorEnd()
    inputSelectionStart = string.len(inputValue)
    inputSelectionEnd = inputSelectionStart
    inputHasSelection = false
end

function showInput(header, placeholder, callback, maxLength, initialValue)
    inputActive = true
    inputValue = initialValue or ''
    inputCallback = callback
    inputHeader = header or ''
    inputPlaceholder = placeholder or ''
    inputMaxLength = maxLength
    inputSelectionStart = string.len(inputValue)
    inputSelectionEnd = inputSelectionStart
    inputHasSelection = false
    
    inputHistory = {{
        value = inputValue,
        selectionStart = inputSelectionStart,
        selectionEnd = inputSelectionEnd,
        hasSelection = inputHasSelection
    }}
    inputHistoryIndex = 1
    
    local inputData = {
        value = inputValue,
        header = inputHeader,
        placeholder = inputPlaceholder,
        selectionStart = inputSelectionStart,
        selectionEnd = inputSelectionEnd,
        hasSelection = inputHasSelection
    }

    MainAPI.InjectCode(commonResource, [[
        MainAPI.CreateTrackedThread('InputFocus', {
            thread = function(self)
                while self.isActive do
                    SetNuiFocus(true, true)
                    Wait(0)
                end
            end,
            onRemove = function()
                SetNuiFocus(false, false)
            end
        })
    ]])

    MachoExecuteDuiScript(menuDui, string.format('window.showInput(%s);', json.encode(inputData)))
end

function hideInput()
    inputActive = false
    inputValue = nil
    inputCallback = nil
    inputHistory = {}
    inputHistoryIndex = 0

    MachoExecuteDuiScript(menuDui, 'window.hideInput();')
    MainAPI.InjectCode(commonResource, [[
        MainAPI.DeleteTrackedThread('InputFocus')
    ]])
end

function isInputActive()
    return inputActive
end

