        }

        #header-wrapper {
            background-color: ${backColor};
            border-radius: 0.45vh;
            overflow: hidden;
            margin-bottom: 0.45vh;
            opacity: 0;
            transform: translateY(-0.9vh);
            transition: opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1), 
                       transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        #header-wrapper.visible {
            opacity: 1;
            transform: translateY(0);
        }

        #header-wrapper.hiding {
            opacity: 0;
            transform: translateY(-0.9vh);
        }

        #menu-container {
            background-color: rgba(${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}, ${backColorRGB.a});
            border-radius: 0.45vh;
            overflow: hidden;
            position: relative;
            opacity: 0;
            transform: translateY(-0.45vh);
            transition: opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1), 
                       transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        #menu-container.visible {
            opacity: 1;
            transform: translateY(0);
        }

        #menu-container.hiding {
            opacity: 0;
            transform: translateY(-0.45vh);
        }

        #menu-banner {
            padding: 0;
            overflow: hidden;
