        }

        #menu-tabs {
            display: flex;
        }

        .tab-item {
            flex: 1;
            min-width: 0;
            padding: 0.6vh 0;
            font-size: 0.9vh;
            text-align: center;
            cursor: pointer;
            color: rgba(255, 255, 255, 0.6);
            background: transparent;
            border-bottom-left-radius: 0.5vh;
            border-bottom-right-radius: 0.5vh;
            transition: 0.3s;
            position: relative;
            overflow: hidden;
        }
        
        .tab-item::before {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(to top, rgb(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.3) 0%, transparent 85%);
            transform: scaleY(0);
            transform-origin: bottom;
            transition: 0.5s;
            z-index: -1;
        }
        
        .tab-item.single {
            min-width: 8vh;
            flex-grow: 0;
            padding: 0.8vh 1vh;
            flex-basis: auto;
        }
        
        .tab-item.active {
            color: white;
            font-weight: 500;
        }
        
        .tab-item.active::before {
            transform: scaleY(1);
        }

        #menu-items {
            position: relative;
            max-height: 39vh;
            overflow: hidden;
        }

        #items-list {
            position: relative;
            transition: transform 0.25s ease-out;
        }
            
        .menu-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 1vh 1vh;
            font-size: 1.2vh;
            border-radius: 0.2vh;
            transition: background-color 0.2s ease-in-out;
            height: 3vh;
            box-sizing: border-box;
        }

        .name-container {
            display: flex;
            align-items: center;
            gap: 0.9vh;
            min-width: 0;
        }

        .name-container .name {
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .menu-item-icon {
            width: 1.4vh;
            height: 1.4vh;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
            color: rgba(255, 255, 255);
        }

        .menu-item-icon svg {
            width: 100%;
            height: 100%;
        }

        .separator-container {
            display: flex;
            align-items: center;
            width: 100%;
            gap: 1vh;
        }

        .separator-bar {
            flex: 1;
            height: 0.3vh;
            background-color: rgba(255, 255, 255, 0.8);
            min-width: 2vh;
            border-radius: 0.2vh;
        }

        .separator-text {
            color: rgba(255, 255, 255, 0.9);
            font-weight: 500;
            white-space: nowrap;
            padding: 0 0.5vh;
        }

        .menu-item.separator {
            justify-content: center;
            font-weight: 500;
            color: rgba(255, 255, 255, 0.6);
            padding: 0.8vh 1.5vh;
            pointer-events: none;
        }

        .menu-item.highlighted {
            /* Not used */
        }

        #selection-highlight {
            position: absolute;
            margin-top: 0.2vh;
            left: 0.2vh;
            right: 0.2vh;
            height: 2.4vh;
            background-color: rgba(var(--main-rgb), 0.35);
            border: 0.1vh solid rgba(var(--main-rgb), 0.35);
            box-shadow: 0 0 0.2vh 0.2vh rgba(var(--main-rgb), 0.45);
            border-radius: 0.4vh;
            z-index: -1;
            transition: top 0.25s ease-out;
        }

        .components-container {
            display: flex;
            gap: 1vh;
            align-items: center;
        }

        .component {
            display: flex;
            align-items: center;
            gap: 0.5vh;
        }

        .component.icon {
            order: -1;
        }

        .submenu-arrow-icon {
            width: 1.4vh;
            height: 1.4vh;
            color: rgba(255, 255, 255, 0.75);
            flex-shrink: 0;
        }

        .component .icon-image {
            width: auto;
            height: 1.6vh;
            object-fit: contain;
            flex-shrink: 0;
        }

        .component .slider-component {
            display: flex;
            align-items: center;
            justify-content: center;
            width: auto;
            font-size: 1.2vh;
            text-align: center;
            user-select: none;
        }

        .component .slider-component span {
            margin: 0 0.8vh;
            min-width: 5vh;
            position: relative;
            left: 1vh;
        }

        .component .slider-component span::before {
            content: '- ';
            color: rgba(255, 255, 255, 0.6);
        }

        .component .slider-component span::after {
            content: ' -';
            color: rgba(255, 255, 255, 0.6);
        }
 
        .component .range-component {
            position: relative;
            width: 8vh;
            height: 2vh;
            display: flex;
            align-items: center;
        }

        .component .range-value {
            position: absolute;
            top: -1.6vh;
            left: 50%;
            transform: translateX(-50%) scale(0);
            background: #333;
            color: #fff;
            padding: 0.2vh 0.6vh;
            border-radius: 0.3vh;
            font-size: 1.1vh;
            transition: transform 0.15s ease-out, opacity 0.15s ease-out;
            opacity: 0;
            pointer-events: none;
        }

        .component .range-component:hover .range-value {
            transform: translateX(-50%) scale(1);
            opacity: 1;
        }

        .component .range-track {
            position: absolute;
            left: 0;
            width: 100%;
            height: 0.4vh;
            background-color: rgba(255, 255, 255, 0.2);
            border-radius: 0.2vh;
            z-index: 1;
        }

        .component .range-fill {
            position: absolute;
            left: 0;
            height: 0.4vh;
            background-color: #fff;
            border-radius: 0.2vh;
            z-index: 2;
        }

        .component input[type="range"] {
            -webkit-appearance: none;
            appearance: none;
            width: 100%;
            height: 0.4vh;
            background: transparent;
            outline: none;
            padding: 0;
            margin: 0;
            cursor: pointer;
            position: relative;
            z-index: 3;
        }
    
        .component input[type="range"]::-webkit-slider-thumb {
            -webkit-appearance: none;
            appearance: none;
            width: 1.4vh;
            height: 1.4vh;
            background: #fff;
            border-radius: 50%;
            cursor: pointer;
            margin-top: 0;
        }
        
        .component input[type="range"]::-moz-range-thumb {
            width: 1.4vh;
            height: 1.4vh;
            background: #fff;
            border-radius: 50%;
            cursor: pointer;
            border: none;
        }
    
        .component button {
            background: #4a4a4a;
            border: none;
            color: white;
            padding: 0.3vh 0.8vh;
            border-radius: 0.3vh;
            font-size: 1.2vh;
            cursor: pointer;
            transition: background 0.2s ease;
        }

        .component button:hover {
            background: #6a6a6a;
        }

        .component input[type="checkbox"] {
            -webkit-appearance: none;
            appearance: none;
            background-color: #333;
            margin: 0;
            width: 3.3vh;
            height: 1.4vh;
            border-radius: 1vh;
            cursor: pointer;
            position: relative;
            transition: background-color 0.2s ease-in-out, border-color 0.2s ease-in-out;
        }

        .component input[type="checkbox"]::after {
            content: '';
            position: absolute;
            top: 0.2vh;
            left: 0.2vh;
            width: 1vh;
            height: 1vh;
            background-color: #f0f0f0;
            border-radius: 50%;
            transition: left 0.2s ease-in-out;
        }

        .component input[type="checkbox"]:checked {
            background-color: rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.75);
        }

        .component input[type="checkbox"]:checked::after {
            left: 2vh;
        }

