        #scrollbar-thumb:hover {
            background-color: rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.9);
        }

        #menu-container {
            background-color: rgba(${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}, ${backColorRGB.a});
            border-radius: 0.45vh;
            overflow: hidden;
