        }

        .notification {
            width: 100%;
            min-height: 4.5vh;
            background-color: rgba(${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}, ${backColorRGB.a});
            border-radius: 0.6vh;
            padding: 1.1vh 1.3vh;
            display: flex;
            flex-direction: row;
            align-items: center;
            gap: 1vh;
            word-wrap: break-word;
            word-break: break-word;
            hyphens: auto;
            box-sizing: border-box;
            transform: translateY(-100%);
            opacity: 0;
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
            position: relative;
            overflow: hidden;
        }

        .notification-content {
            display: flex;
            flex-direction: column;
            gap: 0.35vh;
            flex: 1;
            min-width: 0;
        }

        .notification.show {
            transform: translateX(0);
            opacity: 1;
        }

        .notification.hide {
            transform: translateX(100%);
            opacity: 0;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.6, 1);
        }

        .notification-header {
            font-weight: 600;
            font-size: 1.4vh;
            color: white;
            margin-bottom: 0.15vh;
            line-height: 1.3;
            word-wrap: break-word;
