        }

        .notification-message {
            font-size: 1.1vh;
            color: rgba(255, 255, 255, 0.85);
            line-height: 1.4;
            word-wrap: break-word;
            word-break: break-word;
            hyphens: auto;
        }

        .notification-progress {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 0.3vh;
        }

        .notification-progress-bar {
            position: absolute;
            top: 0;
            left: 0;
            height: 100%;
            width: 100%;
            transform-origin: left;
            transition: transform linear;
        }

