            transition: opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1),
                       transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            overflow: hidden;
        }

        .live-list-container.visible {
            opacity: 1;
            transform: scale(1);
        }

        .live-list-container.hiding {
            opacity: 0;
            transform: scale(0.95);
        }

        .live-list-header {
            position: relative;
            background-color: rgba(var(--back-rgb), var(--back-alpha));
            border-bottom: 0.1vh solid var(--main-color);
