            transition: opacity 0.22s ease, transform 0.22s cubic-bezier(.2, .9, .3, 1.1);
        }

        #watermark-container.visible {
            opacity: 1;
            transform: translateY(0);
            pointer-events: auto;
        }

        #watermark-container.centered {
            transform: translate(-50%, -8px);
        }

        #watermark-container.centered.visible {
            transform: translate(-50%, 0);
        }

