        #help-message-container {
            position: fixed;
            bottom: 4vh;
            left: 50%;
            transform: translateX(-50%);
            z-index: 1500;
            font-family: sans-serif;
            opacity: 0;
            transform: translateX(-50%) translateY(1vh);
            transition: opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1), 
                       transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            pointer-events: none;
        }

        #help-message-container.visible {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
        }

        #help-message-container.hiding {
            opacity: 0;
            transform: translateX(-50%) translateY(1vh);
        }

        #help-message {
            color: rgb(255, 255, 255, 0.8);
            padding: 0.8vh 1.6vh;
            border-radius: 0.5vh;
            font-size: 1.1vh;
            font-weight: 400;
