        #progress-container {
            position: fixed;
            opacity: 0;
            top: 0;
            left: 0;
            transform: none;
            width: 100%;
            height: 100%;
            z-index: 999999;
            color: white;
            font-weight: 300;
            font-family: sans-serif;
            font-size: 1.2vh;
            transition: opacity 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        }

        #progress-box {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%,-50%);
            width: 38vh;
            box-sizing: border-box;
            padding: 2.4vh 2.6vh 2.2vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.9vh;
            border-radius: 1.2vh;
            border: 0.1vh solid rgba(255, 255, 255, 0.08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, 0.045) 0%, rgba(255, 255, 255, 0) 45%),
                rgba(${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}, ${backColorRGB.a});
            -webkit-backdrop-filter: blur(1.6vh);
            box-shadow:
                0 1.6vh 4vh rgba(0, 0, 0, 0.55),
                0 0 2.5vh rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.14),
                inset 0 0.1vh 0 rgba(255, 255, 255, 0.07);
            animation: progress-box-in 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
        }

        @keyframes progress-box-in {
            from {
                opacity: 0;
                transform: translate(-50%, -46%) scale(0.94);
            }
            to {
                opacity: 1;
                transform: translate(-50%, -50%) scale(1);
            }
        }

        #progress-top-text {
            color: rgba(255, 255, 255, 0.95);
            font-size: 1.35vh;
            font-weight: 500;
            letter-spacing: 0.06vh;
            text-align: center;
            line-height: 1.35;
            text-shadow: 0 0.1vh 0.4vh rgba(0, 0, 0, 0.6);
        }

        #progress-bar-container {
            position: relative;
            margin: 0.6vh 0 0.2vh;
            width: 100%;
            height: 0.7vh;
            overflow: hidden;
            background-color: rgba(255, 255, 255, 0.07);
            box-shadow: inset 0 0.1vh 0.25vh rgba(0, 0, 0, 0.5);
            border-radius: 0.4vh;
        }

        #progress-bar {
            position: relative;
            width: 0%;
            height: 100%;
            box-sizing: border-box;
            background: linear-gradient(90deg,
                rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.65) 0%,
                ${mainColor} 65%,
                rgba(255, 255, 255, 0.85) 100%);
            box-shadow:
                0 0 0.5vh rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.85),
                0 0 1.4vh rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.45);
            transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1);
            border-radius: 0.4vh;
        }

        #progress-bar::after {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            border-radius: 0.4vh;
            background: linear-gradient(90deg,
                rgba(255, 255, 255, 0) 0%,
                rgba(255, 255, 255, 0.35) 50%,
                rgba(255, 255, 255, 0) 100%);
            animation: progress-shimmer 1.6s linear infinite;
        }

        @keyframes progress-shimmer {
            from { transform: translateX(-100%); }
            to { transform: translateX(100%); }
        }

        #progress-percent-text {
            color: rgba(255, 255, 255, 0.98);
            font-size: 1.9vh;
            font-weight: 600;
            letter-spacing: 0.05vh;
            font-variant-numeric: tabular-nums;
            text-align: center;
            text-shadow:
                0 0.1vh 0.4vh rgba(0, 0, 0, 0.65),
                0 0 1.6vh rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.5);
        }

        #progress-bottom-text {
            color: rgba(255, 255, 255, 0.55);
            font-size: 1.15vh;
            font-weight: 400;
            text-align: center;
            line-height: 1.4;
            text-shadow: 0 0.1vh 0.35vh rgba(0, 0, 0, 0.6);
        }

        .hovering-text-wrap {
            position: fixed;
            bottom: 7.5vh;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            outline: none;
            min-width: 18.52vh;
            z-index: 99999;
            font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial;
        }
		
        .hovering-text-list {
            list-style: none;
            margin: 0;
            padding: 0;
            text-align: center;
            pointer-events: none;
            user-select: none;
            max-height: calc(9 * (1.3vh * 1.3 + 0.37vh));
            overflow-y: auto;
            overflow-x: hidden;
            scrollbar-width: none;
            -ms-overflow-style: none;
            display: flex;
            flex-direction: column;
            align-items: center;
            scroll-behavior: smooth;
        }

        .hovering-text-list::-webkit-scrollbar {
            display: none;
        }

        .hovering-text-item {
            padding: 0.15vh 0;
            font-size: 1.1vh;
            line-height: 1.3;
            transition: transform 0.22s cubic-bezier(.2,.9,.2,1), color 0.22s cubic-bezier(.2,.9,.2,1), letter-spacing 0.22s;
            transform-origin: center;
            white-space: nowrap;
            min-width: 27.78vh;
            font-weight: 600;
            color: #fff;
        }

		.hovering-text-inactive {
			color: rgba(255, 255, 255, 0.55);
			transform: scale(0.98);
			letter-spacing: 0;
		}

        .hovering-text-selected {
            transform: scale(1.03);
            font-weight: 600;
            letter-spacing: 0.015vh;
            color: ${mainColor};
        }

        @keyframes hovering-text-pulse {
            0% { transform: translateY(-0.185vh) scale(1.03); }
            30% { transform: translateY(-0.556vh) scale(1.08); }
            100% { transform: translateY(-0.185vh) scale(1.03); }
        }

        .hovering-text-activated {
            animation: hovering-text-pulse 0.42s cubic-bezier(.2,.9,.3,1) both;
        }

        .hovering-text-toast {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            bottom: 8vh;
            background: transparent;
            padding: 0.556vh 1.111vh;
            border-radius: 0.741vh;
            font-weight: 600;
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.26s ease;
            color: ${mainColor};
        }

        .hovering-text-toast.visible {
            opacity: 1;
        }

        [data-hovering-text-hidden="true"] {
            display: none !important;
        }
    `;
    
    document.head.appendChild(style);

    menuRoot.innerHTML = `
        <div id="header-wrapper">
            <div id="menu-banner">
                <img src="DEFAULT_BANNER" alt="Menu Banner" id="banner-image">
            </div>
            <div id="menu-tabs"></div>
        </div>
        <div id="menu-container">
            <div id="menu-items">
                <div id="selection-highlight"></div>
                <div id="items-list"></div>
            </div>
        </div>
        <div id="menu-scrollbar">
            <div id="scrollbar-track">
                <div id="scrollbar-thumb"></div>
            </div>
        </div>
        <div id="menu-footer">
           <span id="footer-left">SET_FOOTER</span>
            <span id="footer-right">0/0</span>
        </div>
    `;
    
    const tooltipContainer = document.createElement('div');
    tooltipContainer.id = 'tooltip-container';
    document.body.appendChild(tooltipContainer);

    let currentHelpMessage = null;

    const helpMessageContainer = document.createElement('div');
    helpMessageContainer.id = 'help-message-container';
    document.body.appendChild(helpMessageContainer);

    const helpMessage = document.createElement('div');
    helpMessage.id = 'help-message';
    helpMessageContainer.appendChild(helpMessage);

    const notificationContainer = document.createElement('div');
    notificationContainer.id = 'notification-container';
    document.body.appendChild(notificationContainer);

    const inputDialog = document.createElement('div');
    inputDialog.className = 'input-overlay';
    inputDialog.style.opacity = '0';

    const inputContainer = document.createElement('div');
    inputContainer.className = 'input-box';

    const inputHeader = document.createElement('div');
    inputHeader.className = 'input-header';

    const inputHeaderInner = document.createElement('div');
    inputHeaderInner.className = 'input-header-inner';

    const inputIcon = document.createElement('img');
    inputIcon.src = 'DEFAULT_ICON';

    const inputDivider = document.createElement('div');
    inputDivider.className = 'input-divider';

    const headerText = document.createElement('div');
    headerText.className = 'input-header-text';

    inputHeaderInner.appendChild(inputIcon);
    inputHeaderInner.appendChild(inputDivider);
    inputHeaderInner.appendChild(headerText);
    inputHeader.appendChild(inputHeaderInner);

    const inputBox = document.createElement('input');

    inputContainer.appendChild(inputHeader);
    inputContainer.appendChild(inputBox);
    inputDialog.appendChild(inputContainer);
    document.body.appendChild(inputDialog);
    
    const hoveringTextWrap = document.createElement('div');
    hoveringTextWrap.className = 'hovering-text-wrap';
    hoveringTextWrap.tabIndex = 0;
    hoveringTextWrap.setAttribute('role', 'listbox');
    hoveringTextWrap.setAttribute('aria-hidden', 'false');
    document.body.appendChild(hoveringTextWrap);

    const hoveringTextListEl = document.createElement('ul');
    hoveringTextListEl.className = 'hovering-text-list';
    hoveringTextWrap.appendChild(hoveringTextListEl);

    const hoveringTextToast = document.createElement('div');
    hoveringTextToast.className = 'hovering-text-toast';
    hoveringTextToast.setAttribute('role', 'status');
    hoveringTextToast.setAttribute('aria-live', 'polite');
    document.body.appendChild(hoveringTextToast);

    let hoveringTextVisible = false;
    let hoveringTextSelectedIndex = 0;
    let hoveringTextOptions = [];
    let hoveringTextItems = [];

    function hoveringTextClamp(value, min, max) {
        return Math.max(min, Math.min(max, value));
    };

    function hoveringTextWrapIndex(index) {
        return hoveringTextItems.length ? ((index % hoveringTextItems.length + hoveringTextItems.length) % hoveringTextItems.length) : 0;
    };

    function hoveringTextFindNearestIndex(prevId) {
        if (!hoveringTextItems.length) return 0;
        const idx = hoveringTextItems.findIndex(it => it.dataset.id === prevId);
        if (idx >= 0) return idx;
        return hoveringTextClamp(hoveringTextSelectedIndex, 0, hoveringTextItems.length - 1);
    };

    function hoveringTextRenderList(preserveSelectedId = null) {
        const prevSelectedId = preserveSelectedId ?? (hoveringTextItems[hoveringTextSelectedIndex] && hoveringTextItems[hoveringTextSelectedIndex].dataset.id);
        hoveringTextListEl.innerHTML = '';

        hoveringTextOptions.forEach((opt, i) => {
            const li = document.createElement('li');
            li.className = 'hovering-text-item';
            li.dataset.id = String(opt.id);

            let fullData;
            if (opt.data && opt.data.trim() !== '') {
                fullData = `${opt.name} ${opt.data}`;
            } else {
                fullData = `${opt.name}`;
            };
            
            li.dataset.data = fullData;
            
            li.textContent = String(opt.name);
            li.id = `hovering-text-opt-${i}`;
            hoveringTextListEl.appendChild(li);
        });

        hoveringTextItems = Array.from(hoveringTextListEl.querySelectorAll('.hovering-text-item'));
        hoveringTextSelectedIndex = hoveringTextFindNearestIndex(prevSelectedId);
        hoveringTextUpdateSelection();
    }

    function hoveringTextUpdateMask() {
        const scrollTop = hoveringTextListEl.scrollTop;
        const scrollHeight = hoveringTextListEl.scrollHeight;
        const clientHeight = hoveringTextListEl.clientHeight;
        const scrollBottom = scrollHeight - scrollTop - clientHeight;
        const fadeDistance = 50;
        const topFadeAmount = Math.min(scrollTop / fadeDistance, 1);
        const bottomFadeAmount = Math.min(scrollBottom / fadeDistance, 1);
        const topFade = topFadeAmount * 15;
        const bottomFade = 100 - (bottomFadeAmount * 15);
        const safeTopFade = Math.min(topFade, bottomFade - 5);
        const safeBottomFade = Math.max(bottomFade, topFade + 5);
        const gradient = `linear-gradient(to bottom, transparent 0%, black ${safeTopFade}%, black ${safeBottomFade}%, transparent 100%)`;
        
        hoveringTextListEl.style.maskImage = gradient;
        hoveringTextListEl.style.webkitMaskImage = gradient;
    };

    function hoveringTextScrollToSelected() {
        if (!hoveringTextItems.length || hoveringTextSelectedIndex < 0) return;
        
        const selectedEl = hoveringTextItems[hoveringTextSelectedIndex];
        if (!selectedEl) return;
        
        selectedEl.scrollIntoView({
            behavior: 'smooth',
            block: 'center'
        });
    };
 
    function hoveringTextUpdateSelection() {
        if (!hoveringTextItems.length) {
            hoveringTextSelectedIndex = 0;
            hoveringTextListEl.innerHTML = '';
            return;
        }

        hoveringTextItems.forEach((it, i) => {
            const isSelected = i === hoveringTextSelectedIndex;
            it.classList.toggle('hovering-text-selected', isSelected);
            it.classList.toggle('hovering-text-inactive', !isSelected);

            if (isSelected) {
                const data = it.dataset.data;
                const hasParentheses = data.includes('(');

                if (hasParentheses) {
                    const coloredText = data.replace(/\(([^)]+)\)/g, `(<span style="color: ${mainColor};">$1</span>)`);
                    it.innerHTML = `<span style="color: #fff;">${coloredText}</span>`;
                } else {
                    it.innerHTML = `<span style="color: ${mainColor};">${data}</span>`;
                }

                it.setAttribute('aria-current', 'true');
                hoveringTextWrap.setAttribute('aria-activedescendant', it.id);
            } else {
                const opt = hoveringTextOptions.find(o => String(o.id) === it.dataset.id);
                it.textContent = opt ? opt.name : it.textContent;
                it.style.color = '';
                it.removeAttribute('aria-current');
            }
        });
        
        hoveringTextScrollToSelected();
        setTimeout(hoveringTextUpdateMask, 50);
    };

    function hoveringTextShowToast(text, ms = 900) {
        hoveringTextToast.textContent = text;
        hoveringTextToast.classList.add('visible');
        clearTimeout(hoveringTextShowToast._t);
        hoveringTextShowToast._t = setTimeout(() => hoveringTextToast.classList.remove('visible'), ms);
    }

    function hoveringTextActivateSelection() {
        const el = hoveringTextItems[hoveringTextSelectedIndex];
        if (!el) return null;

        el.classList.remove('hovering-text-activated');
        void el.offsetWidth;
        el.classList.add('hovering-text-activated');

        const id = el.dataset.id;
        const name = el.textContent.trim();

        hoveringTextShowToast(`Selected: ${name} (id: ${id})`);

        return { id, name };
    };

    hoveringTextListEl.addEventListener('scroll', hoveringTextUpdateMask);

    let hoveringTextTransitioning = false;
    let hoveringTextTransitionTimeout = null;

    window.hoveringText = {
        showList() {
            if (hoveringTextTransitionTimeout) {
                clearTimeout(hoveringTextTransitionTimeout);
                hoveringTextTransitionTimeout = null;
            }

            hoveringTextTransitioning = false;

            if (hoveringTextVisible) {
                hoveringTextWrap.removeAttribute('data-hovering-text-hidden');
                hoveringTextWrap.setAttribute('aria-hidden', 'false');
                hoveringTextWrap.style.transition = 'opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1), transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)';
                hoveringTextWrap.style.opacity = '1';
                hoveringTextWrap.style.transform = 'translateX(-50%) translateY(0)';
                hoveringTextRenderList();
                return;
            }

            hoveringTextVisible = true;
            hoveringTextTransitioning = true;
            
            hoveringTextWrap.removeAttribute('data-hovering-text-hidden');
            hoveringTextWrap.setAttribute('aria-hidden', 'false');
            
            hoveringTextWrap.style.transition = 'none';
            hoveringTextWrap.style.opacity = '0';
            hoveringTextWrap.style.transform = 'translateX(-50%) translateY(1vh)';
            
            setTimeout(() => {
                hoveringTextWrap.style.transition = 'opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1), transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)';
                hoveringTextWrap.style.opacity = '1';
                hoveringTextWrap.style.transform = 'translateX(-50%) translateY(0)';
                
                hoveringTextTransitionTimeout = setTimeout(() => {
                    hoveringTextTransitioning = false;
                    hoveringTextTransitionTimeout = null;
                }, 300);
            }, 10);
            
            hoveringTextWrap.focus();
            hoveringTextRenderList();
        },

        hideList() {
            if (hoveringTextTransitioning && !hoveringTextVisible) return;
            
            if (hoveringTextTransitionTimeout) {
                clearTimeout(hoveringTextTransitionTimeout);
                hoveringTextTransitionTimeout = null;
            }
            
            hoveringTextVisible = false;
            hoveringTextTransitioning = true;
            
            hoveringTextWrap.style.transition = 'opacity 0.3s cubic-bezier(0.4, 0, 0.6, 1), transform 0.3s cubic-bezier(0.4, 0, 0.6, 1)';
            hoveringTextWrap.style.opacity = '0';
            hoveringTextWrap.style.transform = 'translateX(-50%) translateY(1vh)';
            
            hoveringTextTransitionTimeout = setTimeout(() => {
                hoveringTextWrap.setAttribute('data-hovering-text-hidden', 'true');
                hoveringTextWrap.setAttribute('aria-hidden', 'true');
                try { hoveringTextWrap.blur(); } catch (e) {}
                hoveringTextTransitioning = false;
                hoveringTextTransitionTimeout = null;
            }, 300);
        },

        toggleVisibility() {
            if (hoveringTextVisible) this.hideList();
            else this.showList();
        },

        setOptions(newOptions = []) {
            hoveringTextOptions = newOptions.map(o => ({
                id: String(o.id),
                name: String(o.name),
                data: String(o.data || '')
            }));
            hoveringTextRenderList();
        },

        addOption(opt, atIndex = undefined) {
            const prevId = hoveringTextItems[hoveringTextSelectedIndex]?.dataset.id;
            const n = { 
                id: String(opt.id), 
                name: String(opt.name),
                data: String(opt.data || '')
            };

            if (atIndex === undefined) hoveringTextOptions.push(n);
            else hoveringTextOptions.splice(hoveringTextClamp(atIndex, 0, hoveringTextOptions.length), 0, n);

            hoveringTextRenderList(prevId);
        },

        removeOptionById(id) {
            const prevId = hoveringTextItems[hoveringTextSelectedIndex]?.dataset.id;
            const sid = String(id);
            const prevLen = hoveringTextOptions.length;

            hoveringTextOptions = hoveringTextOptions.filter(o => String(o.id) !== sid);

            if (hoveringTextOptions.length === prevLen) return false;

            hoveringTextRenderList(prevId);
            return true;
        },

        updateOption(id, newData) {
            const sid = String(id);
            const optIndex = hoveringTextOptions.findIndex(o => String(o.id) === sid);
            
            if (optIndex === -1) return false;
            
            const option = hoveringTextOptions[optIndex];
            const wasSelected = hoveringTextSelectedIndex === optIndex;
            
            if (newData.name !== undefined) {
                option.name = String(newData.name);
            }
            
            if (newData.data !== undefined) {
                option.data = String(newData.data || '');
            }
            
            if (wasSelected && hoveringTextVisible) {
                const selectedEl = hoveringTextItems[hoveringTextSelectedIndex];
                if (selectedEl) {
                    let fullData;
                    if (option.data && option.data.trim() !== '') {
                        fullData = `${option.name} ${option.data}`;
                    } else {
                        fullData = `${option.name}`;
                    }

                    selectedEl.dataset.data = fullData;

                    const hasParentheses = fullData.includes('(');

                    if (hasParentheses) {
                        const coloredText = fullData.replace(/\(([^)]+)\)/g, `(<span style="color: ${mainColor};">$1</span>)`);
                        selectedEl.innerHTML = `<span style="color: #fff;">${coloredText}</span>`;
                    } else {
                        selectedEl.innerHTML = `<span style="color: ${mainColor};">${fullData}</span>`;
                    }
                }
            } else {
                const el = hoveringTextItems[optIndex];
                if (el) {
                    let fullData;
                    if (option.data && option.data.trim() !== '') {
                        fullData = `${option.name} ${option.data}`;
                    } else {
                        fullData = `${option.name}`;
                    }

                    el.dataset.data = fullData;
                    el.textContent = option.name;
                }
            }
            
            return true;
        },

        getOptions() {
            return hoveringTextOptions.slice();
        },

        getSelected() {
            const el = hoveringTextItems[hoveringTextSelectedIndex];
            if (!el) return null;
            return {
                id: el.dataset.id,
                name: el.textContent.trim(),
                index: hoveringTextSelectedIndex
            };
        },

        selectById(id) {
            const sid = String(id);
            const idx = hoveringTextItems.findIndex(it => it.dataset.id === sid);
            if (idx >= 0) {
                hoveringTextSelectedIndex = idx;
                hoveringTextUpdateSelection();
                return true;
            }
            return false;
        },

        selectByIndex(i) {
            if (i < 0 || i >= hoveringTextItems.length) return false;
            hoveringTextSelectedIndex = i;
            hoveringTextUpdateSelection();
            return true;
        },

        activate() {
            return hoveringTextActivateSelection();
        },

        moveSelectionDown() {
            if (!hoveringTextVisible) return;
            hoveringTextSelectedIndex = hoveringTextWrapIndex(hoveringTextSelectedIndex + 1);
            hoveringTextUpdateSelection();
        },

        moveSelectionUp() {
            if (!hoveringTextVisible) return;
            hoveringTextSelectedIndex = hoveringTextWrapIndex(hoveringTextSelectedIndex - 1);
            hoveringTextUpdateSelection();
        },

        moveSelectionHome() {
            if (!hoveringTextVisible) return;
            hoveringTextSelectedIndex = 0;
            hoveringTextUpdateSelection();
        },

        moveSelectionEnd() {
            if (!hoveringTextVisible) return;
            hoveringTextSelectedIndex = Math.max(0, hoveringTextItems.length - 1);
            hoveringTextUpdateSelection();
        }
    };

    hoveringTextRenderList();
    hoveringTextUpdateMask();

    window.crosshair = {
        element: null,
        show() {
            if (!this.element) {
                this.element = document.createElement('div');
                this.element.id = 'screen-crosshair';
                this.element.style.cssText = `
                    position: fixed;
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%);
                    width: 0.9259vh;
                    height: 0.9259vh;
                    pointer-events: none;
                    z-index: 10000;
                    display: none;
                `;

                const hLine = document.createElement('div');
                hLine.style.cssText = `
                    position: absolute;
                    top: 50%;
                    left: 0;
                    width: 100%;
                    height: 0.185vh;
                    background-color: white;
                    transform: translateY(-50%);
                `;

                const vLine = document.createElement('div');
                vLine.style.cssText = `
                    position: absolute;
                    left: 50%;
                    top: 0;
                    width: 0.185vh;
                    height: 100%;
                    background-color: white;
                    transform: translateX(-50%);
                `;

                this.element.appendChild(hLine);
                this.element.appendChild(vLine);
                document.body.appendChild(this.element);
            };
            
            this.element.style.display = 'block';
        },
        hide() {
            if (this.element) {
                this.element.style.display = 'none';
            }
        }
    };
        
    window.showInput = function(data) {
        headerText.textContent = data.header || 'Enter Value';
        inputBox.value = data.value || '';
        inputBox.placeholder = data.placeholder || '';

        setTimeout(() => {
            inputDialog.style.opacity = '1';
            inputBox.focus();

            if (data.selectionStart !== undefined) {
                inputBox.setSelectionRange(data.selectionStart, data.selectionEnd || data.selectionStart);
            }
        }, 10);
    };
    
    window.hideInput = function() {
        inputDialog.style.opacity = '0';
    };
    
    window.updateInput = function(data) {
        inputBox.value = data.value || '';

        if (data.selectionStart !== undefined) {
            inputBox.setSelectionRange(data.selectionStart, data.selectionEnd || data.selectionStart);
        }
    };

    window.copyToClipboardWithSelection = function(data) {
        const textArea = document.createElement('textarea');
        textArea.value = data.text;
        textArea.style.position = 'fixed';
        textArea.style.opacity = '0';
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);
        
        const inputElement = document.querySelector('.input-box input');
        if (inputElement) {
            inputElement.setSelectionRange(data.selectionStart, data.selectionEnd);
            inputElement.focus();
        }
    };

    window.updateMenuBanner = function(data) {
        if (!data || !data.banner) return;
        
        const bannerElement = document.getElementById('banner-image');
        if (bannerElement) {
            bannerElement.src = data.banner;
        }
    };

    window.updateMenuColors = function(colors) {
        if (!colors) return;
        
        let setMainColor = colors.mainColor;
        let setBackColor = colors.backColor;
        
        if (setMainColor) {
            mainColor = setMainColor;
            mainColorRGB = hexToRgb(setMainColor);
        }
        
        if (setBackColor) {
            backColor = setBackColor;
            backColorRGB = hexToRgb(setBackColor);
            backColorRGB.a = 0.8;
        }
        
        const rootStyle = document.documentElement.style;

        if (mainColorRGB) {
            rootStyle.setProperty('--main-color', mainColor);
            rootStyle.setProperty('--main-rgb', `${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}`);
        }

        if (backColorRGB) {
            rootStyle.setProperty('--back-color', backColor);
            rootStyle.setProperty('--back-rgb', `${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}`);
            rootStyle.setProperty('--back-alpha', `${backColorRGB.a}`);
        }

        const styleElement = document.querySelector('style');
        if (!styleElement) return;

        let currentCSS = styleElement.textContent;

        if (mainColorRGB) {
            const brightness = (mainColorRGB.r * 299 + mainColorRGB.g * 587 + mainColorRGB.b * 114) / 1000;
            const textColor = brightness > 200 ? 'black' : 'white';

            currentCSS = currentCSS.replace(
                /background:\s*linear-gradient\(to top,\s*rgb\(\d+,\s*\d+,\s*\d+,\s*[\d.]+\)[^)]*\)/g,
                `background: linear-gradient(to top, rgb(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.3) 0%, transparent 85%)`
            );
            
            currentCSS = currentCSS.replace(
                /\.component input\[type="checkbox"\]:checked\s*\{[^}]*background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*0\.75\)/g,
                match => match.replace(/background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*0\.75\)/, `background-color: rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.75)`)
            );
            
            currentCSS = currentCSS.replace(
                /#scrollbar-thumb\s*\{[^}]*background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*0\.7\)/g,
                match => match.replace(/background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*0\.7\)/, `background-color: rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.7)`)
            );
            
            currentCSS = currentCSS.replace(
                /#scrollbar-thumb:hover\s*\{[^}]*background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*0\.9\)/g,
                match => match.replace(/background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*0\.9\)/, `background-color: rgba(${mainColorRGB.r}, ${mainColorRGB.g}, ${mainColorRGB.b}, 0.9)`)
            );
            
            currentCSS = currentCSS.replace(
                /\.input-box > \.input-header\s*\{[^}]*border-bottom:\s*0\.1vh solid #[0-9a-fA-F]{6}/g,
                match => match.replace(/border-bottom:\s*0\.1vh solid #[0-9a-fA-F]{6}/, `border-bottom: 0.1vh solid ${mainColor}`)
            );
            
            currentCSS = currentCSS.replace(
                /\.input-box input::selection\s*\{[^}]*\}/g,
                `.input-box input::selection {
                    background-color: ${mainColor};
                    color: ${textColor};
                }`
            );

            currentCSS = currentCSS.replace(
                /\.notification-progress-bar\s*\{[^}]*background:\s*#[0-9a-fA-F]{6}/g,
                match => match.replace(/background:\s*#[0-9a-fA-F]{6}/, `background: ${mainColor}`)
            );

            currentCSS = currentCSS.replace(
                /\.hovering-text-selected\s*\{[^}]*color:\s*#[0-9a-fA-F]{6}/g,
                match => match.replace(/color:\s*#[0-9a-fA-F]{6}/, `color: ${mainColor}`)
            );

            currentCSS = currentCSS.replace(
