                match => match.replace(/color:\s*#[0-9a-fA-F]{6}/, `color: ${mainColor}`)
            );
        }

        if (backColorRGB) {
            currentCSS = currentCSS.replace(
                /#menu-footer\s*\{[^}]*background-color:\s*#[0-9a-fA-F]{6}/g,
                match => match.replace(/background-color:\s*#[0-9a-fA-F]{6}/, `background-color: ${backColor}`)
            );

            currentCSS = currentCSS.replace(
