            );
            
            currentCSS = currentCSS.replace(
                /#menu-container\s*\{[^}]*background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*[\d.]+\)/g,
                match => match.replace(/background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*[\d.]+\)/, `background-color: rgba(${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}, ${backColorRGB.a})`)
            );

            currentCSS = currentCSS.replace(
                /\.input-box\s*\{[^}]*background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*[\d.]+\)/g,
                match => match.replace(/background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*[\d.]+\)/, `background-color: rgba(${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}, ${backColorRGB.a})`)
            );
            
            currentCSS = currentCSS.replace(
                /\.notification\s*\{[^}]*background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*[\d.]+\)/g,
                match => match.replace(/background-color:\s*rgba\(\d+,\s*\d+,\s*\d+,\s*[\d.]+\)/, `background-color: rgba(${backColorRGB.r}, ${backColorRGB.g}, ${backColorRGB.b}, ${backColorRGB.a})`)
            );
            
