    let notificationId = 0;
    const activeNotifications = new Map();
    const typeColors = {
        success: 'rgba(44, 196, 90, 1)',
        warning: '#FF9800',
        error: '#F44336',
        info: '#2f94d8'
    };

    window.showNotification = function(setType = '', header = '', message = '', duration = 5000) {
        let setColor = typeColors[setType.toLowerCase()] || mainColor;

        const container = document.getElementById('notification-container') || createNotificationContainer();
        
        const notification = document.createElement('div');
        notification.className = `notification`;

        const contentEl = document.createElement('div');
        contentEl.className = 'notification-content';

        if (header) {
            const headerEl = document.createElement('div');
            headerEl.className = 'notification-header';
            headerEl.textContent = header;
            contentEl.appendChild(headerEl);
        }

        const messageEl = document.createElement('div');
        messageEl.className = 'notification-message';
        messageEl.textContent = message;
        contentEl.appendChild(messageEl);

        notification.appendChild(contentEl);

        const progress = document.createElement('div');
        progress.className = 'notification-progress';

        const progressBar = document.createElement('div');
        progressBar.className = 'notification-progress-bar';
        progressBar.style.background = setColor;
        progressBar.style.transitionDuration = `${duration}ms`;
        
        progress.appendChild(progressBar);
        notification.appendChild(progress);
        
        container.appendChild(notification);
        
        notification.offsetHeight;
        
        requestAnimationFrame(() => {
            notification.classList.add('show');
            
            requestAnimationFrame(() => {
                progressBar.style.transform = 'scaleX(0)';
            });
        });
        
        setTimeout(() => {
            notification.classList.remove('show');
            notification.classList.add('hide');
            setTimeout(() => {
                if (notification.parentNode) {
                    notification.parentNode.removeChild(notification);
                }
            }, 300);
        }, duration);
    };

    function createNotificationContainer() {
        const container = document.createElement('div');
        container.id = 'notification-container';
        document.body.appendChild(container);
        return container;
    }

    function hideNotification(id) {
        const notification = activeNotifications.get(id);
        if (!notification) return;
        
        notification.classList.remove('show');
        notification.classList.add('hide');
        
        setTimeout(() => {
            if (notification.parentNode) {
                notification.parentNode.removeChild(notification);
            }
            activeNotifications.delete(id);
        }, 400);
    }

    window.clearAllNotifications = function() {
        activeNotifications.forEach((notification, id) => {
            hideNotification(id);
        });
    };

    const liveLists = new Map();

    window.createLiveList = function(data) {
        if (!data || !data.id) return;

        let container = liveLists.get(data.id);
        
        if (!container) {
            container = document.createElement('div');
            container.className = 'live-list-container';
            container.id = `live-list-${data.id}`;
            document.body.appendChild(container);
            liveLists.set(data.id, container);
        }

        const header = document.createElement('div');
        header.className = 'live-list-header';

        const headerText = document.createElement('span');
        headerText.className = 'live-list-header-text';

        if (!data.icon) {
            headerText.style.textAlign = 'center';
        }

        headerText.textContent = data.header || 'Live List';
        header.appendChild(headerText);

        if (data.icon) {
            const iconEl = document.createElement('span');
            iconEl.className = 'live-list-header-icon';
            iconEl.dataset.icon = data.icon;
            iconEl.innerHTML = lucideIconSvg(data.icon);
            iconEl.setAttribute('aria-hidden', 'true');

            header.appendChild(iconEl);
        }

        const itemsContainer = document.createElement('div');
        itemsContainer.className = 'live-list-items';

        if (data.items && Array.isArray(data.items) && data.items.length > 0) {
            itemsContainer.style.opacity = 1;

            data.items.forEach(item => {
                const itemDiv = document.createElement('div');
                itemDiv.className = 'live-list-item';

                const label = document.createElement('span');
                label.className = 'live-list-label';
                label.textContent = item.label || '';

                const value = document.createElement('span');
                value.className = 'live-list-value';
                value.textContent = item.value || '';

                itemDiv.appendChild(label);
                itemDiv.appendChild(value);
                itemsContainer.appendChild(itemDiv);
            });
        } else {
            itemsContainer.style.opacity = 0;
        }

        container.innerHTML = '';
        container.appendChild(header);
        container.appendChild(itemsContainer);

        if (data.width) {
            container.style.width = data.width;
        }

        if (data.position) {
            if (data.position.top !== undefined && data.position.top !== null) {
                container.style.top = data.position.top;
                container.style.bottom = 'auto';
            } else if (data.position.bottom !== undefined && data.position.bottom !== null) {
                container.style.bottom = data.position.bottom;
                container.style.top = 'auto';
            }

            if (data.position.left !== undefined && data.position.left !== null) {
                container.style.left = data.position.left;
                container.style.right = 'auto';
            } else if (data.position.right !== undefined && data.position.right !== null) {
                container.style.right = data.position.right;
                container.style.left = 'auto';
            }
        }

        if (data.visible) {
            setTimeout(() => {
                container.classList.add('visible');
            }, 10);
        } else {
            container.classList.remove('visible');
        }
    };

    window.updateLiveList = function(data) {
        if (!data || !data.id) return;

        const container = liveLists.get(data.id);
        if (!container) {
            window.createLiveList(data);
            return;
        }

        const header = container.querySelector('.live-list-header');
        if (header) {
            if (data.header || data.icon !== undefined) {
                header.innerHTML = '';

                const headerText = document.createElement('span');
                headerText.className = 'live-list-header-text';

                if (!data.icon) {
                    headerText.style.textAlign = 'center';
                }

                headerText.textContent = data.header || 'Live List';
                header.appendChild(headerText);

                if (data.icon) {
                    const iconEl = document.createElement('span');
                    iconEl.className = 'live-list-header-icon';
                    iconEl.dataset.icon = data.icon;
                    iconEl.innerHTML = lucideIconSvg(data.icon);
                    iconEl.setAttribute('aria-hidden', 'true');
                    header.appendChild(iconEl);
                }
            }
        }

        const itemsContainer = container.querySelector('.live-list-items');
        if (itemsContainer && data.items !== undefined) {
            itemsContainer.innerHTML = '';

            if (Array.isArray(data.items) && data.items.length > 0) {
                itemsContainer.style.opacity = 1;

                data.items.forEach(item => {
                    const itemDiv = document.createElement('div');
                    itemDiv.className = 'live-list-item';

                    const label = document.createElement('span');
                    label.className = 'live-list-label';
                    label.textContent = item.label || '';

                    const value = document.createElement('span');
                    value.className = 'live-list-value';
                    value.textContent = item.value || '';

                    itemDiv.appendChild(label);
                    itemDiv.appendChild(value);
                    itemsContainer.appendChild(itemDiv);
                });
            } else {
                itemsContainer.style.opacity = 0;
            }
        }

        if (data.width) {
            container.style.width = data.width;
        }

        if (data.position) {
            if (data.position.top !== undefined && data.position.top !== null) {
                container.style.top = data.position.top;
                container.style.bottom = 'auto';
            } else if (data.position.bottom !== undefined && data.position.bottom !== null) {
                container.style.bottom = data.position.bottom;
                container.style.top = 'auto';
            }

            if (data.position.left !== undefined && data.position.left !== null) {
                container.style.left = data.position.left;
                container.style.right = 'auto';
            } else if (data.position.right !== undefined && data.position.right !== null) {
                container.style.right = data.position.right;
                container.style.left = 'auto';
            }
        }

        if (data.visible !== undefined) {
            if (data.visible) {
                container.classList.remove('hiding');
                container.classList.add('visible');
            } else {
                container.classList.remove('visible');
                container.classList.add('hiding');
            }
        }
    };

    window.showLiveList = function(id) {
        if (!id) return;

        const container = liveLists.get(id);
        if (!container) return;

        container.classList.remove('hiding');
        container.classList.add('visible');
    };

    window.hideLiveList = function(id) {
        if (!id) return;

        const container = liveLists.get(id);
        if (!container) return;

        container.classList.remove('visible');
        container.classList.add('hiding');
    };

    window.removeLiveList = function(id) {
        if (!id) return;

        const container = liveLists.get(id);
        if (!container) return;

        container.classList.remove('visible');
        container.classList.add('hiding');
        
        setTimeout(() => {
            if (container.parentNode) {
                container.parentNode.removeChild(container);
            }
            liveLists.delete(id);
        }, 300);
    };

    let watermarkEl = null;

    function getWatermark() {
        if (!watermarkEl) {
            watermarkEl = document.createElement('div');
            watermarkEl.id = 'watermark-container';
            document.body.appendChild(watermarkEl);
        }

        return watermarkEl;
    }

    window.setWatermark = function(data) {
        if (!data) return;

        const container = getWatermark();
        const segments = Array.isArray(data.segments) ? data.segments : [];

        container.innerHTML = '';

        segments.forEach((segment, index) => {
            if (index > 0) {
                const divider = document.createElement('div');
                divider.className = 'watermark-divider';
                container.appendChild(divider);
            }

            const segmentEl = document.createElement('div');
            segmentEl.className = segment.brand ? 'watermark-segment brand' : 'watermark-segment';

            if (segment.icon) {
                const iconEl = document.createElement('span');
                iconEl.className = 'watermark-icon';
                iconEl.innerHTML = lucideIconSvg(segment.icon);
                iconEl.setAttribute('aria-hidden', 'true');

                segmentEl.appendChild(iconEl);
            }

            if (segment.label) {
                const labelEl = document.createElement('span');
                labelEl.className = 'watermark-label';
                labelEl.textContent = segment.label;

                segmentEl.appendChild(labelEl);
            }

            const valueEl = document.createElement('span');
            valueEl.className = 'watermark-value';

            if (segment.dynamic) {
                valueEl.dataset.dynamic = segment.dynamic;
                valueEl.textContent = watermarkDynamicValue(segment.dynamic);
            } else {
                valueEl.textContent = segment.value !== undefined && segment.value !== null ? String(segment.value) : '';
            }

            segmentEl.appendChild(valueEl);
            container.appendChild(segmentEl);
        });

        if (data.position) {
            if (data.position.centered) {
                container.classList.add('centered');
                container.style.left = '50%';
                container.style.right = 'auto';
            } else {
                container.classList.remove('centered');

                if (data.position.left !== undefined && data.position.left !== null) {
                    container.style.left = data.position.left;
                    container.style.right = 'auto';
                } else if (data.position.right !== undefined && data.position.right !== null) {
                    container.style.right = data.position.right;
                    container.style.left = 'auto';
                }
            }

            if (data.position.top !== undefined && data.position.top !== null) {
                container.style.top = data.position.top;
                container.style.bottom = 'auto';
            } else if (data.position.bottom !== undefined && data.position.bottom !== null) {
                container.style.bottom = data.position.bottom;
                container.style.top = 'auto';
            }
        }

        if (data.visible && segments.length > 0) {
            setTimeout(() => {
                container.classList.add('visible');
            }, 10);

            if (!watermarkTicker) {
                watermarkTicker = setInterval(tickWatermark, 1000);
            }
        } else {
            container.classList.remove('visible');

            if (watermarkTicker) {
                clearInterval(watermarkTicker);
                watermarkTicker = null;
            }
        }
    };

    window.showWatermark = function() {
        getWatermark().classList.add('visible');

        if (!watermarkTicker) {
            watermarkTicker = setInterval(tickWatermark, 1000);
        }
    };

    window.hideWatermark = function() {
        getWatermark().classList.remove('visible');

        if (watermarkTicker) {
            clearInterval(watermarkTicker);
            watermarkTicker = null;
        }
    };

    const itemsList = document.getElementById('items-list');
    const tabsContainer = document.getElementById('menu-tabs');
    const selectionHighlight = document.getElementById('selection-highlight');
    const scrollbarThumb = document.getElementById('scrollbar-thumb');
    const scrollbarTrack = document.getElementById('scrollbar-track');
    const rangeAnimations = {};
    let menuConfig = [];
    let currentMenuConfig = {};
    let scrollOffset = 0;
    let currentSelectionIndex = 0;

    window.updateTooltip = function(tooltipData) {
        if (!tooltipData || tooltipData.length === 0) {
            tooltipContainer.classList.add('hiding');
            tooltipContainer.classList.remove('visible');
            
            setTimeout(() => {
                if (tooltipContainer.classList.contains('hiding')) {
                    tooltipContainer.style.display = 'none';
                    tooltipContainer.classList.remove('hiding');
                }
            }, 300);
            return;
        }

        if (tooltipContainer.classList.contains('hiding')) {
            tooltipContainer.classList.remove('hiding');
        }

        if (tooltipContainer.style.display === 'none') {
            tooltipContainer.style.display = 'block';
            tooltipContainer.offsetHeight;
        }

        const existingItems = tooltipContainer.querySelectorAll('.tooltip-item');
        const needsRebuild = existingItems.length !== tooltipData.length;

        if (needsRebuild) {
            tooltipContainer.innerHTML = '';
            tooltipData.forEach(item => {
                const itemEl = document.createElement('div');
                itemEl.className = 'tooltip-item';
                
                const labelEl = document.createElement('span');
                labelEl.className = 'tooltip-label';
                labelEl.textContent = item.label;
                
                const valueContainer = document.createElement('div');
                valueContainer.className = 'tooltip-value-container';
                
                if (item.icon) {
                    const iconEl = document.createElement('img');
                    iconEl.className = 'tooltip-icon';
                    iconEl.src = item.icon;
                    iconEl.alt = item.label || 'Tooltip icon';
                    iconEl.onerror = function() {
                        this.style.visibility = 'hidden';
                        this.style.width = '1.9vh';
                        this.style.height = '1.9vh';
                    };
                    valueContainer.appendChild(iconEl);
                } else {
                    const placeholderEl = document.createElement('div');
                    placeholderEl.style.width = '1.9vh';
                    placeholderEl.style.height = '1.9vh';
                    placeholderEl.style.flexShrink = '0';
                    placeholderEl.style.visibility = 'hidden';
                    placeholderEl.style.order = '-1';
                    valueContainer.appendChild(placeholderEl);
                }
                
                const valueEl = document.createElement('span');
                valueEl.className = 'tooltip-value';
                
                if (typeof item.text === 'object' && item.text !== null) {
                    valueEl.textContent = item.text.value !== undefined ? item.text.value : '';
                    valueEl.style.color = item.text.color || 'rgba(255, 255, 255, 0.85)';
                } else {
                    valueEl.textContent = item.text !== undefined ? item.text : (item.value !== undefined ? item.value : '');
                    valueEl.style.color = 'rgba(255, 255, 255, 0.85)';
                }

                valueContainer.appendChild(valueEl);
                
                if (item.bar) {
                    const barEl = document.createElement('div');
                    barEl.className = 'tooltip-bar';
                    
                    const barFillEl = document.createElement('div');
                    barFillEl.className = 'tooltip-bar-fill';
                    barFillEl.style.backgroundColor = item.bar.color || '#ffffff';
                    barFillEl.style.height = Math.max(0, Math.min(100, item.bar.percent || 0)) + '%';
                    
                    barEl.appendChild(barFillEl);
                    valueContainer.appendChild(barEl);
                }
                
                if (item.image) {
                    const imageEl = document.createElement('img');
                    imageEl.className = 'tooltip-image';
                    imageEl.src = item.image;
                    imageEl.alt = item.label || 'Tooltip image';
                    imageEl.onerror = function() {
                        this.style.display = 'none';
                    };

                    valueContainer.appendChild(imageEl);
                }
                
                itemEl.appendChild(labelEl);
                itemEl.appendChild(valueContainer);
                tooltipContainer.appendChild(itemEl);
            });
        } else {
            existingItems.forEach((itemEl, index) => {
                if (index >= tooltipData.length) return;
                const item = tooltipData[index];
                
                const valueContainer = itemEl.querySelector('.tooltip-value-container');
                if (!valueContainer) return;
                
                const valueEl = itemEl.querySelector('.tooltip-value');
                if (valueEl) {
                    if (typeof item.text === 'object' && item.text !== null) {
                        valueEl.textContent = item.text.value !== undefined ? item.text.value : '';
                        valueEl.style.color = item.text.color || 'rgba(255, 255, 255, 0.85)';
                    } else {
                        valueEl.textContent = item.text !== undefined ? item.text : (item.value !== undefined ? item.value : '');
                        valueEl.style.color = 'rgba(255, 255, 255, 0.85)';
                    }
                }
                
                const barFillEl = itemEl.querySelector('.tooltip-bar-fill');
                if (barFillEl && item.bar) {
                    barFillEl.style.backgroundColor = item.bar.color || '#ffffff';
                    barFillEl.style.height = Math.max(0, Math.min(100, item.bar.percent || 0)) + '%';
                }
                
                let iconEl = valueContainer.querySelector('.tooltip-icon');
                let placeholderEl = valueContainer.querySelector('div[style*="visibility: hidden"]');
                
                if (item.icon) {
                    if (!iconEl) {
                        if (placeholderEl) {
                            placeholderEl.remove();
                        }
                        iconEl = document.createElement('img');
                        iconEl.className = 'tooltip-icon';
                        iconEl.alt = item.label || 'Tooltip icon';
                        iconEl.onerror = function() {
                            this.style.visibility = 'hidden';
                            this.style.width = '1.9vh';
                            this.style.height = '1.9vh';
                        };
                        valueContainer.insertBefore(iconEl, valueContainer.firstChild);
                    }
                    iconEl.src = item.icon;
                    iconEl.style.visibility = 'visible';
                } else {
                    if (iconEl) {
                        iconEl.remove();
                    }

                    if (!placeholderEl) {
                        placeholderEl = document.createElement('div');
                        placeholderEl.style.width = '1.9vh';
                        placeholderEl.style.height = '1.9vh';
                        placeholderEl.style.flexShrink = '0';
                        placeholderEl.style.visibility = 'hidden';
                        placeholderEl.style.order = '-1';
                        valueContainer.insertBefore(placeholderEl, valueContainer.firstChild);
                    }
                }
                
                const imageEl = itemEl.querySelector('.tooltip-image');
                if (item.image) {
                    if (imageEl) {
                        if (imageEl.src !== item.image) {
                            imageEl.src = item.image;
                        }
                        imageEl.style.display = 'block';
                    } else {
                        const newImageEl = document.createElement('img');
                        newImageEl.className = 'tooltip-image';
                        newImageEl.src = item.image;
                        newImageEl.alt = item.label || 'Tooltip image';
                        newImageEl.onerror = function() {
                            this.style.display = 'none';
                        };
                        valueContainer.appendChild(newImageEl);
                    }
                } else if (imageEl) {
                    imageEl.remove();
                }
            });
        }

        try {
            if (!tooltipContainer.classList.contains('visible')) {
                requestAnimationFrame(() => {
                    tooltipContainer.classList.add('visible');
                });
            }
        } catch (error) {}
    };

    window.updateHelpMessage = function(helpMessageData) {
        if (helpMessageData && helpMessageData !== currentHelpMessage) {
            currentHelpMessage = helpMessageData;
            helpMessage.textContent = helpMessageData;
            
            if (!helpMessageContainer.classList.contains('visible')) {
                helpMessageContainer.classList.remove('hiding');
                helpMessageContainer.classList.add('visible');
            }
        } else if (!helpMessageData && currentHelpMessage) {
            currentHelpMessage = null;
            helpMessageContainer.classList.remove('visible');
            helpMessageContainer.classList.add('hiding');
            
            setTimeout(() => {
                if (!currentHelpMessage) {
                    helpMessageContainer.classList.remove('hiding');
                }
            }, 300);
        }
    };

    window.showMenu = function() {
        const menuRoot = document.getElementById('menu-root');
        const headerWrapper = document.getElementById('header-wrapper');
        const menuContainer = document.getElementById('menu-container');
        const menuFooter = document.getElementById('menu-footer');
        const scrollbar = document.getElementById('menu-scrollbar');
        
        if (window.hideMenuTimeout) {
            clearTimeout(window.hideMenuTimeout);
            window.hideMenuTimeout = null;
        }
        
        const isMenuHidden = menuRoot.style.display === 'none' || !menuRoot.classList.contains('visible');
        
        if (isMenuHidden) {
            [menuRoot, headerWrapper, menuContainer, menuFooter, scrollbar].forEach(el => {
                if (el) {
                    el.classList.remove('hiding', 'visible');
                }
            });
            
            menuRoot.style.display = 'block';
            menuRoot.offsetHeight;
            
            requestAnimationFrame(() => {
                menuRoot.classList.add('visible');
                
                if (headerWrapper) {
                    setTimeout(() => headerWrapper.classList.add('visible'), 50);
                }

                if (menuContainer) {
                    setTimeout(() => menuContainer.classList.add('visible'), 100);
                }

                if (menuFooter) {
                    setTimeout(() => menuFooter.classList.add('visible'), 150);
                }
                
                if (scrollbar) {
                    setTimeout(() => scrollbar.classList.add('visible'), 100);
                }
            });

            window.updateSelection(currentSelectionIndex);
        } else {
            [menuRoot, headerWrapper, menuContainer, menuFooter].forEach(el => {
                if (el) {
                    el.classList.remove('hiding');
                    if (!el.classList.contains('visible')) {
                        el.classList.add('visible');
                    }
                }
            });
            
            if (scrollbar) {
                scrollbar.classList.remove('hiding');

                if (!scrollbar.classList.contains('visible')) {
                    scrollbar.classList.add('visible');
                }
            }
        }
    };

    window.hideMenu = function() {
        const menuRoot = document.getElementById('menu-root');
        const headerWrapper = document.getElementById('header-wrapper');
        const menuContainer = document.getElementById('menu-container');
        const menuFooter = document.getElementById('menu-footer');
        const menuScrollbar = document.getElementById('menu-scrollbar');
        
        if (window.hideMenuTimeout) {
            clearTimeout(window.hideMenuTimeout);
            window.hideMenuTimeout = null;
        }
        
        [menuRoot, headerWrapper, menuContainer, menuFooter, menuScrollbar].forEach(el => {
            if (el) {
                el.classList.remove('visible');
                el.classList.add('hiding');
            }
        });
        
        window.hideMenuTimeout = setTimeout(() => {
            if (menuRoot && menuRoot.classList.contains('hiding')) {
                [menuRoot, headerWrapper, menuContainer, menuFooter, menuScrollbar].forEach(el => {
                    if (el) {
                        el.classList.remove('hiding', 'visible');
                    }
                });
            }
            window.hideMenuTimeout = null;
        }, 300);
    };

    window.buildMenu = function(config) {
        currentMenuConfig = config;
        const tabs = config.tabs || [{ label: 'Main', options: config.options || [] }];
        
        tabsContainer.innerHTML = '';
        if (tabs.length > 0) {
            tabs.forEach((tab, index) => {
                const tabEl = document.createElement('div');
                tabEl.className = 'tab-item';
                
                if (tabs.length === 1) {
                    tabEl.classList.add('single');
                }

                tabEl.textContent = tab.label;
                tabEl.dataset.index = index;
                tabsContainer.appendChild(tabEl);
            });
        }

        const menuRoot = document.getElementById('menu-root');
        const headerWrapper = document.getElementById('header-wrapper');
        const menuContainer = document.getElementById('menu-container');
        const menuFooter = document.getElementById('menu-footer');
        const scrollbar = document.getElementById('menu-scrollbar');
        
        menuRoot.style.display = 'block';

        [menuRoot, headerWrapper, menuContainer, menuFooter, scrollbar].forEach(el => {
            if (el) {
                el.classList.remove('visible', 'hiding');
            }
        });
        
        menuRoot.offsetHeight;
        
        setTimeout(() => {
            window.showMenu();
        }, 10);
    };

    window.updateMenuData = function(menuData) {
        currentMenuConfig = menuData;
        
        const tabsContainer = document.getElementById('menu-tabs');
        if (tabsContainer && menuData.tabs) {
            const currentTabCount = tabsContainer.children.length;

            if (currentTabCount !== menuData.tabs.length) {
                tabsContainer.innerHTML = '';

                if (menuData.tabs.length > 0) {
                    menuData.tabs.forEach((tab, index) => {
                        const tabEl = document.createElement('div');
                        tabEl.className = 'tab-item';
                        if (menuData.tabs.length === 1) {
                            tabEl.classList.add('single');
                        }
                        tabEl.textContent = tab.label;
                        tabEl.dataset.index = index;
                        tabsContainer.appendChild(tabEl);
                    });
                }
            } else {
                Array.from(tabsContainer.children).forEach((tabEl, index) => {
                    if (menuData.tabs[index]) {
                        tabEl.textContent = menuData.tabs[index].label;
                    }
                });
            }
        }
        
        updateCurrentTabItems();
    };

    window.updateTab = function(tabIndex) {
        window.currentTabIndex = tabIndex;
        
        const menuRoot = document.getElementById('menu-root');
        const headerWrapper = document.getElementById('header-wrapper');
        const menuContainer = document.getElementById('menu-container');
        const menuFooter = document.getElementById('menu-footer');
        const scrollbar = document.getElementById('menu-scrollbar');
        
        if (window.hideMenuTimeout) {
            clearTimeout(window.hideMenuTimeout);
            window.hideMenuTimeout = null;
        }
        
        [menuRoot, headerWrapper, menuContainer, menuFooter, scrollbar].forEach(el => {
            if (el) {
                el.classList.remove('hiding');
                el.classList.add('visible');
            }
        });
        
        const tabs = currentMenuConfig.tabs || [{ label: 'Main', options: currentMenuConfig.options || [] }];
        const currentTab = tabs[tabIndex];
        let options = [];

        if (currentTab) {
            options = currentTab.options || [];
        }

        menuConfig = options;

        const tabElements = tabsContainer.querySelectorAll('.tab-item');
        tabElements.forEach((el, index) => {
            if (index === tabIndex) {
                el.classList.add('active');
            } else {
                el.classList.remove('active');
            }
        });

        buildItemsForTab(options);
        
        currentSelectionIndex = 0;
        const firstValidIndex = findFirstValidItem(options);
        if (firstValidIndex !== -1) {
            currentSelectionIndex = firstValidIndex;
        }

        scrollOffset = 0;
        itemsList.style.transform = 'translateY(0px)';
        
        updateFooterInfo();
    };

    window.buildItemsForTab = function(options) {
        itemsList.innerHTML = '';
        
        options.forEach((option, index) => {
            const item = document.createElement('div');
            item.className = 'menu-item';
            item.dataset.index = index;
            
            if (option.separator) {
                item.classList.add('separator');
                const separatorContainer = document.createElement('div');
                separatorContainer.className = 'separator-container';
                
                const leftBar = document.createElement('div');
                leftBar.className = 'separator-bar';
                
                const text = document.createElement('div');
                text.className = 'separator-text';
                text.textContent = option.name || '';
                
                const rightBar = document.createElement('div');
                rightBar.className = 'separator-bar';
                
                separatorContainer.appendChild(leftBar);

                if (option.name) {
                    separatorContainer.appendChild(text);
                }

                separatorContainer.appendChild(rightBar);
                
                item.appendChild(separatorContainer);
            } else {
                const nameContainer = document.createElement('div');
                nameContainer.className = 'name-container';

                if (option.navIcon) {
                    const navIconEl = document.createElement('span');
                    navIconEl.className = 'menu-item-icon';
                    navIconEl.dataset.icon = option.navIcon;
                    navIconEl.innerHTML = lucideIconSvg(option.navIcon);
                    nameContainer.appendChild(navIconEl);
                }

                const nameSpan = document.createElement('span');
                nameSpan.className = 'name';
                nameSpan.textContent = option.name || '';
                nameContainer.appendChild(nameSpan);
                item.appendChild(nameContainer);

                const componentsContainer = document.createElement('div');
                componentsContainer.className = 'components-container';

                if (option.icon) {
                    const iconComponent = document.createElement('div');
                    iconComponent.className = 'component icon';
                    const iconImg = document.createElement('img');
                    iconImg.className = 'icon-image';
                    iconImg.src = option.icon;
                    iconComponent.appendChild(iconImg);
                    componentsContainer.appendChild(iconComponent);
                }

                if (option.range) {
                    const rangeComponent = document.createElement('div');
                    rangeComponent.className = 'component';
                    const rangeContainer = document.createElement('div');
                    rangeContainer.className = 'range-component';
                    
                    const rangeValue = document.createElement('div');
                    rangeValue.className = 'range-value';
                    rangeValue.textContent = option.range.value || 0;
                    
                    const rangeTrack = document.createElement('div');
                    rangeTrack.className = 'range-track';
                    
                    const rangeFill = document.createElement('div');
                    rangeFill.className = 'range-fill';
                    const percent = ((option.range.value - option.range.min) / (option.range.max - option.range.min)) * 100;
                    rangeFill.style.width = percent + '%';
                    
                    const rangeInput = document.createElement('input');
                    rangeInput.type = 'range';
                    rangeInput.min = option.range.min || 0;
                    rangeInput.max = option.range.max || 100;
                    rangeInput.step = option.range.step || 1;
                    rangeInput.value = option.range.value || 0;
                    
                    rangeContainer.appendChild(rangeValue);
                    rangeContainer.appendChild(rangeTrack);
                    rangeContainer.appendChild(rangeFill);
                    rangeContainer.appendChild(rangeInput);
                    rangeComponent.appendChild(rangeContainer);
                    componentsContainer.appendChild(rangeComponent);
                }
                
                if (option.slider) {
                    const sliderComponent = document.createElement('div');
                    sliderComponent.className = 'component';
                    const sliderContainer = document.createElement('div');
                    sliderContainer.className = 'slider-component';
                    
                    const sliderValue = document.createElement('span');
                    const currentOption = option.slider.options.find(opt => opt.value === option.slider.value);
                    sliderValue.textContent = currentOption ? currentOption.label : '';
                    
                    sliderContainer.appendChild(sliderValue);
                    sliderComponent.appendChild(sliderContainer);
                    componentsContainer.appendChild(sliderComponent);
                }

                if (option.checkbox) {
                    const checkboxComponent = document.createElement('div');
                    checkboxComponent.className = 'component';
                    const checkbox = document.createElement('input');
                    checkbox.type = 'checkbox';
                    checkbox.checked = option.checkbox.checked || false;
                    checkbox.disabled = option.checkbox.locked || false;
                    checkboxComponent.appendChild(checkbox);
                    componentsContainer.appendChild(checkboxComponent);
                }
                
                if (option.button) {
                    const buttonComponent = document.createElement('div');
                    buttonComponent.className = 'component';
                    const button = document.createElement('button');
                    button.textContent = option.button.label || '';
                    buttonComponent.appendChild(button);
                    componentsContainer.appendChild(buttonComponent);
                }
                
                item.appendChild(componentsContainer);
            }
            
            itemsList.appendChild(item);
        });
    };

    window.updateFooterInfo = function() {
        const footerRight = document.getElementById('footer-right');
        if (footerRight && menuConfig) {
            let totalOptions = 0;
            for (let i = 0; i < menuConfig.length; i++) {
                if (!menuConfig[i].separator) {
                    totalOptions++;
                }
            }
            
            let currentOptionNumber = 0;
            for (let i = 0; i <= currentSelectionIndex && i < menuConfig.length; i++) {
                if (!menuConfig[i].separator) {
                    currentOptionNumber++;
                }
            }
            
            footerRight.textContent = `${currentOptionNumber}/${totalOptions}`;
        }
    };

    window.findFirstValidItem = function(options) {
        for (let i = 0; i < options.length; i++) {
            if (!options[i].separator) {
                return i;
            }
        }
        return 0;
    };

    window.updateCurrentTabItems = function() {
        if (!currentMenuConfig || !currentMenuConfig.tabs) return;
        
        const currentTabData = currentMenuConfig.tabs[window.currentTabIndex || 0];
        if (!currentTabData) return;
        
        const options = currentTabData.options || [];
        
        buildItemsForTab(options);
        
        menuConfig = options;
        
        updateFooterInfo();
    };

    window.updateLiveTabContent = function(options, selectionIndex) {
        menuConfig = options;
        
        const currentItemElements = itemsList.querySelectorAll('.menu-item');
        const currentCount = currentItemElements.length;
        const newCount = options.length;
        
        let needsRebuild = currentCount !== newCount;
        
        if (!needsRebuild && currentCount > 0) {
            for (let i = 0; i < Math.min(currentCount, newCount); i++) {
                const currentEl = currentItemElements[i];
                const newOption = options[i];
                
                const currentIsSeparator = currentEl.classList.contains('separator');
                const newIsSeparator = !!newOption.separator;
                if (currentIsSeparator !== newIsSeparator) {
                    needsRebuild = true;
                    break;
                }
                
                const hasIcon = !!currentEl.querySelector('.icon-image');
                const hasCheckbox = !!currentEl.querySelector('input[type="checkbox"]');
                const hasRange = !!currentEl.querySelector('input[type="range"]');
                const hasSlider = !!currentEl.querySelector('.slider-component');
                const hasButton = !!currentEl.querySelector('button');
                const currentNavIconEl = currentEl.querySelector('.menu-item-icon');
                const hasNavIcon = !!currentNavIconEl;

                const needsIcon = !!(newOption.icon);
                const needsCheckbox = !!(newOption.checkbox);
                const needsRange = !!(newOption.range);
                const needsSlider = !!(newOption.slider);
                const needsButton = !!(newOption.button);
                const needsNavIcon = !!(newOption.navIcon);

                if (hasIcon !== needsIcon || hasCheckbox !== needsCheckbox || hasRange !== needsRange ||
                    hasSlider !== needsSlider || hasButton !== needsButton ||
                    hasNavIcon !== needsNavIcon ||
                    (hasNavIcon && needsNavIcon && currentNavIconEl.dataset.icon !== newOption.navIcon)) {
                    needsRebuild = true;
                    break;
                }
            }
        }
        
        if (needsRebuild) {
            itemsList.innerHTML = '';
            
            options.forEach((item, index) => {
                const itemEl = document.createElement('div');
                itemEl.className = 'menu-item';
                itemEl.dataset.index = index;

                if (item.separator) {
                    itemEl.classList.add('separator');
                    
                    const separatorContainer = document.createElement('div');
                    separatorContainer.className = 'separator-container';
                    
                    const leftBar = document.createElement('div');
                    leftBar.className = 'separator-bar';
                    
                    const separatorText = document.createElement('span');
                    separatorText.className = 'separator-text';
                    separatorText.textContent = item.name;
                    
                    const rightBar = document.createElement('div');
                    rightBar.className = 'separator-bar';
                    
                    separatorContainer.appendChild(leftBar);
                    separatorContainer.appendChild(separatorText);
                    separatorContainer.appendChild(rightBar);
                    
                    itemEl.appendChild(separatorContainer);
                } else {
                    const nameContainer = document.createElement('div');
                    nameContainer.className = 'name-container';

                    if (item.navIcon) {
                        const navIconEl = document.createElement('span');
                        navIconEl.className = 'menu-item-icon';
                        navIconEl.dataset.icon = item.navIcon;
                        navIconEl.innerHTML = lucideIconSvg(item.navIcon);
                        nameContainer.appendChild(navIconEl);
                    }

                    const nameSpan = document.createElement('span');
                    nameSpan.className = 'name';
                    nameSpan.textContent = item.name;
                    nameContainer.appendChild(nameSpan);
                    itemEl.appendChild(nameContainer);
                }

                const componentsContainer = document.createElement('div');
                componentsContainer.className = 'components-container';

                if (item.icon) {
                    const iconDiv = document.createElement('div');
                    iconDiv.className = 'component icon';
                    const iconImg = document.createElement('img');
                    iconImg.className = 'icon-image';
                    iconImg.src = item.icon;
                    iconImg.alt = 'Option icon';
                    iconImg.onerror = function() {
                        this.style.display = 'none';
                    };
                    iconDiv.appendChild(iconImg);
                    componentsContainer.appendChild(iconDiv);
                }

                if (item.checkbox && !item.range && !item.slider) {
                    const componentDiv = document.createElement('div');
                    componentDiv.className = 'component';
                    const checkbox = document.createElement('input');
                    checkbox.type = 'checkbox';
                    checkbox.checked = item.checkbox.checked;
                    componentDiv.appendChild(checkbox);
                    componentsContainer.appendChild(componentDiv);
                }

                if (item.range) {
                    const componentDiv = document.createElement('div');
                    componentDiv.className = 'component';

                    const rangeContainer = document.createElement('div');
                    rangeContainer.className = 'range-component';

                    const rangeTrack = document.createElement('div');
                    rangeTrack.className = 'range-track';

                    const rangeFill = document.createElement('div');
                    rangeFill.className = 'range-fill';

                    const rangeValue = document.createElement('div');
                    rangeValue.className = 'range-value';

                    const rangeInput = document.createElement('input');
                    rangeInput.type = 'range';
                    rangeInput.min = item.range.min;
                    rangeInput.max = item.range.max;
                    rangeInput.step = item.range.step;
                    rangeInput.value = item.range.value;

                    const updateRangeUI = (target) => {
                        const min = parseFloat(target.min);
                        const max = parseFloat(target.max);
                        const val = parseFloat(target.value);
                        const percentage = ((val - min) * 100) / (max - min);
                        rangeFill.style.width = `${percentage}%`;
                        rangeValue.textContent = val.toFixed(val % 1 === 0 ? 0 : 2);
                        
                        const thumbStyle = window.getComputedStyle(target, '::-webkit-slider-thumb');
                        const thumbWidth = parseFloat(thumbStyle.width) || 0;
                        const trackWidth = target.offsetWidth;
                        const thumbPosition = (percentage / 100) * (trackWidth - thumbWidth) + (thumbWidth / 2);
                        rangeValue.style.left = `${thumbPosition}px`;
                    };

                    rangeInput.addEventListener('input', (e) => {
                        updateRangeUI(e.target);
                    });

                    rangeInput.addEventListener('change', (e) => {
                        updateRangeUI(e.target);
                    });

                    rangeContainer.appendChild(rangeTrack);
                    rangeContainer.appendChild(rangeFill);
                    rangeContainer.appendChild(rangeValue);
                    rangeContainer.appendChild(rangeInput);
                    componentDiv.appendChild(rangeContainer);
                    componentsContainer.appendChild(componentDiv);

                    setTimeout(() => updateRangeUI(rangeInput), 0);
                }

                if (item.slider) {
                    const componentDiv = document.createElement('div');
                    componentDiv.className = 'component';
                    
                    const sliderContainer = document.createElement('div');
                    sliderContainer.className = 'slider-component';
                    
                    const leftArrow = document.createElement('div');
                    leftArrow.className = 'arrow';
                    leftArrow.innerHTML = '&lt;';
                    
                    const labelSpan = document.createElement('span');
                    const initialOption = item.slider.options[item.slider.value - 1];
                    labelSpan.textContent = initialOption ? initialOption.label : 'N/A';
                    
                    const rightArrow = document.createElement('div');
                    rightArrow.className = 'arrow';
                    rightArrow.innerHTML = '&gt;';
                    
                    sliderContainer.appendChild(leftArrow);
                    sliderContainer.appendChild(labelSpan);
                    sliderContainer.appendChild(rightArrow);
                    
                    componentDiv.appendChild(sliderContainer);
                    componentsContainer.appendChild(componentDiv);
                }

                if (item.button) {
                    const componentDiv = document.createElement('div');
                    componentDiv.className = 'component';
                    const button = document.createElement('button');
                    button.textContent = item.button.label;
                    componentDiv.appendChild(button);
                    componentsContainer.appendChild(componentDiv);
                }

                if (item.checkbox && (item.range || item.slider)) {
                    const componentDiv = document.createElement('div');
                    componentDiv.className = 'component';
                    const checkbox = document.createElement('input');
                    checkbox.type = 'checkbox';
                    checkbox.checked = item.checkbox.checked;
                    componentDiv.appendChild(checkbox);
                    componentsContainer.appendChild(componentDiv);
                }

                if (componentsContainer.hasChildNodes()) {
                    itemEl.appendChild(componentsContainer);
                }
                
                itemsList.appendChild(itemEl);
            });
            
            scrollOffset = 0;
            itemsList.style.transform = 'translateY(0px)';
        } else {
            const itemElements = itemsList.querySelectorAll('.menu-item');
            itemElements.forEach((el, index) => {
                if (index >= options.length) return;
                const item = options[index];
                
                const nameSpan = el.querySelector('.name');
                if (nameSpan && nameSpan.textContent !== item.name) {
                    nameSpan.textContent = item.name;
                }

                const iconImage = el.querySelector('.icon-image');
                if (iconImage && item.icon && item.icon != iconImage.src) {
                    iconImage.src = item.icon;
                }

                const checkbox = el.querySelector('input[type="checkbox"]');
                if (checkbox && item.checkbox) {
                    checkbox.checked = item.checkbox.checked;
                }

                const rangeInput = el.querySelector('input[type="range"]');
                if (rangeInput && item.range) {

                if (rangeInput.min !== item.range.min.toString()) rangeInput.min = item.range.min;
                    if (rangeInput.max !== item.range.max.toString()) rangeInput.max = item.range.max;
                    if (rangeInput.step !== item.range.step.toString()) rangeInput.step = item.range.step;
                    if (rangeInput.value !== item.range.value.toString()) {
                        rangeInput.value = item.range.value;
                        rangeInput.dispatchEvent(new Event('input', { 'bubbles': true }));
                    }
                }

                const sliderLabel = el.querySelector('.slider-component span');
                if (sliderLabel && item.slider) {
                    const currentOption = item.slider.options[item.slider.value - 1];
                    const newText = currentOption ? currentOption.label : 'N/A';
                    if (sliderLabel.textContent !== newText) {
                        sliderLabel.textContent = newText;
                    }
                }

                const button = el.querySelector('button');
                if (button && item.button && button.textContent !== item.button.label) {
                    button.textContent = item.button.label;
                }
            });
        }
        
        if (selectionIndex !== undefined) {
            window.updateSelection(selectionIndex);
        }
    }

    window.updateRange = function(itemIndex, newValue) {
        const itemEl = itemsList.querySelector(`.menu-item[data-index="${itemIndex}"]`);
        if (!itemEl) return;

        const rangeInput = itemEl.querySelector('input[type="range"]');
        if (!rangeInput) return;

        rangeInput.value = newValue;

        const rangeFill = itemEl.querySelector('.range-fill');
        const rangeValue = itemEl.querySelector('.range-value');

        if (rangeFill && rangeValue) {
            const min = parseFloat(rangeInput.min);
            const max = parseFloat(rangeInput.max);
            const val = parseFloat(rangeInput.value);
            const percentage = ((val - min) * 100) / (max - min);
            rangeFill.style.width = `${percentage}%`;
            rangeValue.textContent = val.toFixed(val % 1 === 0 ? 0 : 2);
            const thumbWidth = 14;
            const trackWidth = rangeInput.offsetWidth;
            const thumbPosition = (percentage / 100) * (trackWidth - thumbWidth) + (thumbWidth / 2);
            rangeValue.style.left = `${thumbPosition}px`;
            
            if (itemEl.classList.contains('highlighted')) {
                const nameSpan = itemEl.querySelector('span:first-child');
                const hoverSpan = nameSpan ? nameSpan.querySelector('.range-hover-value') : null;
                if (hoverSpan) {
                    hoverSpan.textContent = `: ${val.toFixed(val % 1 === 0 ? 0 : 2)}`;
                }
            }
        }
    }

    window.updateSlider = function(itemIndex, newValue) {
        const itemEl = itemsList.querySelector(`.menu-item[data-index="${itemIndex}"]`);
        if (!itemEl) return;

        const sliderContainer = itemEl.querySelector('.slider-component');
        if (!sliderContainer) return;

        const labelSpan = sliderContainer.querySelector('span');
        if (!labelSpan) return;

        const options = menuConfig[itemIndex].slider.options;
        if (!options || newValue < 1 || newValue > options.length) return;

        const newLabel = options[newValue - 1].label;
        labelSpan.textContent = newLabel;
    }

    window.updateCheckbox = function(itemIndex, isChecked) {
        const itemsContainer = document.getElementById('menu-items');
        const itemEl = itemsContainer.querySelector(`.menu-item[data-index="${itemIndex}"]`);
        if (itemEl) {
            const checkbox = itemEl.querySelector('input[type="checkbox"]');
            if (checkbox) {
                checkbox.checked = isChecked;
            }
        }
    }

    window.updateSelection = function(selectionIndex) {
        currentSelectionIndex = selectionIndex;

        requestAnimationFrame(() => {
            const itemElements = itemsList.querySelectorAll('.menu-item');
            if (itemElements.length === 0 || currentSelectionIndex < 0 || currentSelectionIndex >= itemElements.length) {
                selectionHighlight.style.display = 'none';
                return;
            }

            selectionHighlight.style.display = 'block';

            let currentOptionNumber = 0;
            let totalOptions = 0;
            
            for (let i = 0; i < menuConfig.length; i++) {
                if (!menuConfig[i].separator) {
                    totalOptions++;
                }
            }
            
            for (let i = 0; i <= currentSelectionIndex; i++) {
                if (i < menuConfig.length && !menuConfig[i].separator) {
                    currentOptionNumber++;
                }
            }
            
            const footerRight = document.getElementById('footer-right');
            if (footerRight) {
                footerRight.textContent = `${currentOptionNumber}/${totalOptions}`;
            }

            const menuItemsContainer = document.getElementById('menu-items');
            const selectedElement = itemElements[currentSelectionIndex];

            let itemHeightPx = 0;
            if (selectedElement) {
                itemHeightPx = selectedElement.offsetHeight;
            } else if (itemElements.length > 0) {
                itemHeightPx = itemElements[0].offsetHeight;
            }

            if (itemHeightPx === 0 && menuItemsContainer && itemElements.length > 0) {
                itemHeightPx = menuItemsContainer.offsetHeight / itemElements.length;
            }

            const containerHeightPx = menuItemsContainer ? menuItemsContainer.offsetHeight : 0;
            const maxVisibleItems = (containerHeightPx > 0 && itemHeightPx > 0) ? Math.floor(containerHeightPx / itemHeightPx) : itemElements.length;
            const totalItems = itemElements.length;
            const selectedElementTop = selectedElement ? selectedElement.offsetTop : (currentSelectionIndex * itemHeightPx);

            let selectedElementBottom;
            if (selectedElement) {
                const nextElement = itemElements[currentSelectionIndex + 1];
                if (nextElement) {
                    selectedElementBottom = nextElement.offsetTop;
                } else {
                    selectedElementBottom = selectedElement.offsetTop + selectedElement.offsetHeight;
                }
            } else {
                selectedElementBottom = selectedElementTop + itemHeightPx;
            }

            const visibleTop = scrollOffset;
            const visibleBottom = scrollOffset + containerHeightPx;

            if (selectedElementTop < visibleTop) {
                scrollOffset = selectedElementTop;
            } else if (selectedElementBottom > visibleBottom) {
                scrollOffset = selectedElementBottom - containerHeightPx;
            }

            let maxScroll = 0;
            if (itemElements.length > 0) {
                const lastElement = itemElements[itemElements.length - 1];
                const lastElementBottom = lastElement.offsetTop + lastElement.offsetHeight;
                maxScroll = Math.max(0, lastElementBottom - containerHeightPx);
            }

            scrollOffset = Math.max(0, Math.min(scrollOffset, maxScroll));

            itemsList.style.transform = `translateY(-${scrollOffset}px)`;

            if (selectedElement) {
                const highlightTop = selectedElementTop - scrollOffset;
                selectionHighlight.style.top = `${highlightTop}px`;
            }

            const menuScrollbar = document.getElementById('menu-scrollbar');
            if (totalItems > maxVisibleItems) {                
                const totalContentHeightPx = totalItems * itemHeightPx;
                
                const scrollbarTrack = document.getElementById('scrollbar-track');
                scrollbarTrack.style.height = `${containerHeightPx}px`;
                
                const thumbHeightPx = Math.max(20, (containerHeightPx / totalContentHeightPx) * containerHeightPx);
                
                const maxThumbTop = containerHeightPx - thumbHeightPx;
                const scrollPercentage = maxScroll > 0 ? scrollOffset / maxScroll : 0;
                const thumbTopPx = scrollPercentage * maxThumbTop;
                
                scrollbarThumb.style.height = `${thumbHeightPx}px`;
                scrollbarThumb.style.top = `${thumbTopPx}px`;
            } else {                
                const scrollbarTrack = document.getElementById('scrollbar-track');
                scrollbarTrack.style.height = `${containerHeightPx}px`;
                scrollbarThumb.style.height = `${containerHeightPx}px`;
                scrollbarThumb.style.top = '0px';
            }
        });
    };

