                iconImg.className = 'icon-image';
                iconImg.src = item.icon;
                iconImg.alt = 'Option icon';
                iconImg.onerror = function() {
                    this.style.display = 'none';
                };
                iconDiv.appendChild(iconImg);
                componentsContainer.appendChild(iconDiv);
            }

            if (item.checkbox && !item.range && !item.slider) {
                const componentDiv = document.createElement('div');
                componentDiv.className = 'component';
                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.checked = item.checkbox.checked;
                componentDiv.appendChild(checkbox);
                componentsContainer.appendChild(componentDiv);
            }

            if (item.range) {
                const componentDiv = document.createElement('div');
                componentDiv.className = 'component';

                const rangeContainer = document.createElement('div');
                rangeContainer.className = 'range-component';

                const rangeTrack = document.createElement('div');
                rangeTrack.className = 'range-track';

                const rangeFill = document.createElement('div');
                rangeFill.className = 'range-fill';

                const rangeValue = document.createElement('div');
                rangeValue.className = 'range-value';

                const rangeInput = document.createElement('input');
                rangeInput.type = 'range';
                rangeInput.min = item.range.min;
                rangeInput.max = item.range.max;
                rangeInput.step = item.range.step;
                rangeInput.value = item.range.value;

                const updateRangeUI = (target) => {
                    const min = parseFloat(target.min);
                    const max = parseFloat(target.max);
                    const val = parseFloat(target.value);
                    const percentage = ((val - min) * 100) / (max - min);
                    rangeFill.style.width = `${percentage}%`;
                    rangeValue.textContent = val.toFixed(val % 1 === 0 ? 0 : 2);
                    
                    const thumbStyle = window.getComputedStyle(target, '::-webkit-slider-thumb');
                    const thumbWidth = parseFloat(thumbStyle.width) || 0;
                    const trackWidth = target.offsetWidth;
                    const thumbPosition = (percentage / 100) * (trackWidth - thumbWidth) + (thumbWidth / 2);
                    rangeValue.style.left = `${thumbPosition}px`;
                };

                rangeInput.addEventListener('input', (e) => {
                    updateRangeUI(e.target);
                });

                rangeInput.addEventListener('change', (e) => {
                    updateRangeUI(e.target);
                });

                rangeContainer.appendChild(rangeTrack);
                rangeContainer.appendChild(rangeFill);
                rangeContainer.appendChild(rangeValue);
                rangeContainer.appendChild(rangeInput);
                componentDiv.appendChild(rangeContainer);
                componentsContainer.appendChild(componentDiv);

                setTimeout(() => updateRangeUI(rangeInput), 0);
            }

            if (item.slider) {
                const componentDiv = document.createElement('div');
                componentDiv.className = 'component';
                
                const sliderContainer = document.createElement('div');
                sliderContainer.className = 'slider-component';
                
                const leftArrow = document.createElement('div');
                leftArrow.className = 'arrow';
                leftArrow.innerHTML = '&lt;';
                
                const labelSpan = document.createElement('span');
                const initialOption = item.slider.options[item.slider.value - 1];
                labelSpan.textContent = initialOption ? initialOption.label : 'N/A';
                
                const rightArrow = document.createElement('div');
                rightArrow.className = 'arrow';
                rightArrow.innerHTML = '&gt;';
                
                sliderContainer.appendChild(leftArrow);
                sliderContainer.appendChild(labelSpan);
                sliderContainer.appendChild(rightArrow);
                
                componentDiv.appendChild(sliderContainer);
                componentsContainer.appendChild(componentDiv);
            }

            if (item.button) {
                const componentDiv = document.createElement('div');
                componentDiv.className = 'component';
                const button = document.createElement('button');
                button.textContent = item.button.label;
                componentDiv.appendChild(button);
                componentsContainer.appendChild(componentDiv);
            }

            if (item.checkbox && (item.range || item.slider)) {
                const componentDiv = document.createElement('div');
                componentDiv.className = 'component';
                const checkbox = document.createElement('input');
                checkbox.type = 'checkbox';
                checkbox.checked = item.checkbox.checked;
                componentDiv.appendChild(checkbox);
                componentsContainer.appendChild(componentDiv);
            }

            if (componentsContainer.hasChildNodes()) {
                itemEl.appendChild(componentsContainer);
            }
            
            itemsList.appendChild(itemEl);
        });
    };

