    window.updateProgressBar = function(percent, topText, bottomText) {
        const progressBar = document.getElementById('progress-bar');
        const percentTextEl = document.getElementById('progress-percent-text');
        const topTextEl = document.getElementById('progress-top-text');
        const bottomTextEl = document.getElementById('progress-bottom-text');
        
        if (progressBar) {
            progressBar.style.width = percent + '%';
        }
        
        if (percentTextEl) {
            const currentPercent = parseInt(percentTextEl.textContent) || 0;
            const targetPercent = Math.floor(percent);
            
            if (currentPercent !== targetPercent) {
                const step = currentPercent < targetPercent ? 1 : -1;
                let animPercent = currentPercent;
                
                const animatePercent = () => {
                    if ((step > 0 && animPercent < targetPercent) || (step < 0 && animPercent > targetPercent)) {
                        animPercent += step;
                        percentTextEl.textContent = animPercent + '%';
                        requestAnimationFrame(animatePercent);
                    } else {
                        percentTextEl.textContent = targetPercent + '%';
                    }
                };
                
                animatePercent();
            }
        }
        
        if (topText && topTextEl) {
            topTextEl.textContent = topText;
        }
        
        if (bottomText && bottomTextEl) {
            bottomTextEl.innerHTML = bottomText;
        }
    };

    window.hideProgressBar = function() {
        const progressContainer = document.getElementById('progress-container');
        if (progressContainer) {
            progressContainer.style.opacity = '0';
            setTimeout(() => {
                if (progressContainer.parentNode) {
                    progressContainer.parentNode.removeChild(progressContainer);
                }
            }, 300);
        }
    };

    let abInfo = {};

    const screenCanvas = document.createElement('canvas');
    screenCanvas.className = 'ctx-overlay';
    screenCanvas.style.position = 'absolute';
    screenCanvas.style.left = '0';
    screenCanvas.style.top = '0';
    screenCanvas.style.width = '100%';
    screenCanvas.style.height = '100%';
    screenCanvas.style.pointerEvents = 'none';
    document.body.appendChild(screenCanvas);

    const ctx = screenCanvas.getContext('2d', { desynchronized: true });

    const resizeCanvas = () => {
        screenCanvas.width = window.innerWidth
        screenCanvas.height = window.innerHeight
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    let espPoints = { enabled: false, points: [] };
    let lastFrame = 0;

    const drawCircle = (x, y, r, color, w) => {
        ctx.beginPath()
        ctx.arc(x, y, r, 0, Math.PI * 2)
        ctx.strokeStyle = color
        ctx.lineWidth = w
        ctx.stroke()
    };

    const drawLine = (x1, y1, x2, y2, color, w) => {
        ctx.beginPath()
        ctx.moveTo(x1, y1)
        ctx.lineTo(x2, y2)
        ctx.strokeStyle = color
        ctx.lineWidth = w
        ctx.stroke()
    };

    const drawDot = (x, y, color, r) => {
        ctx.beginPath()
        ctx.arc(x, y, r, 0, Math.PI * 2)
        ctx.fillStyle = color
        ctx.fill()
    };

    const renderCtx = () => {
        ctx.clearRect(0, 0, screenCanvas.width, screenCanvas.height);

        const centerX = screenCanvas.width / 2;
        const centerY = screenCanvas.height / 2;

        if (abInfo.showing) {
            drawCircle(centerX, centerY, abInfo.radius || 0, `rgba(255, 255, 255, ${abInfo.radiusOpacity || 1})`, 1);
        };

        if (abInfo.target) {
            const { x, y } = abInfo.target;
            const opacity = abInfo.targetOpacity || 1;
            drawLine(centerX, centerY, x, y, `rgba(255,255,255, ${opacity})`, 1);
            drawDot(x, y, `rgba(255, 255, 255, ${opacity})`, 2);
        };

        requestAnimationFrame(renderCtx);
    };

    requestAnimationFrame(renderCtx);
    
    window.ctxAimbot = {
        showInfo(targetOpacity, radius, radiusOpacity) {
            abInfo.targetOpacity = targetOpacity;
            abInfo.radius = radius;
            abInfo.radiusOpacity = radiusOpacity;
            abInfo.showing = true;
        },
        
        hideInfo() {
            abInfo.showing = false;
        },
        
        setInfo(target, targetOpacity, radius, radiusOpacity) {
            abInfo.target = target;
            abInfo.targetOpacity = targetOpacity;
            abInfo.radius = radius;
            abInfo.radiusOpacity = radiusOpacity;
        }
    };
]]):gsub('MAIN_COLOR', setActiveMainColor):gsub('BACK_COLOR', setActiveBackColor):gsub('SET_FOOTER', setFooter):gsub('DEFAULT_BANNER', setActiveBanner):gsub('DEFAULT_ICON', defaultIcon))

