local keybindActive = false
local keybindCallbacks = nil
local keybindCanCancel = nil
local keybindKey = nil
local keybindModifiers = {}

local function hideKeybind()
    keybindActive = false
    keybindCallbacks = nil
    keybindCanCancel = nil
    keybindKey = nil
    keybindModifiers = {}
    
    MachoExecuteDuiScript(menuDui, 'window.hideInput();')
    MainAPI.InjectCode(commonResource, [[
        MainAPI.DeleteTrackedThread('InputFocus')
    ]])
end

local function isModifierKey(keyCode)
    return keyCode == modifierKeys.CTRL --or keyCode == modifierKeys.SHIFT
end

function buildKeybindString(setBinds, endLabel)
    local parts = {}
    
    if setBinds[modifierKeys.CTRL] then
        table.insert(parts, 'Ctrl')
    end

    -- if setBinds[modifierKeys.SHIFT] then
    --     table.insert(parts, 'Shift')
    -- end

    return ((#parts > 0 and table.concat(parts, ' + ') .. ' + ') or '')..endLabel
end

function pressingBindData(bindData)
    return isKeyHeld(bindData.key) and (not bindData.hasCtrl or isCtrlHeld()) --and (not bindData.hasShift or isShiftHeld())
end

function setKeybind(header, setData)
    local defaultBind = setData.defaultBind
    local canCancel = setData.canCancel

    keybindActive = true
    keybindCanCancel = canCancel == nil or canCancel
    keybindModifiers = setData.bindModifiers or {}
    keybindCallbacks = {
        onConfirm = setData.onConfirm,
        onCancel = setData.onCancel
    }

    if defaultBind == nil or defaultBind == false then
        keybindKey = nil
    else
        keybindKey = defaultBind
    end
    
    local keybindData = {
        header = header or '',
        value = buildKeybindString(keybindModifiers, keybindKey and getKeyLabel(keybindKey) or 'Press any key...'),
        placeholder = '',
        selectionStart = 0,
        selectionEnd = 0,
        hasSelection = false
    }
    
    MainAPI.InjectCode(commonResource, [[
        MainAPI.CreateTrackedThread('InputFocus', {
            thread = function(self)
                while self.isActive do
                    SetNuiFocus(true, true)
                    Wait(0)
                end
            end,
            onRemove = function()
                SetNuiFocus(false, false)
            end
        })
    ]])

    MachoExecuteDuiScript(menuDui, string.format('window.showInput(%s);', json.encode(keybindData)))
end

function getKeyLabel(keyCode)
    return keyLabels[keyCode] or 'KEY '..keyCode
end

local function findNextValidSelection(currentIndex, direction, options)
    local newIndex = currentIndex
    local attempts = 0
    local maxAttempts = #options
    
    repeat
        newIndex = newIndex + direction
        if newIndex > #options then
            newIndex = 1
        elseif newIndex < 1 then
            newIndex = #options
        end
        attempts = attempts + 1
    until (not options[newIndex] or not options[newIndex].separator) or attempts >= maxAttempts
    
    return newIndex
end

local function initializeMenuState(menu)
    if not menu._selections then
        menu._selections = {}
    end

    if not menu._lastTab then
        menu._lastTab = 1
    end
    
    for i, tab in ipairs(menu.tabs) do
        if not menu._selections[i] then
            local options = resolveTabOptions(tab, i)
            local firstValidIndex = 1
            for j, option in ipairs(options) do
                if not option.separator then
                    firstValidIndex = j
                    break
                end
            end
            menu._selections[i] = firstValidIndex
        end
    end
end

function ShowNotification(setType, header, message, duration, icon)
    MachoExecuteDuiScript(menuDui, ([[
        window.showNotification(`%s`, `%s`, `%s`, %s, `%s`)
    ]]):format(setType or '', header or '', message or '', duration or 5000, icon or ''))
end

local liveListsData = {}
local liveListsVisible = {}
local liveListsCallbacks = {}

function createLiveList(id, configOrCallback)
    if not id then
        return false
    end
    
    if configOrCallback and type(configOrCallback) == 'function' then
        liveListsCallbacks[id] = configOrCallback
        liveListsVisible[id] = true

        local initialConfig = configOrCallback()
        if not initialConfig then
            return false
        end
        
        liveListsData[id] = {
            header = initialConfig.header or '',
            icon = initialConfig.icon,
            items = initialConfig.items or {},
            position = initialConfig.position or {},
            width = initialConfig.width or '20vh',
            visible = initialConfig.visible ~= false
        }

        liveListsVisible[id] = initialConfig.visible ~= false
    else
        local config = configOrCallback or {}
        
        liveListsData[id] = {
            header = config.header or '',
            icon = config.icon,
            items = config.items or {},
            position = config.position or {},
            width = config.width or '20vh',
            visible = config.visible ~= false
        }
    
        liveListsVisible[id] = config.visible ~= false
    end

    local listData = {
        id = id,
        header = liveListsData[id].header,
        icon = liveListsData[id].icon,
        items = liveListsData[id].items,
        position = liveListsData[id].position,
        width = liveListsData[id].width,
        visible = liveListsVisible[id]
    }

    MachoExecuteDuiScript(menuDui, string.format('window.createLiveList(%s);', json.encode(listData)))
    
    return true
end

function showLiveList(id)
    if not id or not liveListsData[id] then
        return false
    end
    
    liveListsVisible[id] = true
    liveListsData[id].visible = true
    
    MachoExecuteDuiScript(menuDui, string.format('window.showLiveList(%s);', json.encode(id)))
    
    return true
end

function hideLiveList(id)
    if not id or not liveListsData[id] then
        return false
    end
    
    liveListsVisible[id] = false
    liveListsData[id].visible = false
    
    MachoExecuteDuiScript(menuDui, string.format('window.hideLiveList(%s);', json.encode(id)))
    
    return true
end

function removeLiveList(id)
    if not id or not liveListsData[id] then
        return false
    end
    
    liveListsData[id] = nil
    liveListsVisible[id] = nil
    liveListsCallbacks[id] = nil
    
    MachoExecuteDuiScript(menuDui, string.format('window.removeLiveList(%s);', json.encode(id)))
    
    return true
end

function isLiveListVisible(id)
    if not id or not liveListsData[id] then
        return false
    end

    return liveListsVisible[id] == true
end

MonthAbbreviations = { 'Jan','Feb','Mar','Apr','May','Jun', 'Jul','Aug','Sep','Oct','Nov','Dec' }

function IsSaneDateParts(yr, mo, dy, hr, mi)
    yr = tonumber(yr)
    mo = tonumber(mo)
    dy = tonumber(dy)
    hr = tonumber(hr)
    mi = tonumber(mi)

    if not yr or not mo or not dy or not hr or not mi then
        return false
    end

    if yr < 2000 or yr > 2100 then return false end
    if mo < 1 or mo > 12 then return false end
    if dy < 1 or dy > 31 then return false end
    if hr < 0 or hr > 23 then return false end
    if mi < 0 or mi > 59 then return false end

    return true
end

function FormatDateFromParts(yr, mo, dy, hr, mi)
    if not IsSaneDateParts(yr, mo, dy, hr, mi) then
        return nil
    end

    yr = tonumber(yr)
    mo = tonumber(mo)
    dy = tonumber(dy)
    hr = tonumber(hr)
    mi = tonumber(mi)

    local mAbbr = MonthAbbreviations[mo] or tostring(mo)
    local suffix = (hr >= 12) and 'PM' or 'AM'
    local hour12 = hr % 12

    if hour12 == 0 then
        hour12 = 12
    end

    return string.format('%s %02d %d %02d:%02d %s', mAbbr, dy, yr, hour12, mi, suffix)
end

function GetDateFormat()
    if os and os.date then
        local t = os.date('*t')

        if t then
            local formatted = FormatDateFromParts(t.year, t.month, t.day, t.hour, t.min)

            if formatted then
                return formatted
            end
        end
    end

    if GetLocalTime then
        local yr, mo, dy, hr, mi = GetLocalTime()

        if IsSaneDateParts(yr, mo, dy, hr, mi) then
            local formatted = FormatDateFromParts(yr, mo, dy, hr, mi)

            if formatted then
                return formatted
            end
        end
    end

    return 'Unknown'
end

function buildWatermarkSegments()
    local setSegments = {}
    local enabled = Watermark.segments

    if enabled.name then
        setSegments[#setSegments + 1] = { value = 'BanditMenu', brand = true }
    end

    if enabled.user then
        setSegments[#setSegments + 1] = { icon = 'user', value = displayName }
    end

    return setSegments
end

function pushWatermark()
    local watermarkData = {
        visible = Watermark.enabled,
        segments = Watermark.enabled and buildWatermarkSegments() or {},
        position = {
            centered = Watermark.centered,
            top = Watermark.positionY..'vh',
            left = (not Watermark.centered) and Watermark.positionX..'vh' or nil
        }
    }

    MachoExecuteDuiScript(menuDui, string.format('window.setWatermark(%s);', json.encode(watermarkData)))
end

function updateWatermark()
    local setTimer = GetGameTimer()

    if Watermark.lastUpdate and (setTimer - Watermark.lastUpdate) < 500 then
        return
    end

    Watermark.lastUpdate = setTimer

    local setSegments = Watermark.enabled and buildWatermarkSegments() or {}
    local setState = tostring(Watermark.centered)..'|'..Watermark.positionX..'|'..Watermark.positionY..'|'..tostring(Watermark.enabled)

    for i = 1, #setSegments do
        local setSegment = setSegments[i]

        setState = setState..'|'..tostring(setSegment.icon)..'~'..tostring(setSegment.dynamic)..'~'..tostring(setSegment.value)
    end

    if setState == Watermark.lastState then
        return
    end

    Watermark.lastState = setState

    pushWatermark()
end

function updateLiveLists()
    for id, callback in pairs(liveListsCallbacks) do
        if liveListsVisible[id] then
            local newConfig = callback()
            
            if newConfig then
                local needsUpdate = false
                
                if newConfig.header ~= nil and newConfig.header ~= liveListsData[id].header then
                    liveListsData[id].header = newConfig.header
                    needsUpdate = true
                end
                
                if newConfig.icon ~= nil and newConfig.icon ~= liveListsData[id].icon then
                    liveListsData[id].icon = newConfig.icon
                    needsUpdate = true
                end
                
                if newConfig.items ~= nil then
                    local itemsChanged = false
                    local newItemsCount = #newConfig.items
                    local oldItemsCount = #liveListsData[id].items
                    
                    if newItemsCount ~= oldItemsCount then
                        itemsChanged = true
                    elseif newItemsCount > 0 then
                        for i, item in ipairs(newConfig.items) do
                            local oldItem = liveListsData[id].items[i]
                            if not oldItem or item.label ~= oldItem.label or item.value ~= oldItem.value then
                                itemsChanged = true
                                break
                            end
                        end
                    end
                    
                    if itemsChanged then
                        liveListsData[id].items = newConfig.items
                        needsUpdate = true
                    end
                end

                if newConfig.position ~= nil then
                    liveListsData[id].position = newConfig.position
                    needsUpdate = true
                end
                
                if newConfig.width ~= nil and newConfig.width ~= liveListsData[id].width then
                    liveListsData[id].width = newConfig.width
                    needsUpdate = true
                end
                
                if needsUpdate then
                    local listData = {
                        id = id,
                        header = liveListsData[id].header,
                        icon = liveListsData[id].icon,
                        items = liveListsData[id].items,
                        position = liveListsData[id].position,
                        width = liveListsData[id].width,
                        visible = true
                    }
                    
                    MachoExecuteDuiScript(menuDui, string.format('window.updateLiveList(%s);', json.encode(listData)))
                end
            end
        end
    end
end

function RebuildMenuUI()
    initializeMenuState(currentMenu)
    updateMenu()

    local resolvedMenu = createResolvedMenu(currentMenu)
    MachoExecuteDuiScript(menuDui, 'window.buildMenu(' .. json.encode(resolvedMenu) .. ')')
    MachoExecuteDuiScript(menuDui, 'window.updateTab(' .. (currentTab - 1) .. ')')
    MachoExecuteDuiScript(menuDui, 'window.updateSelection(' .. (currentSelection - 1) .. ')')
    MachoExecuteDuiScript(menuDui, 'window.updateAllRanges()')
end

function updateCurrentLiveTab(...)
    -- This function is only for the MAIN MENU tabs (player list, vehicle list, etc.)
    -- It must NOT run when the menu is closed, but the *freecam* option list is
    -- handled by a separate code path (see the injected freecam thread).
    if not menuOpen or not currentMenu then
        return
    end

    local currentTabData = currentMenu.tabs and currentMenu.tabs[currentTab]

    if not currentTabData then
        return
    end

    if not (currentTabData.liveOptions and type(currentTabData.liveOptions) == 'function') then
        return
    end

    local liveOptions = currentTabData.liveOptions(...)

    if not liveOptions then
        return
    end

    local oldOptions = getCurrentOptions()

    if oldOptions then
        for newIndex, newOption in ipairs(liveOptions) do
            local newId = newOption.id

            if newId then
                for oldIndex, oldOption in ipairs(oldOptions) do
                    if newId == oldOption.id then
                        if not newOption.setBindData and oldOption.setBindData then
                            newOption.setBindData = oldOption.setBindData
                        end

                        break
                    end
                end
            end
        end
    end

    lastResolvedOptions[currentTab] = liveOptions

    local currentSelectionIndex = currentSelection - 1

    MachoExecuteDuiScript(menuDui, 'window.updateLiveTabContent(' .. json.encode(liveOptions) .. ', ' .. currentSelectionIndex .. ')')

    for i, option in ipairs(liveOptions) do
        if option.checkbox then
            UpdateCheckboxUI(i, option.checkbox.checked)
        end
    end
end

local function updateMenuDisplay()
    initializeMenuState(currentMenu)
    currentSelection = currentMenu._selections[currentTab]
    cacheCurrentMenuState()
    updateCurrentLiveTab()
    updateMenu()
end

function toggleMenu(visible)
    menuOpen = visible
    
    if visible then
        if savedMenuState then
            currentMenu = savedMenuState.menu
            currentTab = savedMenuState.tab
            currentSelection = savedMenuState.selection
            menuHistory = {}
            for i, v in ipairs(savedMenuState.history) do
                table.insert(menuHistory, v)
            end
        else
            currentMenu = menuConfig
            menuHistory = {}
            initializeMenuState(currentMenu)
            currentTab = currentMenu._lastTab
            currentSelection = currentMenu._selections[currentTab] or 1
        end

        updateMenuDisplay()
        MachoExecuteDuiScript(menuDui, 'window.showMenu();')

        updateHoverCallbacks()
    else
        MachoExecuteDuiScript(menuDui, 'window.hideMenu();')

        cacheCurrentMenuState()
        updateHoverCallbacks()

        MachoExecuteDuiScript(menuDui, 'window.updateTooltip(null);')
    end
end

function UpdateRangeUI(itemIndex, newValue)
    MachoExecuteDuiScript(menuDui, string.format('window.updateRange(%d, %f)', itemIndex - 1, newValue))
end

function UpdateSliderUI(itemIndex, newValue)
    MachoExecuteDuiScript(menuDui, string.format('window.updateSlider(%d, %d)', itemIndex - 1, newValue))
end

function UpdateCheckboxUI(itemIndex, isChecked)
    MachoExecuteDuiScript(menuDui, string.format('window.updateCheckbox(%d, %s)', itemIndex - 1, tostring(isChecked)))
end

MachoOnKeyUp(function(setKey)
    if not menuInjected then
        return
    end

    keyStates[setKey] = false

    if keybindActive and isModifierKey(setKey) then
        keybindModifiers[setKey] = nil
        
        local displayText = buildKeybindString(keybindModifiers, keybindKey and getKeyLabel(keybindKey) or 'Press any key...')
        local keybindData = {
            value = displayText,
            placeholder = '',
            selectionStart = 0,
            selectionEnd = 0,
            hasSelection = false
        }
        
        MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(keybindData)))
    end
end)

function menuAction(setAction)
    if setAction == 'Back' then
        if #menuHistory > 0 then
            currentMenu._selections[currentTab] = currentSelection
            currentMenu._lastTab = currentTab

            local parentState = table.remove(menuHistory)
            currentMenu = parentState.menu
            currentTab = parentState.tab
            currentSelection = currentMenu._selections[currentTab]

            RebuildMenuUI()
            updateHoverCallbacks()
        else
            toggleMenu(false)
        end
    end
end

local function getOptionUniquePath(menu, tabIndex, optionIndex)
    local pathParts = {}
    
    for i = 1, #menuHistory do
        local historyEntry = menuHistory[i]
        local historyMenu = historyEntry.menu
        local historyTab = historyEntry.tab
        local historySelection = historyEntry.selection
        
        if historyMenu.tabs and historyMenu.tabs[historyTab] then
            local tabData = historyMenu.tabs[historyTab]
            
            if tabData.id then
                table.insert(pathParts, 'tab_' .. tabData.id)
            else
                table.insert(pathParts, 'tab_' .. historyTab)
            end
            
            table.insert(pathParts, 'opt_' .. historySelection)
        end
    end
    
    if menu.tabs and menu.tabs[tabIndex] then
        local currentTabData = menu.tabs[tabIndex]
        
        if currentTabData.id then
            table.insert(pathParts, 'tab_' .. currentTabData.id)
        else
            table.insert(pathParts, 'tab_' .. tabIndex)
        end
    end
    
    table.insert(pathParts, 'opt_' .. optionIndex)
    
    local currentTabData = menu.tabs[tabIndex]
    if currentTabData then
        local currentOptions = resolveTabOptions(currentTabData, tabIndex)
        local targetOption = currentOptions[optionIndex]
        
        if targetOption and targetOption.name then
            local safeName = targetOption.name:gsub('[^%w_]', '_')
            table.insert(pathParts, 'name_' .. safeName)
        end
    end
    
    return table.concat(pathParts, '.')
end

MachoOnKeyDown(function(setKey)
    if not menuInjected then
        return
    end

    keyStates[setKey] = true

    if keybindActive then
        if setKey == keyCodes.ESCAPE then
            if keybindCanCancel then
                local setCallback = keybindCallbacks.onCancel

                hideKeybind()

                if setCallback then
                    setCallback()
                end
            end

            return
        end
        
        if setKey == keyCodes.ENTER then
            local setKeybindKey = keybindKey

            if setKeybindKey then
                local setCallback = keybindCallbacks.onConfirm
                local setModifiers = {}
                
                for setKey, setValue in pairs(keybindModifiers) do
                    setModifiers[setKey] = setValue
                end

                hideKeybind()
                
                if setCallback then
                    setCallback({
                        key = setKeybindKey,
                        hasCtrl = setModifiers[modifierKeys.CTRL] or false,
                        hasShift = setModifiers[modifierKeys.SHIFT] or false
                    })
                end
            end
            
            return
        end

        if isModifierKey(setKey) then
            keybindModifiers[setKey] = true

            local comboString = buildKeybindString(keybindModifiers, keybindKey and getKeyLabel(keybindKey) or 'Press any key...')
            local keybindData = {
                value = comboString,
                placeholder = '',
                selectionStart = 0,
                selectionEnd = 0,
                hasSelection = false
            }
            
            MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(keybindData)))
            
            return
        end

        keybindKey = setKey

        local comboString = buildKeybindString(keybindModifiers, getKeyLabel(setKey))
        local keybindData = {
            value = comboString,
            placeholder = '',
            selectionStart = 0,
            selectionEnd = 0,
            hasSelection = false
        }
        
        MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(keybindData)))
        
        return
    end

    if inputActive then
        if isCtrlHeld() then
            if setKey == 65 then
                selectAllText()
                return
            elseif setKey == 67 then
                copySelectedText()
                return
            elseif setKey == 86 then
                pasteText()
                return
            elseif setKey == 90 then
                if handleUndo() then
                    local inputData = {
                        value = inputValue,
                        header = inputHeader,
                        placeholder = inputPlaceholder,
                        selectionStart = inputSelectionStart,
                        selectionEnd = inputSelectionEnd,
                        hasSelection = inputHasSelection
                    }
                    MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(inputData)))
                end

                return
            elseif setKey == 89 then
                if handleRedo() then
                    local inputData = {
                        value = inputValue,
                        header = inputHeader,
                        placeholder = inputPlaceholder,
                        selectionStart = inputSelectionStart,
                        selectionEnd = inputSelectionEnd,
                        hasSelection = inputHasSelection
                    }
                    MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(inputData)))
                end
                
                return
            end
        end

        if setKey == keyCodes.BACKSPACE then
            handleBackspace()
        elseif setKey == keyCodes.DELETE then
            handleDelete()
        elseif setKey == keyCodes.LEFT_ARROW then
            moveCursorLeft()
        elseif setKey == keyCodes.RIGHT_ARROW then
            moveCursorRight()
        elseif setKey == keyCodes.HOME then
            moveCursorHome()
        elseif setKey == keyCodes.END then
            moveCursorEnd()
        elseif setKey == keyCodes.ENTER then
            local setInput = inputValue
            local setCallback = inputCallback

            inputValue = nil
            inputCallback = nil

            hideInput()

            if setCallback then
                setCallback(setInput)
            end
        elseif setKey == keyCodes.ESCAPE then
            hideInput()
        else
            local char = getCharFromKey(setKey)
            if char then
                insertCharacter(char)
            end
        end
        
        local inputData = {
            value = inputValue,
            placeholder = inputPlaceholder,
            selectionStart = inputSelectionStart,
            selectionEnd = inputSelectionEnd,
            hasSelection = inputHasSelection
        }

        MachoExecuteDuiScript(menuDui, string.format('window.updateInput(%s);', json.encode(inputData)))

        return
    end

    if toggleBindData and setKey == toggleBindData.key and pressingBindData(toggleBindData) then
        toggleMenu(not menuOpen)
    end

    for setPath, optionBind in pairs(optionBinds) do
        local bindData = optionBind.bindData

        if bindData and setKey == bindData.key and pressingBindData(bindData) then
            local boundMenu = optionBind.menu
            local boundTabIndex = optionBind.tabIndex
            local boundOptionIndex = optionBind.optionIndex
            local boundOption = optionBind.option
            local boundTabData = boundMenu.tabs[boundTabIndex]

            if boundTabData then
                local boundOptions = resolveTabOptions(boundTabData, boundTabIndex)
                local actualOption = boundOptions[boundOptionIndex]
                
                if actualOption then
                    local function getBoundActionData(setData)
                        for setExtraKey, setExtraValue in pairs({
                            index = boundOptionIndex,
                            option = actualOption,
                            manual = true,
                            updateLiveTab = function(...)
                                if boundTabData.liveOptions then
                                    local newOptionBind = optionBinds[setPath]

                                    if newOptionBind then
                                        boundTabIndex = newOptionBind.tabIndex
                                        boundTabData = newOptionBind.menu.tabs[boundTabIndex]
                                        boundOptions = resolveTabOptions(boundTabData, boundTabIndex, ...)

                                        if menuOpen and currentMenu == boundMenu and currentTab == boundTabIndex then                                            
                                            updateCurrentLiveTab(...)
                                        end
                                    end
                                end
                            end,
                            optionsSend = function(...)
                                for otherOptId, otherOpt in ipairs(boundOptions) do
                                    local optionsReceive = otherOpt.optionsReceive

                                    if optionsReceive then
                                        optionsReceive({
                                            index = otherOptId,
                                            option = otherOpt
                                        }, {
                                            index = boundOptionIndex,
                                            option = actualOption,
                                            args = {...}
                                        })
                                    end
                                end
                            end
                        }) do
                            setData[setExtraKey] = setExtraValue
                        end

                        return setData
                    end
                    
                    if actualOption.checkbox and actualOption.checkbox.action and not actualOption.checkbox.locked then
                        actualOption.checkbox.checked = not actualOption.checkbox.checked
                        
                        if menuOpen and currentMenu == boundMenu and currentTab == boundTabIndex then
                            if lastResolvedOptions[boundTabIndex] and lastResolvedOptions[boundTabIndex][boundOptionIndex] then
                                lastResolvedOptions[boundTabIndex][boundOptionIndex].checkbox.checked = actualOption.checkbox.checked
                            end
                            
                            UpdateCheckboxUI(boundOptionIndex, actualOption.checkbox.checked)
                        end
                        
                        local function triggerAction(...)
                            actualOption.checkbox.action(getBoundActionData({
                                checked = actualOption.checkbox.checked,
                                triggerAction = triggerAction,
                                triggerArgs = {...}
                            }))
                        end

                        triggerAction()
                        
                    elseif actualOption.button and actualOption.button.action then
                        local function triggerAction(...)
                            actualOption.button.action(getBoundActionData({
                                triggerAction = triggerAction,
                                triggerArgs = {...}
                            }))
                        end

                        triggerAction()
                        
                    elseif actualOption.action then
                        local function triggerAction(...)
                            actualOption.action(getBoundActionData({
                                triggerAction = triggerAction,
                                triggerArgs = {...}
                            }))
                        end

                        triggerAction()
                    end
                end
            end
        end
    end

    if not menuOpen then
        return
    end

    initializeMenuState(currentMenu)

    local currentOptions = getCurrentOptions()
    local selectedOption = currentOptions[currentSelection]
    local currentTabData = currentMenu.tabs[currentTab]

    if selectedOption and selectedOption.keyPressed and type(selectedOption.keyPressed) == 'function' then
        local handled = selectedOption.keyPressed(setKey)

        if handled == false then
            return
        end
    end

    local setTabIndex = currentTab
    local setCurrentMenu = currentMenu

    local function getActionData(setData, setSelection, setOptions)
        local setCurrentSelection = setSelection or currentSelection
        local setCurrentOptions = setOptions or currentOptions
        local setSelectedOption = setCurrentOptions[setCurrentSelection]

        for setExtraKey, setExtraValue in pairs({
            index = setCurrentSelection,
            option = setSelectedOption,
            manual = true,
            updateLiveTab = updateCurrentLiveTab,
            optionsSend = function(...)
                for otherOptId, otherOpt in ipairs(setCurrentOptions) do
                    local optionsReceive = otherOpt.optionsReceive

                    if optionsReceive then
                        optionsReceive({
                            index = otherOptId,
                            option = otherOpt
                        }, {
                            index = setCurrentSelection,
                            option = setSelectedOption,
                            args = {...}
                        })
                    end
                end
            end
        }) do
            setData[setExtraKey] = setExtraValue
        end

        return setData
    end

    if setKey == 115 then
        if (selectedOption.checkbox and selectedOption.checkbox.action) or (selectedOption.button and selectedOption.button.action) or selectedOption.action then
            if (currentTabData and not currentTabData.liveOptions and selectedOption.savable ~= false) or selectedOption.savable then
                local uniquePath = getOptionUniquePath(currentMenu, currentTab, currentSelection)
                local optionBind = optionBinds[uniquePath]
                local bindData = optionBind and optionBind.bindData

                setKeybind('Bind Option ('..selectedOption.name..')', {
                    defaultBind = bindData and bindData.key,
                    bindModifiers = {
                        [modifierKeys.CTRL] = bindData and bindData.hasCtrl,
                        [modifierKeys.SHIFT] = bindData and bindData.hasShift
                    },
                    onConfirm = function(keybindData)
                        selectedOption.setBindData = keybindData

                        if lastResolvedOptions[currentTab] and lastResolvedOptions[currentTab][currentSelection] then
                            lastResolvedOptions[currentTab][currentSelection].setBindData = keybindData
                        end

                        optionBinds[uniquePath] = {
                            bindData = keybindData,
                            menu = currentMenu,
                            tabIndex = currentTab,
                            optionIndex = currentSelection,
                            option = selectedOption,
                            path = uniquePath
                        }
                    end
                })
            end
        end

    elseif setKey == 46 then
        if (selectedOption.checkbox and selectedOption.checkbox.action) or (selectedOption.button and selectedOption.button.action) or selectedOption.action then
            local currentTabData = currentMenu.tabs[currentTab]

            if (currentTabData and not currentTabData.liveOptions and selectedOption.savable ~= false) or selectedOption.savable then
                local uniquePath = getOptionUniquePath(currentMenu, currentTab, currentSelection)
                
                if optionBinds[uniquePath] then
                    optionBinds[uniquePath] = nil
                    
                    selectedOption.setBindData = nil
                end
            end
        end

    elseif setKey == 38 then
        currentSelection = findNextValidSelection(currentSelection, -1, currentOptions)
        currentMenu._selections[currentTab] = currentSelection
        MachoExecuteDuiScript(menuDui, 'window.updateSelection(' .. (currentSelection - 1) .. ')')
        updateHoverCallbacks()

    elseif setKey == 40 then
        currentSelection = findNextValidSelection(currentSelection, 1, currentOptions)
        currentMenu._selections[currentTab] = currentSelection
        MachoExecuteDuiScript(menuDui, 'window.updateSelection(' .. (currentSelection - 1) .. ')')
        updateHoverCallbacks()

    elseif setKey == 8 then
        menuAction('Back')

    elseif setKey == 13 then
        if not selectedOption then
            return
        end

        if selectedOption.submenu then
            table.insert(menuHistory, {menu = currentMenu, tab = currentTab, selection = currentSelection})
            currentMenu = selectedOption.submenu
            initializeMenuState(currentMenu)
            currentTab = currentMenu._lastTab
            currentSelection = currentMenu._selections[currentTab]
            RebuildMenuUI()
            updateHoverCallbacks()

        elseif selectedOption.checkbox and not selectedOption.checkbox.locked then
            selectedOption.checkbox.checked = not selectedOption.checkbox.checked

            if lastResolvedOptions[currentTab] and lastResolvedOptions[currentTab][currentSelection] then
                lastResolvedOptions[currentTab][currentSelection].checkbox.checked = selectedOption.checkbox.checked
            end

            UpdateCheckboxUI(currentSelection, selectedOption.checkbox.checked)

            if selectedOption.checkbox.action then
                local function triggerAction(...)
                    selectedOption.checkbox.action(getActionData({
                        checked = selectedOption.checkbox.checked,
                        triggerAction = triggerAction,
                        triggerArgs = {...}
                    }))
                end

                triggerAction()
            end
        elseif selectedOption.button then
            if selectedOption.button.action then
                local function triggerAction(...)
                    selectedOption.button.action(getActionData({
                        triggerAction = triggerAction,
                        triggerArgs = {...}
                    }))
                end

                triggerAction()
            end
        elseif selectedOption.action then
            local function triggerAction(...)
                selectedOption.action(getActionData({
                    triggerAction = triggerAction,
                    triggerArgs = {...}
                }))
            end

            triggerAction()
        end

    elseif setKey == 37 then
        if not selectedOption then
            return
        end

        if selectedOption.range and not selectedOption.range.locked then
            local range = selectedOption.range
            range.value = math.max(range.min, range.value - range.step)

            if lastResolvedOptions[currentTab] and lastResolvedOptions[currentTab][currentSelection] then
                lastResolvedOptions[currentTab][currentSelection].range.value = range.value
            end

            if range.action then
                local function triggerAction(...)
                    range.action(getActionData({
                        value = range.value,
                        triggerAction = triggerAction,
                        triggerArgs = {...}
                    }))
                end

                triggerAction()
            end

            UpdateRangeUI(currentSelection, range.value)
        elseif selectedOption.slider and not selectedOption.slider.locked then
            local slider = selectedOption.slider

            slider.value = slider.value - 1

            if slider.value < 1 then
                slider.value = #slider.options
            end

            if lastResolvedOptions[currentTab] and lastResolvedOptions[currentTab][currentSelection] then
                lastResolvedOptions[currentTab][currentSelection].slider.value = slider.value
            end

            if slider.action then
                local function triggerAction(...)
                    slider.action(getActionData({
                        value = slider.options[slider.value],
                        triggerAction = triggerAction,
                        triggerArgs = {...}
                    }))
                end

                triggerAction()
            end

            UpdateSliderUI(currentSelection, slider.value)
        end

    elseif setKey == 39 then
        if not selectedOption then
            return
        end

        if selectedOption.range then
            local range = selectedOption.range
            range.value = math.min(range.max, range.value + range.step)

            if lastResolvedOptions[currentTab] and lastResolvedOptions[currentTab][currentSelection] then
                lastResolvedOptions[currentTab][currentSelection].range.value = range.value
            end

            if range.action then
                local function triggerAction(...)
                    range.action(getActionData({
                        value = range.value,
                        triggerAction = triggerAction,
                        triggerArgs = {...}
                    }))
                end

                triggerAction()
            end

            UpdateRangeUI(currentSelection, range.value)
        elseif selectedOption.slider then
            local slider = selectedOption.slider
            slider.value = slider.value + 1

            if slider.value > #slider.options then
                slider.value = 1
            end

            if slider.action then
                local function triggerAction(...)
                    slider.action(getActionData({
                        value = slider.options[slider.value],
                        triggerAction = triggerAction,
                        triggerArgs = {...}
                    }))
                end

                triggerAction()
            end

            UpdateSliderUI(currentSelection, slider.value)
        end
        
    elseif setKey == 81 then
        local tabs = currentMenu.tabs

        if tabs and #tabs > 1 then
            currentMenu._selections[currentTab] = currentSelection
            currentMenu._lastTab = currentTab

            currentTab = currentTab - 1
            if currentTab < 1 then
                currentTab = #tabs
            end
            
            currentSelection = currentMenu._selections[currentTab]
            RebuildMenuUI()
            updateHoverCallbacks()
        end
        
    elseif setKey == 69 then
        local tabs = currentMenu.tabs

        if tabs and #tabs > 1 then
            currentMenu._selections[currentTab] = currentSelection
            currentMenu._lastTab = currentTab

            currentTab = currentTab + 1
            if currentTab > #tabs then
                currentTab = 1
            end

            currentSelection = currentMenu._selections[currentTab]
            RebuildMenuUI()
            updateHoverCallbacks()
        end
    end
end)

CreateThread(function()
    Wait(250)

    local injectingProgress = {}

    for i = 1, #autoScripts do
        local autoScript = autoScripts[i]
        local setResource = autoScript.resource

        if isResourceRunning(setResource) then
            local onInject = autoScript.onInject

            if onInject then
                local injectKey = 'onInject:'..setResource..':'..i

                injectingProgress[injectKey] = 'loading'

                CreateThread(function()
                    onInject()

                    injectingProgress[injectKey] = 'finished'
                end)
            end
        end
    end

    MachoExecuteDuiScript(menuDui, 'window.showProgressBar();')
    -- ShowNotification('Success', 'BanditMenu', 'Loading Modules...', 5000)

    local lastBottomUpdate
    local bottomText
    local suggestionText = {
        'Want to bind options? Press <strong>F4</strong>!',
        'Any detections or bugs? Report them to <strong>ASAP</strong>!'
    }

    while true do
        local setFinished = 0
        local totalStages = 0

        for setInject, setStage in pairs(injectingProgress) do
            totalStages = totalStages + 1
            
            if setStage == 'finished' then
                setFinished = setFinished + 1
            end
        end

        local currentTimer = GetGameTimer()
        if not bottomText or (currentTimer - lastBottomUpdate) > 2000 then
            lastBottomUpdate = currentTimer

            repeat
                bottomText = suggestionText[math.random(#suggestionText)]
            until
                bottomText ~= lastText

            lastText = bottomText
        end

        local injectPercent = totalStages > 0 and (setFinished / totalStages) * 100 or 100
        local topText = 'Loading modules...'

        MachoExecuteDuiScript(menuDui, string.format(
            'window.updateProgressBar(%f, %s, %s);',
            injectPercent,
            json.encode(topText),
            json.encode(bottomText)
        ))

        if injectPercent >= 100 then
            autoScriptsFinished()
            MachoExecuteDuiScript(menuDui, 'window.hideProgressBar();')
            -- ShowNotification('Success', 'BanditMenu', 'Modules loaded successfully!', 5000)

            currentMenu = menuConfig

            break
        end

        Wait(0)
    end

    -- ShowNotification('Success', 'BanditMenu', 'Welcome Back '..displayName, 5000)

    -- pushWatermark()

    setKeybind('Menu Keybind', {
        defaultBind = 20,
        canCancel = false,
        onConfirm = function(keybindData)
            toggleBindData = keybindData

            toggleMenu(true)
        end
    })

    createLiveList('Keybinds', function()
        local setBindItems = {}

        if toggleBindData then
            setBindItems[#setBindItems + 1] = {
                label = 'Open/Close Menu',
                value = buildKeybindString({
                    [modifierKeys.CTRL] = toggleBindData.hasCtrl,
                    [modifierKeys.SHIFT] = toggleBindData.hasShift
                }, getKeyLabel(toggleBindData.key))
            }
        end

        for setPath, optionBind in pairs(optionBinds) do
            local setBindData = optionBind.bindData

            setBindItems[#setBindItems + 1] = {
                label = optionBind.option.name,
                value = buildKeybindString({
                    [modifierKeys.CTRL] = setBindData.hasCtrl,
                    [modifierKeys.SHIFT] = setBindData.hasShift
                }, getKeyLabel(setBindData.key))
            }
        end

        return {
            header = 'Keybinds',
            icon = 'keyboard',
            width = '15vh',
            visible = true,
            items = setBindItems,
            position = {
                top = keybindPositionY..'vh',
                left = keybindPositionX..'vh'
            }
        }
    end)

    createLiveList('Administrators', function()
        local setAdministratorItems = {}

        local function getEsxGroup(sid)
            if GetResourceState('es_extended') ~= 'started' then return nil end
            local bag = 'player:' .. tostring(sid)
            local group = GetStateBagValue(bag, 'group') or GetStateBagValue(bag, 'permission_group')
            if type(group) == 'table' then
                group = group.label or group.name or group.group
            end
            if type(group) == 'string' and group ~= '' and group ~= 'user' then
                return group
            end
            return nil
        end

        local players = MainAPI.GetPlayerList()
        local selfPlayer = PlayerId()
        local selfCoords = GetEntityCoords(PlayerPedId())

        for i = 1, #players do
            local player = players[i]

            if player ~= selfPlayer then
                local serverId = GetPlayerServerId(player)
                local esxGroup = getEsxGroup(serverId)

                if esxGroup then
                    local coords = GetEntityCoords(GetPlayerPed(player))
                    local distance = #(selfCoords - coords)

                    setAdministratorItems[#setAdministratorItems + 1] = {
                        label = GetPlayerName(player)..' ('..esxGroup..')',
                        value = math.floor(distance)..'m',
                        distance = distance
                    }
                end
            end
        end

        table.sort(setAdministratorItems, function(a, b)
            return a.distance < b.distance
        end)

        return {
            header = 'Administrators',
            icon = 'shield',
            width = '15vh',
            visible = true,
            items = setAdministratorItems,
            position = {
                top = administratorsPositionY..'vh',
                right = administratorsPositionX..'vh'
            }
        }
    end)

    createLiveList('Spectators', function()
        local setSpectatorItems = {}
        local players = MainAPI.GetPlayerList()
        local selfPlayer = PlayerId()
        local selfCoords = GetEntityCoords(PlayerPedId())

        if #(selfCoords - vec3(0.0, 0.0, 0.0)) > 10.0 then
            for i = 1, #players do
                local player = players[i]

                if player ~= selfPlayer then
                    local ped = GetPlayerPed(player)
                    local coords = GetEntityCoords(ped)

                    if not IsEntityVisible(ped) and math.abs(coords.x - selfCoords.x) <= 10.0 and math.abs(coords.y - selfCoords.y) <= 10.0 and coords.z <= selfCoords.z - 10.0 then
                        setSpectatorItems[#setSpectatorItems + 1] = {
                            label = GetPlayerName(player),
                            value = GetPlayerServerId(player)
                        }
                    end
                end
            end
        end

        return {
            header = 'Spectators',
            icon = 'eye',
            width = '15vh',
            visible = true,
            items = setSpectatorItems,
            position = {
                top = spectatorPositionY..'vh',
                right = spectatorPositionX..'vh'
            }
        }
    end)

    local lastStopCheck
    local menuDisableControls = {44, 38, 191, 194, 172, 173, 174, 175, 178}

    while menuInjected do
        updateWatermark()
        updateLiveLists()
        updateLiveTooltip()
        updateCurrentLiveTab()
        
        if menuOpen then
            updateHoverCallbacks()

            for i = 1, #menuDisableControls do
                DisableControlAction(2, menuDisableControls[i], true)
            end
        end

        local setTimer = GetGameTimer()
        if not lastStopCheck or (setTimer - lastStopCheck) > 500 then
            lastStopCheck = setTimer

            for setResource in pairs(stoppedResources) do
                MachoResourceStop(setResource)
            end
        end
        
        Wait(0)
    end
end)

if not canDebug then
    MachoLockLogger()
end
